  -- source id: 13
  (
    'da000001-0013-4000-8000-000000000001',
    'Virginia CARES, Inc.',
    'Virginia CARES (Community Action Reentry System) is a statewide network of community action agencies serving returning citizens since 1981, with pre-release programs in 15 prisons and 11 regional and local jails and post-release services in 43 Virginia localities. Local sites provide case management, job readiness training, peer support groups, emergency aid for food, clothing, transportation, and ID fees, and rights restoration help. Contact the central office to be routed to your local site.',
    'Virginia CARES (Community Action Reentry System) es una red estatal de agencias de acción comunitaria que sirve a ciudadanos que regresan desde 1981, con programas previos a la liberación en 15 prisiones y 11 cárceles regionales y locales, y servicios posteriores en 43 localidades de Virginia. Los sitios locales ofrecen manejo de casos, preparación laboral, grupos de apoyo entre pares, ayuda de emergencia para alimentos, ropa, transporte y tarifas de identificación, y restauración de derechos.',
    'c1000001-0017-4000-8000-000000000001',
    'Virginia',
    'Roanoke City',
    'Roanoke',
    '108 Henry Street NW',
    '540-342-9344',
    'https://www.vacares.org',
    NULL,
    'Central office Monday–Friday business hours; local site hours vary',
    'People incarcerated in Virginia state or federal prisons or local and regional jails, and people recently released who reside in Virginia; family members may also seek guidance.',
    'Personas encarceladas en prisiones estatales o federales de Virginia o en cárceles locales y regionales, y personas recién liberadas que residen en Virginia; los familiares también pueden buscar orientación.',
    'Call 540-342-9344 to find the Virginia CARES site serving your locality; phone referrals and walk-ins accepted at local sites; Spanish-language assistance available.',
    'Llame al 540-342-9344 para encontrar el sitio de Virginia CARES que sirve su localidad; los sitios locales aceptan referencias telefónicas y visitas sin cita; asistencia en español disponible.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Pre-release workshops', 'Post-release case management', 'Job readiness training', 'Emergency aid', 'Rights restoration assistance'],
    ARRAY['statewide', 'reentry', 'case-management', 'peer-support', 'employment', 'rights-restoration'],
    ARRAY['accepts_criminal_record'],
    false,
    'active'
