  -- source id: 14
  (
    'da000001-0014-4000-8000-000000000001',
    'Virginia DMV — ID Cards & DMV Connect',
    'The Virginia Department of Motor Vehicles issues the state ID cards and driver''s licenses needed for employment, housing, and benefits after release. Through the DMV Connect mobile program, DMV teams visit VADOC facilities so people can obtain a Virginia ID—including REAL ID—about six months before release, and DMV Connect also brings ID, vital records ordering, and license services to community sites statewide. Fees apply, with loans available for indigent individuals in custody.',
    'El Departamento de Vehículos Motorizados de Virginia emite las tarjetas de identificación estatales y licencias de conducir necesarias para empleo, vivienda y beneficios después de la liberación. Mediante el programa móvil DMV Connect, equipos del DMV visitan las instalaciones de VADOC para que las personas obtengan una identificación de Virginia—incluida REAL ID—unos seis meses antes de la liberación, y también llevan servicios de identificación y registros vitales a sitios comunitarios. Aplican tarifas.',
    'c1000001-0008-4000-8000-000000000001',
    'Virginia',
    'Statewide',
    NULL,
    NULL,
    NULL,
    'https://www.dmv.virginia.gov/locations/mobile-offices',
    NULL,
    'Customer service center and DMV Connect visit hours vary; check dmv.virginia.gov',
    'Virginia residents with required identity and residency documents; people in VADOC custody are scheduled through facility staff; standard DMV fees apply.',
    'Residentes de Virginia con los documentos requeridos de identidad y residencia; las personas en custodia de VADOC se programan a través del personal de la instalación; aplican tarifas estándar del DMV.',
    'Find DMV Connect visit schedules and customer service centers at dmv.virginia.gov; bring a certified birth certificate or passport plus proof of Virginia residency; DMV Connect can also order Virginia vital records by mail.',
    'Encuentre los horarios de visitas de DMV Connect y los centros de servicio en dmv.virginia.gov; traiga un certificado de nacimiento certificado o pasaporte más prueba de residencia en Virginia; DMV Connect también puede ordenar registros vitales por correo.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['State ID card issuance', 'REAL ID issuance', 'Driver''s license services', 'Vital records ordering', 'Mobile ID visits at correctional facilities'],
    ARRAY['statewide', 'id-documentation', 'DMV', 'drivers-license', 'DMV-connect', 'reentry'],
    ARRAY['accepts_criminal_record'],
    false,
    'active'
  ),
  -- source id: 15
  (
    'da000001-0015-4000-8000-000000000001',
    'Virginia Veteran & Family Support (VVFS) — Department of Veterans Services',
    'Virginia Veteran and Family Support is the Department of Veterans Services program that coordinates behavioral health, rehabilitative services, and community resources for veterans and their families statewide. Its Justice Involved Services program assigns Veteran Justice Specialists who connect justice-involved veterans—in veteran treatment court dockets, in jail or prison within 120 days of release, or on community supervision—to housing, employment, treatment, and VA benefits. VVFS is not a crisis line.',
    'Virginia Veteran and Family Support es el programa del Departamento de Servicios para Veteranos que coordina salud conductual, servicios de rehabilitación y recursos comunitarios para veteranos y sus familias en todo el estado. Su programa de Servicios para Personas Involucradas con la Justicia asigna especialistas que conectan a veteranos con antecedentes penales—en tribunales de tratamiento, en cárcel o prisión dentro de 120 días de la liberación, o bajo supervisión—con vivienda, empleo, tratamiento y beneficios del VA. No es una línea de crisis.',
    'c1000001-0014-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    '101 North 14th Street',
    '1-844-838-7838',
    'https://www.dvs.virginia.gov/benefits-services/veteran-and-family-support',
    NULL,
    'Monday–Friday business hours; services available in person, by phone, and virtually',
    'Virginia-resident veterans of any era regardless of discharge status, Virginia National Guard and Reserve members, transitioning service members, and their families and caregivers.',
    'Veteranos residentes de Virginia de cualquier época sin importar el tipo de baja, miembros de la Guardia Nacional y la Reserva de Virginia, militares en transición y sus familias y cuidadores.',
    'Request services at vvn.dvs.virginia.gov or call 1-844-838-7838; for the Justice Involved Services program call 804-225-4734 or email justice.vvfs@dvs.virginia.gov; in crisis call or text 988.',
    'Solicite servicios en vvn.dvs.virginia.gov o llame al 1-844-838-7838; para el programa de Servicios para Personas Involucradas con la Justicia llame al 804-225-4734 o escriba a justice.vvfs@dvs.virginia.gov; en crisis llame o envíe un texto al 988.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Veteran Justice Specialist connections', 'Care coordination', 'Peer recovery support', 'VA benefits linkages', 'Housing and employment referrals'],
    ARRAY['statewide', 'veterans', 'justice-involved-veterans', 'VA-benefits', 'peer-support', 'reentry'],
    ARRAY[]::TEXT[],
    false,
    'active'
  ),
  -- source id: 16
  (
    'da000001-0016-4000-8000-000000000001',
    'Federation of Virginia Food Banks',
    'The Federation of Virginia Food Banks is the Feeding America state association coordinating Virginia''s seven regional food banks and more than 1,100 partner pantries and distribution sites across the Commonwealth. The federation supports food sourcing, SNAP outreach, and hunger advocacy so that every Virginia locality has access to a regional food bank network. The federation itself is a coordinating body—food is distributed through member food banks and their local partner agencies.',
    'La Federación de Bancos de Alimentos de Virginia es la asociación estatal de Feeding America que coordina los siete bancos de alimentos regionales de Virginia y más de 1,100 despensas y sitios de distribución asociados en todo el estado. La federación apoya el abastecimiento de alimentos, la difusión de SNAP y la defensa contra el hambre para que cada localidad tenga acceso a una red regional. La federación es un ente coordinador; los alimentos se distribuyen mediante los bancos miembros y sus agencias locales.',
    'c1000001-0007-4000-8000-000000000001',
    'Virginia',
    'Statewide',
    NULL,
    NULL,
    NULL,
    'https://vafoodbanks.org',
    NULL,
    'Member food bank and pantry hours vary',
    'Open to Virginians facing food insecurity through member food banks and partner pantries; pantry-level requirements vary by site.',
    'Abierto a virginianos con inseguridad alimentaria a través de los bancos de alimentos miembros y despensas asociadas; los requisitos varían según el sitio.',
    'Find your regional food bank at vafoodbanks.org; dial 211 to locate the nearest pantry; apply for SNAP through CommonHelp or call 855-635-4370.',
    'Encuentre su banco de alimentos regional en vafoodbanks.org; marque 211 para ubicar la despensa más cercana; solicite SNAP mediante CommonHelp o llame al 855-635-4370.',
    ARRAY[]::TEXT[],
    'statewide',
