  -- source id: 17
  (
    'da000001-0017-4000-8000-000000000001',
    'SAARA of Virginia — Peer Recovery Support',
    'SAARA of Virginia (Substance Abuse and Addiction Recovery Alliance) is the statewide recovery community organization providing peer-led recovery groups, warmline support, recovery advocacy, and training for Certified Peer Recovery Specialists. SAARA peers also serve Richmond-area behavioral health and criminal court dockets, supporting justice-involved participants one-on-one through recovery. SAARA offers peer support and education—not clinical treatment or detox services.',
    'SAARA of Virginia (Alianza de Recuperación de Adicciones y Abuso de Sustancias) es la organización comunitaria de recuperación estatal que ofrece grupos de recuperación dirigidos por pares, apoyo por línea cálida, defensa de la recuperación y capacitación para Especialistas Certificados en Recuperación entre Pares. Los pares de SAARA también sirven en tribunales conductuales y penales del área de Richmond, apoyando a participantes con antecedentes penales. SAARA ofrece apoyo entre pares y educación, no tratamiento clínico.',
    'c1000001-0012-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    '530 East Main Street, Suite 701',
    '804-762-4445',
    'https://www.saara.org',
    'info@saara.org',
    'Office Monday–Friday business hours; group schedules vary',
    'Open to Virginians in or seeking recovery from substance use disorders, their families, and community supporters; no criminal-record restrictions stated.',
    'Abierto a virginianos en recuperación o que buscan recuperarse de trastornos por uso de sustancias, sus familias y aliados comunitarios; sin restricciones de antecedentes penales indicadas.',
    'Visit saara.org for peer group schedules and CPRS training dates; SAARA affiliates operate in regions across Virginia including Richmond, Roanoke, Hampton Roads, and Northern Virginia.',
    'Visite saara.org para horarios de grupos de pares y fechas de capacitación CPRS; SAARA tiene afiliados en regiones de toda Virginia, incluidas Richmond, Roanoke, Hampton Roads y el norte de Virginia.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Peer-led recovery groups', 'Recovery warmline support', 'Peer Recovery Specialist training', 'Court docket peer support', 'Recovery advocacy'],
