  -- source id: 18
  (
    'da000001-0018-4000-8000-000000000001',
    'OAR of Richmond',
    'OAR of Richmond (Opportunity. Alliance. Reentry.) is the Richmond region''s lead reentry organization, providing person-centered transition services during and after incarceration in the Richmond, Henrico, Chesterfield, and Hanover jails and for people returning from state and federal custody. Case managers help with employment readiness, ID and document fees, clothing, transportation, and community referrals. Intake is available for people released within roughly the past six months.',
    'OAR of Richmond (Opportunity. Alliance. Reentry.) es la organización líder de reinserción de la región de Richmond, y ofrece servicios de transición centrados en la persona durante y después de la encarcelación en las cárceles de Richmond, Henrico, Chesterfield y Hanover y para quienes regresan de custodia estatal y federal. Los administradores de casos ayudan con preparación laboral, tarifas de identificación y documentos, ropa, transporte y referencias comunitarias. La admisión está disponible para personas liberadas en los últimos seis meses aproximadamente.',
    'c1000001-0017-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    '3111 West Clay Street',
    '804-643-2746',
    'https://www.oarric.org',
    'info@oarric.org',
    'Monday–Thursday, 8:30 a.m.–12:00 p.m. and 1:00–3:30 p.m.; closed Fridays',
    'Adults impacted by the criminal legal system returning to the Richmond region; post-release intake generally within six months of release.',
    'Adultos afectados por el sistema legal penal que regresan a la región de Richmond; la admisión posterior a la liberación generalmente es dentro de los seis meses posteriores a la liberación.',
    'Complete intake in person; visiting hours Monday–Thursday 8:30 a.m.–12:00 p.m. and 1:00–3:30 p.m.; closed Fridays; call 804-643-2746 before your first visit.',
    'Complete la admisión en persona; horario de visitas de lunes a jueves de 8:30 a.m. a 12:00 p.m. y de 1:00 a 3:30 p.m.; cerrado los viernes; llame al 804-643-2746 antes de su primera visita.',
    ARRAY['Richmond City', 'Henrico', 'Chesterfield', 'Hanover', 'Petersburg'],
    'multi',
