  -- source id: 19
  (
    'da000001-0019-4000-8000-000000000001',
    'REAL LIFE — Recovery & Reentry Program',
    'REAL LIFE is a Richmond nonprofit bridging incarceration, homelessness, and substance use disorder through eleven structured recovery houses, an East End community center, and intensive case management. Residents complete 20–30 hours of weekly programming using a behavior modification curriculum, then receive employment and education navigation with connections to more than 100 employer partners. The program primarily serves people in reentry from across Virginia and requires full participation.',
    'REAL LIFE es una organización sin fines de lucro de Richmond que atiende la encarcelación, la falta de vivienda y los trastornos por uso de sustancias mediante once casas de recuperación estructuradas, un centro comunitario en el East End y manejo intensivo de casos. Los residentes completan de 20 a 30 horas semanales de programación con un currículo de modificación de conducta, y luego reciben navegación de empleo y educación con conexiones a más de 100 empleadores aliados. Sirve principalmente a personas en reinserción de toda Virginia y requiere participación completa.',
    'c1000001-0002-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    NULL,
    NULL,
    'https://reallifeprogram.org',
    NULL,
    'Residential program 24/7; contact for community center hours',
    'Adults 18 and older exiting incarceration, homelessness, or addiction who are drug-free at entry and willing to commit to the structured residential program; participants come from across Virginia.',
    'Adultos de 18 años o más que salen de la encarcelación, la falta de vivienda o la adicción, libres de drogas al ingresar y dispuestos a comprometerse con el programa residencial estructurado; los participantes provienen de toda Virginia.',
    'Apply for recovery housing through the forms at reallifeprogram.org; an initial stabilization period restricts outside appointments before the employment search phase begins.',
    'Solicite vivienda de recuperación mediante los formularios en reallifeprogram.org; un período inicial de estabilización restringe las citas externas antes de que comience la fase de búsqueda de empleo.',
    ARRAY['Richmond City'],
    'single',
    ARRAY['Structured recovery housing', 'Intensive case management', 'Behavior modification programming', 'Employment navigation', 'Education support'],
    ARRAY['richmond', 'housing', 'recovery', 'reentry', 'SUD', 'case-management'],
    ARRAY['accepts_criminal_record'],
    false,
    'active'
  ),
  -- source id: 20
  (
    'da000001-0020-4000-8000-000000000001',
    'Boaz & Ruth — Transitional Jobs & Training',
    'Boaz & Ruth rebuilds lives and the Highland Park community in Richmond through a transitional jobs and training program for formerly incarcerated men and women. Trainees practice job and life skills in the organization''s social enterprises along the Highland Park commercial corridor, paired with mentoring, Jobs for Life classes, and community connection activities. Fewer than 10% of program graduates have returned to incarceration, and most gain full-time employment during or shortly after the program.',
    'Boaz & Ruth reconstruye vidas y la comunidad de Highland Park en Richmond mediante un programa de empleos transicionales y capacitación para hombres y mujeres anteriormente encarcelados. Los participantes practican habilidades laborales y de vida en las empresas sociales de la organización en el corredor comercial de Highland Park, junto con mentoría, clases Jobs for Life y actividades de conexión comunitaria. Menos del 10% de los graduados ha vuelto a la encarcelación y la mayoría obtiene empleo de tiempo completo.',
    'c1000001-0003-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    '3030 Meadowbridge Road',
    '804-329-4900',
    'https://www.boazandruth.com',
    NULL,
    'Monday–Friday business hours; enterprise hours vary',
    'Formerly incarcerated and unemployed or under-employed adults seeking transitional work and training; program-specific enrollment requirements apply.',
    'Adultos anteriormente encarcelados y desempleados o subempleados que buscan trabajo transicional y capacitación; aplican requisitos de inscripción específicos del programa.',
    'Call 804-329-4900 for training program enrollment; social enterprise sites in Highland Park serve as hands-on training labs.',
    'Llame al 804-329-4900 para inscribirse en el programa de capacitación; los sitios de empresas sociales en Highland Park sirven como laboratorios prácticos.',
    ARRAY['Richmond City'],
    'single',
