  -- source id: 21
  (
    'da000001-0021-4000-8000-000000000001',
    'CARITAS — The Healing Place',
    'The Healing Place is a long-term, peer-driven residential recovery program offered free of charge by CARITAS to men and women with substance use disorders in the greater Richmond area, including many people arriving directly from incarceration. The program combines on-demand residential recovery, workforce development, a transitional sober living community, and an active alumni network. Admission is first-come, first-served with an in-person pre-screening at the appropriate campus.',
    'The Healing Place es un programa residencial de recuperación a largo plazo, dirigido por pares y gratuito, ofrecido por CARITAS a hombres y mujeres con trastornos por uso de sustancias en el área metropolitana de Richmond, incluidas muchas personas que llegan directamente de la encarcelación. El programa combina recuperación residencial bajo demanda, desarrollo laboral, una comunidad de vivienda sobria transicional y una red activa de exalumnos. La admisión es por orden de llegada con una preevaluación en persona.',
    'c1000001-0005-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    '700 Dinwiddie Avenue',
    '804-230-1184',
    'https://caritasva.org/the-healing-place/',
    NULL,
    'Residential program 24/7; intake Monday–Friday business hours',
    'Adults 18 and older with substance use disorders able to physically participate; men served at the Dinwiddie Avenue campus and women at 2220 Stockton Street; no fee.',
    'Adultos de 18 años o más con trastornos por uso de sustancias capaces de participar físicamente; los hombres son atendidos en el campus de Dinwiddie Avenue y las mujeres en 2220 Stockton Street; sin costo.',
    'Call 804-230-1184 for the men''s program or 804-418-3049 for the women''s program; complete pre-screening in person at the campus; for emergency shelter call the Homeless Connection Line at 804-972-0813.',
    'Llame al 804-230-1184 para el programa de hombres o al 804-418-3049 para el de mujeres; complete la preevaluación en persona en el campus; para refugio de emergencia llame a la Homeless Connection Line al 804-972-0813.',
    ARRAY['Richmond City', 'Chesterfield', 'Henrico', 'Hanover'],
    'multi',
    ARRAY['Long-term residential recovery', 'Peer-driven programming', 'Workforce development', 'Transitional sober living', 'Alumni recovery support'],
    ARRAY['richmond', 'chesterfield', 'henrico', 'substance-use', 'recovery', 'housing', 'peer-support'],
    ARRAY[]::TEXT[],
    false,
    'active'
  ),
  -- source id: 22
  (
    'da000001-0022-4000-8000-000000000001',
    'CARITAS Works — Workforce Development',
    'CARITAS Works is a six-week intensive workforce development program in Richmond for adults with significant employment barriers, including criminal records, homelessness, and recovery histories. Participants build professional skills, practice interviewing, earn credentials, and connect with Richmond-area employers willing to hire program graduates. The program is part of the CARITAS continuum that also includes shelter, recovery, and furniture bank services for the region.',
    'CARITAS Works es un programa intensivo de desarrollo laboral de seis semanas en Richmond para adultos con barreras significativas de empleo, incluidos antecedentes penales, falta de vivienda e historiales de recuperación. Los participantes desarrollan habilidades profesionales, practican entrevistas, obtienen credenciales y se conectan con empleadores del área de Richmond dispuestos a contratar a los graduados. Forma parte del continuo de CARITAS, que también incluye refugio, recuperación y un banco de muebles.',
    'c1000001-0003-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    '2220 Stockton Street',
    '804-612-1752',
    'https://caritasva.org/i-need-help/',
    'mmilio@caritasva.org',
    'Class schedule varies by cohort; office Monday–Friday business hours',
    'Adults in the Richmond region with significant barriers to employment, including justice involvement, homelessness, or substance use recovery.',
    'Adultos de la región de Richmond con barreras significativas para el empleo, incluidas la participación en el sistema de justicia, la falta de vivienda o la recuperación del uso de sustancias.',
    'Contact mmilio@caritasva.org or 804-612-1752 to apply; cohorts run on a class schedule, so ask about the next start date.',
    'Contacte a mmilio@caritasva.org o al 804-612-1752 para solicitar; las cohortes siguen un calendario de clases, pregunte por la próxima fecha de inicio.',
    ARRAY['Richmond City', 'Chesterfield', 'Henrico', 'Hanover'],
    'multi',
    ARRAY['Six-week job readiness training', 'Professional skills classes', 'Interview preparation', 'Employer connections', 'Career coaching'],
    ARRAY['richmond', 'employment', 'job-training', 'fair-chance', 'reentry', 'workforce'],
    ARRAY['accepts_criminal_record'],
    false,
    'active'
  ),
  -- source id: 23
  (
    'da000001-0023-4000-8000-000000000001',
    'Goodwill of Central and Coastal Virginia — Reentry & Career Services',
    'Goodwill of Central and Coastal Virginia operates community employment centers across the Richmond region and Hampton Roads offering free career services with dedicated reentry support for citizens returning from incarceration. Staff help with career planning, resumes and interviews, disclosing a criminal record to employers, the federal bonding program, restoration of civil rights, and guidance on record expungement, plus job fairs that include fair-chance employers.',
    'Goodwill de Virginia Central y Costera opera centros comunitarios de empleo en la región de Richmond y Hampton Roads que ofrecen servicios de carrera gratuitos con apoyo dedicado de reinserción para ciudadanos que regresan de la encarcelación. El personal ayuda con planificación de carrera, currículums y entrevistas, cómo divulgar antecedentes penales a empleadores, el programa federal de fianzas, la restauración de derechos civiles y orientación sobre expungación, además de ferias de empleo con empleadores de segunda oportunidad.',
    'c1000001-0003-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    '6301 Midlothian Turnpike',
    '804-745-6300',
    'https://goodwillvirginia.org',
    NULL,
    'Monday–Friday, 8:00 a.m.–4:30 p.m.; center hours vary',
    'Job seekers with barriers to employment including criminal histories, disabilities, limited work experience, or outdated skills; services are free.',
    'Buscadores de empleo con barreras, incluidos antecedentes penales, discapacidades, experiencia laboral limitada o habilidades desactualizadas; los servicios son gratuitos.',
    'Call 804-745-6300 in Central Virginia or 757-248-9405 in Hampton Roads (1911 Saville Row, Hampton); registration required for reentry workshops.',
    'Llame al 804-745-6300 en Virginia Central o al 757-248-9405 en Hampton Roads (1911 Saville Row, Hampton); se requiere registro para los talleres de reinserción.',
    ARRAY['Richmond City', 'Henrico', 'Chesterfield', 'Hampton', 'Newport News', 'Norfolk'],
