  (
    'da000001-0024-4000-8000-000000000001',
    'Daily Planet Health Services',
    'Daily Planet Health Services is a federally qualified health center in Richmond serving people experiencing homelessness or housing instability—including many returning from incarceration—along with the broader community facing barriers to care. Integrated services include primary medical care, mental health and substance use disorder treatment, dental care, pharmacy counseling, case management, and medical respite, delivered across multiple sites regardless of insurance status.',
    'Daily Planet Health Services es un centro de salud calificado federalmente en Richmond que atiende a personas sin hogar o con inestabilidad de vivienda—incluidas muchas que regresan de la encarcelación—y a la comunidad en general que enfrenta barreras de atención. Los servicios integrados incluyen atención médica primaria, tratamiento de salud mental y uso de sustancias, atención dental, consejería de farmacia, manejo de casos y descanso médico, en varios sitios sin importar el estado del seguro.',
    'c1000001-0004-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    '517 West Grace Street',
    '804-783-2505',
    'https://dailyplanetva.org',
    NULL,
    'Monday–Friday, 8:30 a.m.–4:30 p.m.; 24/7 after-hours phone coverage',
    'Anyone regardless of housing, financial, or insurance status; primary population is people experiencing homelessness or housing instability; sliding fees determined at registration.',
    'Cualquier persona sin importar su situación de vivienda, financiera o de seguro; la población principal son personas sin hogar o con inestabilidad de vivienda; tarifas móviles determinadas al registrarse.',
    'Register in person 8–11:30 a.m. and 1–3 p.m. Monday–Friday or by phone at 804-783-2505; walk-in medical care at 511 West Grace Street; bring ID and proof of income if available.',
    'Regístrese en persona de 8 a 11:30 a.m. y de 1 a 3 p.m. de lunes a viernes o por teléfono al 804-783-2505; atención médica sin cita en 511 West Grace Street; traiga identificación y prueba de ingresos si las tiene.',
