  (
    'da000001-0025-4000-8000-000000000001',
    'Feed More — Central Virginia Food Bank',
    'Feed More is Central Virginia''s Feeding America food bank, collecting and distributing food through nearly 300 partner pantries, soup kitchens, and mobile distributions across a 34-locality service area stretching from the Northern Neck to the North Carolina border. Its Help Line connects neighbors—including people rebuilding after incarceration—to nearby food pantries and helps with SNAP applications. Feed More distributes through partners rather than serving walk-in clients at its warehouse.',
    'Feed More es el banco de alimentos de Feeding America para Virginia Central, y recolecta y distribuye alimentos a través de casi 300 despensas asociadas, comedores y distribuciones móviles en un área de servicio de 34 localidades que se extiende desde el Northern Neck hasta la frontera con Carolina del Norte. Su línea de ayuda conecta a los vecinos—incluidas personas que se reconstruyen tras la encarcelación—con despensas cercanas y ayuda con solicitudes de SNAP. Distribuye mediante aliados, no atiende directamente en su almacén.',
    'c1000001-0007-4000-8000-000000000001',
    'Virginia',
    'Henrico',
    'Richmond',
    '8020 Villa Park Drive',
    '804-521-2500',
    'https://feedmore.org',
