    'Help Line Monday–Friday, 9:00 a.m.–4:00 p.m.; pantry hours vary',
    'Residents of Feed More''s 34-city-and-county Central Virginia service area facing food insecurity; partner pantry requirements vary by site.',
    'Residentes del área de servicio de 34 ciudades y condados de Feed More en Virginia Central que enfrentan inseguridad alimentaria; los requisitos de las despensas asociadas varían según el sitio.',
    'Call the Help Line at 804-237-8617 (Mon–Fri 9 a.m.–4 p.m.) to find a nearby pantry or get SNAP application help; use the online agency locator at feedmore.org.',
    'Llame a la línea de ayuda al 804-237-8617 (lun–vie 9 a.m.–4 p.m.) para encontrar una despensa cercana u obtener ayuda con la solicitud de SNAP; use el localizador de agencias en feedmore.org.',
