  (
    'da000001-0026-4000-8000-000000000001',
    'The Fountain Fund — Central Virginia',
    'The Fountain Fund is a nonprofit lender providing low-interest microloans and financial coaching to formerly incarcerated people in Central Virginia, with lending based in Charlottesville and expanded into Richmond. Loans up to $5,000 for consumers (and larger amounts for businesses) can pay court debt, work expenses, transportation, rental move-in costs, or child support, at rates near 5% regardless of conviction type. Borrowers build credit while working toward self-determined goals.',
    'The Fountain Fund es un prestamista sin fines de lucro que ofrece microcréditos de bajo interés y asesoría financiera a personas anteriormente encarceladas en Virginia Central, con préstamos basados en Charlottesville y expandidos a Richmond. Los préstamos de hasta $5,000 para consumidores (y montos mayores para negocios) pueden pagar deudas judiciales, gastos laborales, transporte, costos de mudanza o manutención infantil, con tasas cercanas al 5% sin importar el tipo de condena. Los prestatarios construyen crédito.',
    'c1000001-0009-4000-8000-000000000001',
    'Virginia',
    'Charlottesville',
    'Charlottesville',
    NULL,
    NULL,
    'https://www.fountainfund.org',
    NULL,
    'Online inquiries 24/7; staff respond during business hours',
    'Formerly incarcerated adults in the Central Virginia lending area with a demonstrated ability to repay; no restrictions based on conviction type or length of incarceration.',
    'Adultos anteriormente encarcelados en el área de préstamos de Virginia Central con capacidad demostrada de pago; sin restricciones por tipo de condena o duración de la encarcelación.',
    'Submit the Central Virginia loan inquiry form at fountainfund.org; review the FAQs and lending policies first; an ACH automatic-payment discount lowers the rate to 3%.',
    'Envíe el formulario de consulta de préstamo de Virginia Central en fountainfund.org; revise primero las preguntas frecuentes y las políticas de préstamo; el descuento por pago automático ACH baja la tasa al 3%.',
    ARRAY['Charlottesville', 'Albemarle', 'Richmond City'],
