  (
    'da000001-0027-4000-8000-000000000001',
    'STEP UP, Inc. — Hampton Roads Reentry Employment',
    'STEP UP, Inc. is a Norfolk-based nonprofit providing pre-release and post-incarceration services across Hampton Roads, Western Tidewater, and nearby localities. Staff meet participants in jails and prisons before release and continue after return home with job skills training, resume help, employment placement, and referrals for housing, food, clothing, transportation, and treatment. Norfolk''s re-entry resource guides list STEP UP for justice-involved job training.',
    'STEP UP, Inc. es una organización sin fines de lucro con sede en Norfolk que ofrece servicios previos y posteriores a la encarcelación en Hampton Roads, Western Tidewater y localidades cercanas. El personal se reúne con participantes en cárceles y prisiones antes de la liberación y continúa después del regreso con capacitación laboral, ayuda con currículums, colocación de empleo y referencias de vivienda, alimentos, ropa, transporte y tratamiento.',
    'c1000001-0003-4000-8000-000000000001',
    'Virginia',
    'Norfolk',
    'Norfolk',
