    'People incarcerated in or released from correctional facilities who are returning to Hampton Roads localities; referrals from jails, prisons, probation, and community organizations accepted.',
    'Personas encarceladas o liberadas de instalaciones correccionales que regresan a las localidades de Hampton Roads; se aceptan referencias de cárceles, prisiones, probatoria y organizaciones comunitarias.',
    'Call 757-588-3151 or email info@stepupincorporated.org for intake; stepupincorporated.org was unavailable at re-audit—use phone or email. Pre-release participants are often enrolled through jail programming such as the Norfolk Sheriff''s Pathway programs.',
    'Llame al 757-588-3151 o escriba a info@stepupincorporated.org; stepupincorporated.org no estaba disponible en la reauditoría. Los participantes previos a la liberación a menudo se inscriben mediante programación carcelaria como Pathway del alguacil de Norfolk.',
