  (
    'da000001-0028-4000-8000-000000000001',
    'The Up Center — Family Support & Counseling',
    'The Up Center is a Norfolk-based nonprofit providing more than 20 support services for children and families across South Hampton Roads, including mental health and substance use counseling, fatherhood support through the Dad2Dads program, parenting education, youth mentoring, and housing and financial counseling. Families navigating a parent''s incarceration or reentry can access counseling and father-engagement programming; the center has historically run Second Chance Act fatherhood reentry programs.',
    'The Up Center es una organización sin fines de lucro con sede en Norfolk que ofrece más de 20 servicios de apoyo para niños y familias en South Hampton Roads, incluidos consejería de salud mental y uso de sustancias, apoyo a la paternidad mediante el programa Dad2Dads, educación para padres, mentoría juvenil y consejería de vivienda y finanzas. Las familias que atraviesan la encarcelación o reinserción de un padre pueden acceder a consejería y programas de participación paterna.',
    'c1000001-0011-4000-8000-000000000001',
