    'Call 757-354-3819 or use the new-client application at theupcenter.org; Dads Under Construction groups meet the first and third Tuesdays, 6–7:30 p.m.',
    'Llame al 757-354-3819 o use la solicitud de cliente nuevo en theupcenter.org; los grupos Dads Under Construction se reúnen el primer y tercer martes de 6 a 7:30 p.m.',
