  (
    'da000001-0029-4000-8000-000000000001',
    'Union Mission Ministries — Norfolk',
    'Union Mission Ministries operates Norfolk''s largest emergency shelter campus, open 24 hours with the Bashford Men''s Shelter, the Grace Place women''s shelter, and family accommodations. Guests receive meals, clothing, showers, case management, job-readiness and life-skills training, benefits assistance, and housing and employment referrals, with the RECLAIM transitional housing track for men needing longer support. The faith-based ministry cannot provide hotel vouchers or rent payments.',
    'Union Mission Ministries opera el campus de refugio de emergencia más grande de Norfolk, abierto las 24 horas, con el refugio para hombres Bashford, el refugio para mujeres Grace Place y alojamiento familiar. Los huéspedes reciben comidas, ropa, duchas, manejo de casos, capacitación laboral y de habilidades para la vida, asistencia con beneficios y referencias de vivienda y empleo, con el programa transicional RECLAIM para hombres que necesitan apoyo más prolongado. El ministerio no ofrece vales de hotel ni pagos de renta.',
    'c1000001-0002-4000-8000-000000000001',
    'Virginia',
    'Norfolk',
    'Norfolk',
    '5100 East Virginia Beach Boulevard',
    '757-627-8686',
    'https://www.unionmissionministries.org',
    NULL,
    'Open 24 hours daily',
    'Adults and families experiencing homelessness in the Norfolk area; no profession of faith required to receive shelter, meals, or services.',
    'Adultos y familias sin hogar en el área de Norfolk; no se requiere profesión de fe para recibir refugio, comidas o servicios.',
    'Call 757-627-8686 for shelter availability—ext. 200 for men, ext. 331 for women; the campus is open 24 hours; for regional housing crisis help call 757-587-4202.',
    'Llame al 757-627-8686 para disponibilidad de refugio—ext. 200 para hombres, ext. 331 para mujeres; el campus está abierto las 24 horas; para ayuda regional de crisis de vivienda llame al 757-587-4202.',
