  (
    'da000001-0030-4000-8000-000000000001',
    'Hampton Roads Community Health Center',
    'Hampton Roads Community Health Center is a federally qualified health center with clinics in Portsmouth and Norfolk providing primary medical care, dental care, behavioral health, and an in-house pharmacy with free prescription delivery. All sites schedule through one central number, and a mobile dental unit travels across Portsmouth, Norfolk, and Suffolk to reach low-income residents where they are. New patients, including uninsured adults returning from incarceration, are accepted with sliding fees.',
    'Hampton Roads Community Health Center es un centro de salud calificado federalmente con clínicas en Portsmouth y Norfolk que ofrece atención médica primaria, atención dental, salud conductual y una farmacia interna con entrega gratuita de recetas. Todos los sitios agendan mediante un número central, y una unidad dental móvil recorre Portsmouth, Norfolk y Suffolk para llegar a los residentes de bajos ingresos. Se aceptan pacientes nuevos, incluidos adultos sin seguro que regresan de la encarcelación, con tarifas móviles.',
    'c1000001-0004-4000-8000-000000000001',
    'Virginia',
    'Portsmouth',
