    'Monday–Friday, 7:30 a.m.–5:30 p.m.; site hours vary',
    'Open to Hampton Roads residents regardless of insurance status; sliding fee discounts based on income; Medicaid, Medicare, and private insurance accepted.',
    'Abierto a residentes de Hampton Roads sin importar el estado del seguro; descuentos de tarifa móvil según ingresos; se aceptan Medicaid, Medicare y seguros privados.',
    'Call 757-393-6363 to schedule at any location; the Portsmouth site at 1541 High Street offers medical, dental, behavioral health, and pharmacy under one roof.',
    'Llame al 757-393-6363 para agendar en cualquier ubicación; el sitio de Portsmouth en 1541 High Street ofrece servicios médicos, dentales, de salud conductual y farmacia en un solo lugar.',
