  (
    'da000001-0031-4000-8000-000000000001',
    'Foodbank of Southeastern Virginia and the Eastern Shore',
    'The Foodbank of Southeastern Virginia and the Eastern Shore is the Feeding America food bank serving eleven cities and counties across South Hampton Roads, Western Tidewater, and the Eastern Shore since 1981. It distributes food through a large network of partner pantries, mobile pantries, and community programs, and helps neighbors connect to SNAP and other benefits. Food reaches households through partner agencies located throughout the 4,745-square-mile service area.',
    'El Foodbank of Southeastern Virginia and the Eastern Shore es el banco de alimentos de Feeding America que sirve a once ciudades y condados de South Hampton Roads, Western Tidewater y la Costa Este desde 1981. Distribuye alimentos a través de una amplia red de despensas asociadas, despensas móviles y programas comunitarios, y ayuda a los vecinos a conectarse con SNAP y otros beneficios. Los alimentos llegan a los hogares mediante agencias asociadas en toda el área de servicio.',
