  (
    'da000001-0032-4000-8000-000000000001',
    'Virginia Peninsula Foodbank',
    'The Virginia Peninsula Foodbank in Hampton provides hunger relief across nine Peninsula and Middle Peninsula localities through more than 170 partner agencies including food pantries, soup kitchens, shelters, and community centers. Neighbors can shop the Community Pantry in Newport News, find partner pantries through the online locator, or arrange emergency food assistance by appointment. The foodbank also runs mobile distributions and nutrition programs for children, seniors, and veterans.',
    'El Virginia Peninsula Foodbank en Hampton brinda alivio contra el hambre en nueve localidades de la Península y la Península Media a través de más de 170 agencias asociadas, incluidas despensas, comedores, refugios y centros comunitarios. Los vecinos pueden usar la Despensa Comunitaria en Newport News, encontrar despensas asociadas con el localizador en línea o coordinar asistencia alimentaria de emergencia con cita. El banco también opera distribuciones móviles y programas de nutrición para niños, personas mayores y veteranos.',
    'c1000001-0007-4000-8000-000000000001',
    'Virginia',
    'Hampton',
    'Hampton',
    '2401 Aluminum Avenue',
    '757-596-7188',
    'https://hrfoodbank.org',
    NULL,
    'Office Monday–Friday business hours; emergency assistance 1:30–3:30 p.m. weekdays',
    'Residents of the Peninsula service area facing food insecurity; partner pantry requirements vary by site.',
    'Residentes del área de servicio de la Península que enfrentan inseguridad alimentaria; los requisitos de las despensas asociadas varían según el sitio.',
    'Visit the Community Pantry at 3509 Chestnut Avenue, Newport News during shopping hours; for emergency food call 757-596-7188 (Mon–Fri 1:30–3:30 p.m., appointments preferred).',
    'Visite la Despensa Comunitaria en 3509 Chestnut Avenue, Newport News durante el horario de compras; para alimentos de emergencia llame al 757-596-7188 (lun–vie 1:30–3:30 p.m., se prefieren citas).',
