  (
    'da000001-0033-4000-8000-000000000001',
    'Virginia Career Works — Norfolk Center',
    'The Virginia Career Works Norfolk center is the American Job Center serving the Hampton Roads workforce region with free job search assistance, career coaching, resume help, WIOA training referrals, and connections to hiring events. Staff serve all job seekers, including people with criminal records, and can point returning citizens to fair-chance employers, federal bonding, and the Work Opportunity Tax Credit that offsets hiring concerns for employers.',
    'El centro Virginia Career Works de Norfolk es el Centro de Empleo Americano que sirve a la región laboral de Hampton Roads con ayuda gratuita para buscar empleo, orientación profesional, ayuda con currículums, referencias a capacitación WIOA y conexiones con eventos de contratación. El personal atiende a todos los buscadores de empleo, incluidas personas con antecedentes penales, y puede orientar a los ciudadanos que regresan hacia empleadores de segunda oportunidad, fianzas federales y el crédito fiscal WOTC.',
    'c1000001-0003-4000-8000-000000000001',
