    'Open to job seekers in the Hampton Roads region including justice-involved individuals; core services are free.',
    'Abierto a buscadores de empleo en la región de Hampton Roads, incluidas personas con antecedentes penales; los servicios básicos son gratuitos.',
    'Check current hours through the center locator at virginiacareerworks.com/locations; register on the Virginia Workforce Connection before visiting to speed up services.',
    'Consulte los horarios actuales en el localizador de centros en virginiacareerworks.com/locations; regístrese en Virginia Workforce Connection antes de visitar para agilizar los servicios.',
