  (
    'da000001-0034-4000-8000-000000000001',
    'Virginia Career Works — Hampton Center',
    'The Virginia Career Works Hampton center is the American Job Center for the Virginia Peninsula, offering free job search tools, career counseling, skills workshops, WIOA-funded training referrals, and unemployment insurance assistance. Peninsula job seekers with criminal records can get help framing their history for employers and connecting to fair-chance hiring initiatives, GED referrals, and supportive services through partner agencies co-located with the center.',
    'El centro Virginia Career Works de Hampton es el Centro de Empleo Americano de la Península de Virginia, y ofrece herramientas gratuitas de búsqueda de empleo, consejería de carrera, talleres de habilidades, referencias a capacitación financiada por WIOA y asistencia con el seguro de desempleo. Los buscadores de empleo con antecedentes penales pueden recibir ayuda para presentar su historial a los empleadores y conectarse con iniciativas de contratación de segunda oportunidad, referencias de GED y servicios de apoyo.',
