  -- source id: 35
  (
    'da000001-0035-4000-8000-000000000001',
    'OAR of Arlington, Alexandria and Falls Church',
    'OAR of Arlington, Alexandria and Falls Church journeys with people impacted by the criminal legal system, running pre-release programs in the Arlington County Detention Facility, Alexandria''s Truesdale Adult Detention Center, and Coffeewood Correctional Center, plus post-release reentry support at its Arlington office. Services include transition coaching, employment help, housing assistance, phones and laptops, food, clothing, and a weekly support group, along with community service alternative sentencing.',
    'OAR de Arlington, Alexandria y Falls Church acompaña a personas afectadas por el sistema legal penal, con programas previos a la liberación en el Centro de Detención del Condado de Arlington, el Centro de Detención Truesdale de Alexandria y el Centro Correccional Coffeewood, además de apoyo de reinserción posterior a la liberación en su oficina de Arlington. Los servicios incluyen orientación de transición, ayuda de empleo, asistencia de vivienda, teléfonos y computadoras, alimentos, ropa y un grupo de apoyo semanal, junto con sentencias alternativas de servicio comunitario.',
    'c1000001-0017-4000-8000-000000000001',
    'Virginia',
    'Arlington',
    'Arlington',
    '1400 N. Uhle Street, Suite 704',
    '703-745-5441',
    'https://www.oaronline.org',
    'info@oaronline.org',
    'Monday–Friday business hours',
    'People returning to Arlington County, the City of Alexandria, or the City of Falls Church from incarceration and their families; post-release reentry referral generally within 90 days of release.',
    'Personas que regresan al Condado de Arlington, la Ciudad de Alexandria o la Ciudad de Falls Church tras la encarcelación y sus familias; la referencia de reinserción posterior a la liberación generalmente ocurre dentro de los 90 días posteriores a la liberación.',
    'Call 703-745-5441 or email info@oaronline.org; a separate organization, OAR NOVA, serves Fairfax, Loudoun, and Prince William counties.',
    'Llame al 703-745-5441 o escriba a info@oaronline.org; una organización separada, OAR NOVA, sirve a los condados de Fairfax, Loudoun y Prince William.',
