  -- source id: 36
  (
    'da000001-0036-4000-8000-000000000001',
    'Friends of Guest House — Women''s Reentry Program',
    'Friends of Guest House in Alexandria is Northern Virginia''s only 24/7 residential reentry program for women and the largest gender-responsive reentry program in Virginia. The free six-month residential program pairs each woman with a case manager for an individualized reentry plan covering healthcare, workforce development, life skills, GED tutoring, and family reconnection, followed by aftercare and a Second Chance transitional rental community. About 85% of graduates never return to incarceration.',
    'Friends of Guest House en Alexandria es el único programa residencial de reinserción 24/7 para mujeres en el norte de Virginia y el programa de reinserción con enfoque de género más grande del estado. El programa residencial gratuito de seis meses asigna a cada mujer una administradora de casos con un plan individualizado que cubre atención médica, desarrollo laboral, habilidades para la vida, tutoría de GED y reconexión familiar, seguido de un programa de seguimiento y una comunidad transicional de renta. Cerca del 85% de las graduadas no vuelve a la encarcelación.',
    'c1000001-0002-4000-8000-000000000001',
    'Virginia',
    'Alexandria',
    'Alexandria',
    NULL,
    NULL,
    'https://friendsofguesthouse.org',
    NULL,
    'Residential program 24/7; office Monday–Friday business hours',
    'Women 18 and older on Virginia state probation or parole and in compliance with supervision terms; application includes a background check, physical exam, and phone interview.',
    'Mujeres de 18 años o más en probatoria o libertad condicional estatal de Virginia y en cumplimiento de los términos de supervisión; la solicitud incluye verificación de antecedentes, examen físico y entrevista telefónica.',
    'Submit the client application through friendsofguesthouse.org before release when possible; residents complete an intake evaluation with the Alexandria Community Services Board on arrival.',
    'Envíe la solicitud de cliente en friendsofguesthouse.org antes de la liberación cuando sea posible; las residentes completan una evaluación de admisión con la Junta de Servicios Comunitarios de Alexandria al llegar.',
