  (
    'da000001-0037-4000-8000-000000000001',
    'Legal Services of Northern Virginia',
    'Legal Services of Northern Virginia is a nonprofit law firm providing free civil legal help to low-income, elderly, and disabled residents across Northern Virginia, with offices in Fairfax, Arlington, Alexandria, Leesburg, and the Route 1 corridor. Practice areas include housing, consumer, family, benefits, and a Second Chances initiative addressing barriers tied to criminal records. LSNV handles civil matters only—not criminal defense—and screens all applicants for financial eligibility.',
    'Legal Services of Northern Virginia es un bufete sin fines de lucro que brinda ayuda legal civil gratuita a residentes de bajos ingresos, personas mayores y personas con discapacidades en el norte de Virginia, con oficinas en Fairfax, Arlington, Alexandria, Leesburg y el corredor de la Ruta 1. Las áreas de práctica incluyen vivienda, consumidor, familia, beneficios y una iniciativa de Segundas Oportunidades sobre barreras ligadas a antecedentes penales. LSNV atiende solo asuntos civiles y evalúa la elegibilidad financiera.',
    'c1000001-0006-4000-8000-000000000001',
    'Virginia',
    'Fairfax',
    'Fairfax',
    '10700 Page Avenue, Suite 100',
    '703-778-6800',
    'https://lsnv.org',
    'help@lsnv.org',
    'Intake Monday–Thursday, 9:30 a.m.–12:00 p.m. and 1:30–3:00 p.m.; online application 24/7',
    'Low-income, elderly, or disabled residents of Fairfax, Arlington, Loudoun, and Prince William counties and the cities of Alexandria, Falls Church, Fairfax, Manassas, and Manassas Park; financial eligibility screening required.',
    'Residentes de bajos ingresos, personas mayores o con discapacidades de los condados de Fairfax, Arlington, Loudoun y Prince William y las ciudades de Alexandria, Falls Church, Fairfax, Manassas y Manassas Park; se requiere evaluación de elegibilidad financiera.',
    'Apply online 24/7 at lsnv.org or call 703-778-6800 Monday–Thursday, 9:30 a.m.–12 p.m. and 1:30–3 p.m.; walk-in applications on Wednesdays only.',
    'Solicite en línea 24/7 en lsnv.org o llame al 703-778-6800 de lunes a jueves, de 9:30 a.m. a 12 p.m. y de 1:30 a 3 p.m.; solicitudes sin cita solo los miércoles.',
