  (
    'da000001-0038-4000-8000-000000000001',
    'Legal Aid Justice Center',
    'The Legal Aid Justice Center provides free civil legal help to financially eligible Virginians from offices in Charlottesville, Richmond, Petersburg, and Falls Church, with a criminal legal system practice that runs expungement clinics and helps people seal eligible records under Virginia''s record sealing laws taking effect July 1, 2026. LAJC also litigates on housing, benefits, immigration, and civil rights issues. It does not handle criminal defense cases.',
    'El Legal Aid Justice Center brinda ayuda legal civil gratuita a virginianos financieramente elegibles desde oficinas en Charlottesville, Richmond, Petersburg y Falls Church, con una práctica del sistema legal penal que realiza clínicas de expungación y ayuda a sellar antecedentes elegibles bajo las leyes de sellado de Virginia vigentes desde el 1 de julio de 2026. LAJC también litiga sobre vivienda, beneficios, inmigración y derechos civiles. No atiende casos de defensa penal.',
    'c1000001-0006-4000-8000-000000000001',
    'Virginia',
    'Charlottesville',
    'Charlottesville',
    '1000 Preston Avenue, Suite A',
    '434-977-0553',
    'https://www.justice4all.org',
