    'Intake Monday–Friday business hours; leave a voicemail for a callback',
    'Financially eligible residents of LAJC''s Charlottesville, Richmond, Petersburg, and Northern Virginia service areas, or people whose legal issue arose there; income screening applies.',
    'Residentes financieramente elegibles de las áreas de servicio de LAJC en Charlottesville, Richmond, Petersburg y el norte de Virginia, o personas cuyo asunto legal surgió allí; se aplica evaluación de ingresos.',
    'Call the office nearest you: Charlottesville 434-977-0553, Richmond 804-643-1086 (phone intakes Mon–Fri), Petersburg 804-862-2205, Falls Church 703-778-3450; watch justice4all.org for expungement clinic dates.',
    'Llame a la oficina más cercana: Charlottesville 434-977-0553, Richmond 804-643-1086 (admisión telefónica lun–vie), Petersburg 804-862-2205, Falls Church 703-778-3450; consulte justice4all.org para fechas de clínicas de expungación.',
