  (
    'da000001-0039-4000-8000-000000000001',
    'Central Virginia Legal Aid Society',
    'Central Virginia Legal Aid Society provides free civil legal assistance to low-income people in the cities of Richmond, Petersburg, Hopewell, Colonial Heights, and Charlottesville and fifteen surrounding counties. Attorneys and pro bono volunteers handle housing and eviction, public benefits, family law, consumer, and expungement-related civil matters, with offices in Richmond, Petersburg, and Charlottesville. CVLAS handles civil cases only and screens applicants for income eligibility.',
    'Central Virginia Legal Aid Society brinda asistencia legal civil gratuita a personas de bajos ingresos en las ciudades de Richmond, Petersburg, Hopewell, Colonial Heights y Charlottesville y quince condados circundantes. Abogados y voluntarios pro bono atienden vivienda y desalojos, beneficios públicos, derecho familiar, asuntos de consumidor y asuntos civiles relacionados con la expungación, con oficinas en Richmond, Petersburg y Charlottesville. CVLAS atiende solo casos civiles y evalúa la elegibilidad de ingresos.',
    'c1000001-0006-4000-8000-000000000001',
