    'Residentes de bajos ingresos del área de servicio de CVLAS o personas con problemas legales surgidos allí; generalmente aplican las pautas de ingresos LSC.',
    'Call Richmond 804-648-1012 or toll-free 800-868-1012; Charlottesville 434-296-8851 or 800-390-9982; Petersburg 804-862-1100; online intake available at cvlas.org.',
    'Llame a Richmond al 804-648-1012 o gratis al 800-868-1012; Charlottesville 434-296-8851 u 800-390-9982; Petersburg 804-862-1100; admisión en línea disponible en cvlas.org.',
