  -- source id: 40
  (
    'da000001-0040-4000-8000-000000000001',
    'Neighborhood Health — Northern Virginia FQHC',
    'Neighborhood Health is Northern Virginia''s leading federally qualified health center, serving more than 40,000 patients at 15 clinics across Alexandria, Arlington, and Fairfax County. Services include adult primary care, pediatrics, dental care, behavioral health, and pharmacy assistance, with sliding fee discounts for uninsured and underinsured patients and help enrolling in Medicaid. Returning citizens without coverage can establish primary and behavioral health care regardless of ability to pay.',
    'Neighborhood Health es el principal centro de salud calificado federalmente del norte de Virginia, y atiende a más de 40,000 pacientes en 15 clínicas en Alexandria, Arlington y el condado de Fairfax. Los servicios incluyen atención primaria para adultos, pediatría, atención dental, salud conductual y asistencia de farmacia, con descuentos de tarifa móvil para pacientes sin seguro y ayuda para inscribirse en Medicaid. Los ciudadanos que regresan sin cobertura pueden establecer atención primaria y conductual sin importar su capacidad de pago.',
    'c1000001-0004-4000-8000-000000000001',
    'Virginia',
    'Alexandria',
    'Alexandria',
    '2 East Glebe Road',
    NULL,
    'https://neighborhoodhealthva.org',
    NULL,
    'Clinic hours vary; evening and weekend options at some locations',
    'Open to all Northern Virginia residents regardless of insurance status; sliding fee discounts based on household income; Medicaid, Medicare, and most private insurance accepted.',
    'Abierto a todos los residentes del norte de Virginia sin importar el estado del seguro; descuentos de tarifa móvil según los ingresos del hogar; se aceptan Medicaid, Medicare y la mayoría de los seguros privados.',
    'Find the nearest clinic and appointment lines at neighborhoodhealthva.org; bring proof of income to apply for the sliding fee discount; same-day and next-day appointments available at some sites.',
    'Encuentre la clínica más cercana y las líneas de citas en neighborhoodhealthva.org; traiga prueba de ingresos para solicitar el descuento de tarifa móvil; algunos sitios ofrecen citas para el mismo día o el siguiente.',
