  (
    'da000001-0041-4000-8000-000000000001',
    'Virginia Career Works — Alexandria Center',
    'The Virginia Career Works Alexandria center on Cherokee Avenue is a Northern Virginia American Job Center offering free career counseling, job search assistance, workshops, WIOA training referrals, and access to hiring events for the Alexandria and Arlington area. Job seekers with criminal records receive the same free core services and can ask staff about fair-chance employers, federal bonding, and training scholarships that reduce barriers to reemployment after release.',
    'El centro Virginia Career Works de Alexandria en Cherokee Avenue es un Centro de Empleo Americano del norte de Virginia que ofrece consejería de carrera gratuita, ayuda para buscar empleo, talleres, referencias a capacitación WIOA y acceso a eventos de contratación para el área de Alexandria y Arlington. Los buscadores de empleo con antecedentes penales reciben los mismos servicios básicos gratuitos y pueden preguntar al personal sobre empleadores de segunda oportunidad, fianzas federales y becas de capacitación.',
    'c1000001-0003-4000-8000-000000000001',
    'Virginia',
    'Alexandria',
    'Alexandria',
    '5520 Cherokee Avenue, Suite 100',
    NULL,
    'https://virginiacareerworks.com/locations/',
    NULL,
    'Monday–Friday business hours; confirm via center locator',
    'Open to Northern Virginia job seekers including justice-involved individuals; core services are free.',
    'Abierto a buscadores de empleo del norte de Virginia, incluidas personas con antecedentes penales; los servicios básicos son gratuitos.',
    'Check current hours through the center locator at virginiacareerworks.com/locations; an Arlington County affiliate site at 2100 Washington Boulevard operates Thursdays only.',
    'Consulte los horarios actuales en el localizador de centros en virginiacareerworks.com/locations; un sitio afiliado del condado de Arlington en 2100 Washington Boulevard opera solo los jueves.',
    ARRAY['Alexandria'],
    'single',
