  (
    'da000001-0042-4000-8000-000000000001',
    'Virginia Career Works — Prince William Center',
    'The Virginia Career Works Prince William center in Woodbridge is the American Job Center serving greater Prince William County with free job search resources, career coaching, skills assessments, WIOA training referrals, and employer hiring events. Returning citizens in the Prince William, Manassas, and Manassas Park area can use the center''s computers and staffed assistance to rebuild work histories, connect with training funds, and reach employers open to fair-chance hiring.',
    'El centro Virginia Career Works de Prince William en Woodbridge es el Centro de Empleo Americano que sirve al área metropolitana del condado de Prince William con recursos gratuitos de búsqueda de empleo, orientación profesional, evaluaciones de habilidades, referencias a capacitación WIOA y eventos de contratación. Los ciudadanos que regresan en el área de Prince William, Manassas y Manassas Park pueden usar las computadoras y la asistencia del personal para reconstruir historiales laborales y llegar a empleadores abiertos a la contratación de segunda oportunidad.',
