    'Check current hours through the center locator at virginiacareerworks.com/locations; register on the Virginia Workforce Connection before visiting.',
    'Consulte los horarios actuales en el localizador de centros en virginiacareerworks.com/locations; regístrese en Virginia Workforce Connection antes de visitar.',
