  -- source id: 43
  (
    'da000001-0043-4000-8000-000000000001',
    'TAP — Total Action for Progress Reentry Programs',
    'Total Action for Progress, the Roanoke Valley''s community action agency, runs incarceration reentry programs including Virginia CARES, WINGS for women, and A Second Chance for the Alleghany Highlands. Staff help returning citizens within six months of release with job training and searches, interview preparation, transportation, and rights restoration, connecting participants to TAP''s wider housing, education, and financial services. Participants outside the service area may enroll if they can reach a TAP office.',
    'Total Action for Progress, la agencia de acción comunitaria del valle de Roanoke, opera programas de reinserción tras la encarcelación que incluyen Virginia CARES, WINGS para mujeres y A Second Chance para Alleghany Highlands. El personal ayuda a los ciudadanos que regresan dentro de los seis meses posteriores a la liberación con capacitación y búsqueda de empleo, preparación de entrevistas, transporte y restauración de derechos, conectándolos con los servicios más amplios de vivienda, educación y finanzas de TAP.',
    'c1000001-0017-4000-8000-000000000001',
    'Virginia',
    'Roanoke City',
    'Roanoke',
    '302 2nd Street SW',
    '540-777-4673',
    'https://tapintohope.org/program/reentry-program/',
    'info@tapintohope.org',
    'Monday–Friday business hours',
    'People within six months of release from incarceration, before or after release, living in the Roanoke Valley or Alleghany Highlands service areas or able to travel to a TAP office.',
    'Personas dentro de los seis meses previos o posteriores a la liberación de la encarcelación que viven en el valle de Roanoke o Alleghany Highlands o pueden trasladarse a una oficina de TAP.',
    'Call 540-777-4673 (540-777-HOPE) or use the contact form on the reentry program page; ask about WINGS for women and A Second Chance for Alleghany-area residents.',
    'Llame al 540-777-4673 (540-777-HOPE) o use el formulario de contacto en la página del programa de reinserción; pregunte por WINGS para mujeres y A Second Chance para residentes del área de Alleghany.',
