  -- source id: 44
  (
    'da000001-0044-4000-8000-000000000001',
    'TAP This Valley Works — Adult Education & Career Training',
    'This Valley Works is Total Action for Progress''s education and career development division, offering GED preparation, adult literacy, employment soft-skills classes, and the Center for Employment Training at the Roanoke Higher Education Center. Programs pair classes and certification preparation with coaches, advisors, and job placement partnerships with local employers, and they are designed for low-income adults including those rebuilding after incarceration. About 500 students graduate each year.',
    'This Valley Works es la división de educación y desarrollo profesional de Total Action for Progress, y ofrece preparación para el GED, alfabetización de adultos, clases de habilidades laborales y el Centro de Capacitación para el Empleo en el Roanoke Higher Education Center. Los programas combinan clases y preparación de certificaciones con tutores, asesores y alianzas de colocación laboral con empleadores locales, y están diseñados para adultos de bajos ingresos, incluidos quienes se reconstruyen tras la encarcelación.',
    'c1000001-0013-4000-8000-000000000001',
    'Virginia',
    'Roanoke City',
    'Roanoke',
    '108 N. Jefferson Street',
    '540-777-4673',
    'https://tapintohope.org',
    NULL,
    'Class schedules vary; office Monday–Friday business hours',
    'Low-income adults in the Roanoke Valley seeking GED preparation, literacy help, or career training; program-specific enrollment requirements apply.',
    'Adultos de bajos ingresos del valle de Roanoke que buscan preparación para el GED, ayuda de alfabetización o capacitación profesional; aplican requisitos de inscripción específicos del programa.',
    'Call 540-777-4673 to enroll; most classes meet at the Roanoke Higher Education Center; ask about certification test preparation and job placement support.',
    'Llame al 540-777-4673 para inscribirse; la mayoría de las clases se imparten en el Roanoke Higher Education Center; pregunte por la preparación de exámenes de certificación y el apoyo de colocación laboral.',
