  -- source id: 45
  (
    'da000001-0045-4000-8000-000000000001',
    'Rescue Mission of Roanoke',
    'The Rescue Mission of Roanoke is a comprehensive crisis intervention center open 365 days a year with 257 low-barrier emergency shelter beds for men, women, and families, three daily community meals open to anyone, a weekly food box distribution, the Fralin Free Clinic, and The Way Forward long-term residential recovery program supported by certified peer recovery specialists. No profession of faith is required to receive meals, shelter, medical care, or other services.',
    'La Rescue Mission de Roanoke es un centro integral de intervención en crisis abierto los 365 días del año, con 257 camas de refugio de emergencia de baja barrera para hombres, mujeres y familias, tres comidas comunitarias diarias abiertas a cualquiera, una distribución semanal de cajas de alimentos, la Clínica Gratuita Fralin y el programa residencial de recuperación a largo plazo The Way Forward apoyado por especialistas certificados en recuperación entre pares. No se requiere profesión de fe para recibir servicios.',
    'c1000001-0015-4000-8000-000000000001',
    'Virginia',
    'Roanoke City',
    'Roanoke',
    '402 Fourth Street SE',
    '540-343-7227',
    'https://rescuemission.net',
    NULL,
    'Meals daily; shelter intake daily from 3:00 p.m.; office Monday–Saturday',
    'Anyone in need may eat at the Mission; shelter guests must participate in case management to continue services; The Way Forward serves adults seeking recovery from substance use disorder.',
    'Cualquier persona necesitada puede comer en la Misión; los huéspedes del refugio deben participar en el manejo de casos para continuar los servicios; The Way Forward atiende a adultos que buscan recuperarse del trastorno por uso de sustancias.',
    'Shelter is open 3:00 p.m.–9:00 a.m. with daily intakes; call 540-343-7227; food boxes Wednesdays and Thursdays 1–3 p.m.; Fralin Free Clinic at 321 Tazewell Avenue SE, 540-777-7671.',
    'El refugio abre de 3:00 p.m. a 9:00 a.m. con admisiones diarias; llame al 540-343-7227; cajas de alimentos miércoles y jueves de 1 a 3 p.m.; Clínica Gratuita Fralin en 321 Tazewell Avenue SE, 540-777-7671.',
    ARRAY['Roanoke City', 'Roanoke', 'Salem', 'Covington', 'Alleghany', 'Botetourt', 'Craig', 'Floyd', 'Franklin'],
    'multi',
    ARRAY['Emergency shelter', 'Daily community meals', 'Food box distribution', 'Free medical clinic', 'Long-term residential recovery'],
    ARRAY['roanoke', 'basic-needs', 'shelter', 'meals', 'free-clinic', 'recovery'],
