  (
    'da000001-0046-4000-8000-000000000001',
    'Blue Ridge Legal Services',
    'Blue Ridge Legal Services is the nonprofit legal aid society providing free civil legal assistance to low-income residents of the Shenandoah and Roanoke Valleys through offices in Harrisonburg, Roanoke, Lexington, and Winchester plus a Staunton outreach site. Attorneys handle housing, public benefits, family, and consumer matters that stabilize households after incarceration, and the Roanoke office performs intake for the Legal Aid Society of Roanoke Valley as well. Civil matters only.',
    'Blue Ridge Legal Services es la sociedad de asistencia legal sin fines de lucro que brinda ayuda legal civil gratuita a residentes de bajos ingresos de los valles de Shenandoah y Roanoke mediante oficinas en Harrisonburg, Roanoke, Lexington y Winchester, además de un sitio de atención en Staunton. Los abogados atienden asuntos de vivienda, beneficios públicos, familia y consumidor que estabilizan a los hogares tras la encarcelación, y la oficina de Roanoke realiza la admisión también para la Legal Aid Society of Roanoke Valley. Solo asuntos civiles.',
    'c1000001-0006-4000-8000-000000000001',
    'Virginia',
    'Harrisonburg',
    'Harrisonburg',
    '204 N. High Street',
    '540-433-1830',
    'https://brls.org',
    NULL,
    'Intake hours vary by office; online application 24/7',
    'Low-income residents of the Shenandoah Valley and Roanoke Valley service area; income eligibility screening required.',
    'Residentes de bajos ingresos del área de servicio de los valles de Shenandoah y Roanoke; se requiere evaluación de elegibilidad de ingresos.',
    'Harrisonburg intake 540-433-1830 (Mon–Thu 9 a.m.–12:45 p.m.) or toll-free 800-237-0141; Roanoke office 540-344-2080; Lexington 540-463-7334; online applications accepted at brls.org.',
    'Admisión en Harrisonburg 540-433-1830 (lun–jue 9 a.m.–12:45 p.m.) o gratis al 800-237-0141; oficina de Roanoke 540-344-2080; Lexington 540-463-7334; se aceptan solicitudes en línea en brls.org.',
