  (
    'da000001-0047-4000-8000-000000000001',
    'Virginia Career Works — Roanoke Center',
    'The Virginia Career Works Roanoke center on South Jefferson Street is the American Job Center for the Roanoke Valley, providing free job search assistance, career coaching, workshops, WIOA training referrals, and hiring events. Staff serve all job seekers, including people returning from incarceration, and can connect returning citizens to fair-chance employers, federal bonding information, and partner programs such as TAP and Virginia CARES located nearby in downtown Roanoke.',
    'El centro Virginia Career Works de Roanoke en South Jefferson Street es el Centro de Empleo Americano del valle de Roanoke, y ofrece ayuda gratuita para buscar empleo, orientación profesional, talleres, referencias a capacitación WIOA y eventos de contratación. El personal atiende a todos los buscadores de empleo, incluidas las personas que regresan de la encarcelación, y puede conectarlos con empleadores de segunda oportunidad, información de fianzas federales y programas aliados como TAP y Virginia CARES en el centro de Roanoke.',
    'c1000001-0003-4000-8000-000000000001',
