  -- source id: 48
  (
    'da000001-0048-4000-8000-000000000001',
    'Miriam''s House — Lynchburg Housing Programs',
    'Miriam''s House works to end homelessness in the Lynchburg community through housing-first programs, including a family emergency shelter at 409 Magnolia Street opened in early 2026 and the Community First rapid re-housing program that pairs short-term rental assistance with in-home case management. Households leaving incarceration into homelessness can be screened through the community''s centralized intake line. Services focus on families with children, youth, and chronically homeless individuals.',
    'Miriam''s House trabaja para acabar con la falta de vivienda en la comunidad de Lynchburg mediante programas de vivienda primero, incluidos un refugio familiar de emergencia en 409 Magnolia Street abierto a inicios de 2026 y el programa de realojamiento rápido Community First, que combina asistencia de renta a corto plazo con manejo de casos en el hogar. Los hogares que salen de la encarcelación hacia la falta de vivienda pueden ser evaluados mediante la línea centralizada de admisión. Se enfoca en familias con niños, jóvenes y personas sin hogar crónicas.',
    'c1000001-0002-4000-8000-000000000001',
    'Virginia',
    'Lynchburg',
    'Lynchburg',
    NULL,
    '434-427-2442',
    'https://www.miriamshouse.org',
    NULL,
    'Intake line business hours; shelter operates 24/7',
    'Households experiencing homelessness in the Lynchburg community, with priority programs for families with children, unaccompanied youth, and chronically homeless individuals.',
    'Hogares sin vivienda en la comunidad de Lynchburg, con programas prioritarios para familias con niños, jóvenes no acompañados y personas sin hogar crónicas.',
    'Call the centralized homeless intake line (CHIA) at 434-427-2442 to be screened for shelter and housing programs; the family shelter provides case management, housing navigation, and basic needs.',
    'Llame a la línea centralizada de admisión (CHIA) al 434-427-2442 para ser evaluado para refugio y programas de vivienda; el refugio familiar ofrece manejo de casos, navegación de vivienda y necesidades básicas.',
    ARRAY['Lynchburg'],
    'single',
