  (
    'da000001-0049-4000-8000-000000000001',
    'Virginia Career Works — Lynchburg Center',
    'The Virginia Career Works Lynchburg center on Odd Fellows Road is the American Job Center for the Lynchburg region, offering free job search help, career coaching, skills workshops, WIOA-funded training referrals, and connections to area employers. People with criminal records returning to Lynchburg and surrounding counties can use center computers, get help explaining their history to employers, and ask about fair-chance hiring, federal bonding, and GED and training partners.',
    'El centro Virginia Career Works de Lynchburg en Odd Fellows Road es el Centro de Empleo Americano de la región de Lynchburg, y ofrece ayuda gratuita de búsqueda de empleo, orientación profesional, talleres de habilidades, referencias a capacitación financiada por WIOA y conexiones con empleadores del área. Las personas con antecedentes penales que regresan a Lynchburg y los condados circundantes pueden usar las computadoras del centro, recibir ayuda para explicar su historial a los empleadores y preguntar sobre contratación de segunda oportunidad y fianzas federales.',
    'c1000001-0003-4000-8000-000000000001',
