  -- source id: 50
  (
    'da000001-0050-4000-8000-000000000001',
    'The Haven — Charlottesville Day Shelter & Housing',
    'The Haven is a low-barrier day shelter at 112 West Market Street in downtown Charlottesville, open every morning of the year with breakfast, showers, laundry, a mailing address, storage, and computer access for anyone experiencing homelessness—including people just released from incarceration with nowhere to go. The Haven also administers Housing First programs (rapid re-housing, homelessness prevention, and a housing fund) and runs the region''s coordinated entry Homeless Information Line.',
    'The Haven es un refugio diurno de baja barrera en 112 West Market Street en el centro de Charlottesville, abierto todas las mañanas del año con desayuno, duchas, lavandería, dirección postal, almacenamiento y acceso a computadoras para cualquier persona sin hogar—incluidas personas recién liberadas de la encarcelación sin dónde ir. The Haven también administra programas de Vivienda Primero (realojamiento rápido, prevención de la falta de vivienda y un fondo de vivienda) y opera la Línea de Información para Personas sin Hogar de entrada coordinada de la región.',
    'c1000001-0015-4000-8000-000000000001',
    'Virginia',
    'Charlottesville',
    'Charlottesville',
    '112 West Market Street',
    '434-973-1234',
    'https://www.thehaven.org',
    'operations@thehaven.org',
    'Monday–Friday, 7:00 a.m.–5:00 p.m.; Saturday–Sunday, 7:00 a.m.–12:00 p.m.',
    'Day shelter open to anyone in need; housing program screening requires literal homelessness or imminent housing loss per coordinated entry criteria.',
    'Refugio diurno abierto a cualquier persona necesitada; la evaluación para programas de vivienda requiere falta de vivienda literal o pérdida inminente de vivienda según los criterios de entrada coordinada.',
    'Day shelter open Mon–Fri 7 a.m.–5 p.m. and weekends 7 a.m.–noon; for housing screening call the Homeless Information Line at 434-207-2328 and leave a voicemail; for overnight shelter see PACEM.',
    'Refugio diurno abierto lun–vie de 7 a.m. a 5 p.m. y fines de semana de 7 a.m. a mediodía; para evaluación de vivienda llame a la Línea de Información al 434-207-2328 y deje un mensaje de voz; para refugio nocturno consulte PACEM.',
    ARRAY['Charlottesville', 'Albemarle', 'Fluvanna', 'Greene', 'Louisa', 'Nelson'],
