    'da000001-0051-4000-8000-000000000001',
    'Virginia Career Works — Charlottesville Center',
    'The Virginia Career Works Charlottesville center at Glenwood Station is the American Job Center for the Charlottesville area, offering free job search assistance, career coaching, workshops, WIOA training referrals, and employer hiring events. Justice-involved job seekers returning to Charlottesville and surrounding counties can access the same free services and ask staff about fair-chance employers, federal bonding, and reentry partners such as OAR and the Fountain Fund in the region.',
    'El centro Virginia Career Works de Charlottesville en Glenwood Station es el Centro de Empleo Americano del área de Charlottesville, y ofrece ayuda gratuita de búsqueda de empleo, orientación profesional, talleres, referencias a capacitación WIOA y eventos de contratación con empleadores. Los buscadores de empleo con antecedentes penales que regresan a Charlottesville y los condados circundantes pueden acceder a los mismos servicios gratuitos y preguntar al personal sobre empleadores de segunda oportunidad, fianzas federales y aliados de reinserción de la región.',
