  (
    'da000001-0052-4000-8000-000000000001',
    'Accomack Department of Social Services — Benefits & Family Support',
    'Accomack Department of Social Services — Benefits & Family Support serves justice-involved adults and families rebuilding stability after incarceration in Accomack County. Accomack Department of Social Services in Accomack processes SNAP, Medicaid, TANF, and energy assistance applications for residents of Accomack County, including returning citizens reestablishing food and health benefits after release from jail or Virginia Department of Corrections custody. Bring proof of identity, income, and release or residency documents when applying at a county office or online portal. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Accomack Department of Social Services — Benefits & Family Support sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Accomack. Lleve prueba de identidad, ingresos y documentos de liberación o residencia al solicitar en una oficina del condado o portal en línea. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
    'c1000001-0009-4000-8000-000000000001',
    'Virginia',
    'Accomack',
    'Accomack',
    'P. O. Box 210',
    '(757) 787-1530',
    'http://www.co.accomack.va.us/departments/social-services',
    NULL,
    'Typically Monday–Friday business hours; call ahead',
    'Residents of Accomack County meeting income and household-size requirements for SNAP, Medicaid, and TANF; criminal record generally not a barrier.',
    'Residentes del condado de Accomack que cumplan requisitos de ingresos y tamaño de hogar para SNAP, Medicaid y TANF; los antecedentes penales generalmente no son barrera.',
    'Apply online at commonhelp.virginia.gov, call 833-522-5582, or visit the local department of social services.',
    'Solicite en línea en commonhelp.virginia.gov, llame al 833-522-5582 o visite el departamento local de servicios sociales.',
