  -- source id: 171
  (
    'da000001-0171-4000-8000-000000000001',
    'CARITAS — The Healing Place (Men''s & Women''s Campuses)',
    'CARITAS operates The Healing Place, a long-term, peer-driven residential recovery program offered free of charge to men and women with substance use disorders in the greater Richmond area. The men''s campus on Dinwiddie Avenue has 196 beds and the women''s campus at the CARITAS Center has 142 beds. Participants live on campus while working a structured recovery curriculum with peer mentors, then transition through workforce development toward independent housing.',
    'CARITAS opera The Healing Place, un programa residencial de recuperación a largo plazo, dirigido por pares y gratuito para hombres y mujeres con trastornos por uso de sustancias en el área metropolitana de Richmond. El campus de hombres en Dinwiddie Avenue tiene 196 camas y el de mujeres en el CARITAS Center tiene 142 camas. Los participantes viven en el campus siguiendo un currículo estructurado de recuperación y luego pasan a desarrollo laboral hacia una vivienda independiente.',
    'c1000001-0002-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    '2220 Stockton Street',
    '804-230-1184',
    'https://caritasva.org/the-healing-place/',
    'info@caritasva.org',
    'Residential program 24/7; intake lines during business hours',
    'Adult men and women with substance use disorders; on-demand admission at no cost; people leaving incarceration are accepted.',
    'Hombres y mujeres adultos con trastornos por uso de sustancias; admisión según disponibilidad sin costo; se aceptan personas que salen de la encarcelación.',
    'Men''s intake 804-230-1184 (700 Dinwiddie Avenue); women''s intake 804-418-3049 (2220 Stockton Street); for emergency shelter call the Homeless Connection Line at 804-972-0813.',
    'Admisión de hombres 804-230-1184 (700 Dinwiddie Avenue); admisión de mujeres 804-418-3049 (2220 Stockton Street); para refugio de emergencia llame a la Homeless Connection Line al 804-972-0813.',
    ARRAY['Richmond City', 'Henrico', 'Chesterfield'],
    'multi',
    ARRAY['Long-term residential recovery', 'Peer-driven recovery curriculum', 'Emergency shelter referral', 'Workforce development', 'Recovery residence transition'],
    ARRAY['housing', 'recovery-residence', 'residential-recovery', 'free', 'Richmond', 'reentry'],
    ARRAY['accepts_criminal_record'],
    false,
    'active'
  ),
  -- source id: 172
  (
    'da000001-0172-4000-8000-000000000001',
    'CARITAS Recovery Residences',
    'CARITAS Recovery Residences offers safe, affordable sober-living apartments at the CARITAS Center in South Richmond for men and women at any point in their recovery journey. Residents live in a structured, substance-free community with access to CARITAS recovery programming, the CARITAS Works six-week workforce development program, and the Furniture Bank for household goods when they move into permanent housing.',
    'CARITAS Recovery Residences ofrece apartamentos de vida sobria seguros y asequibles en el CARITAS Center, al sur de Richmond, para hombres y mujeres en cualquier punto de su recuperación. Los residentes viven en una comunidad estructurada y libre de sustancias con acceso a la programación de recuperación de CARITAS, al programa de desarrollo laboral CARITAS Works de seis semanas y al banco de muebles al mudarse a una vivienda permanente.',
    'c1000001-0002-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    '2220 Stockton Street',
    '804-801-5082',
    'https://caritasva.org/i-need-help/',
    'RecoveryResidences@caritasva.org',
    'Office Monday–Friday business hours',
    'Men and women in recovery from substance use disorders at any stage; rent is affordable and income-based; criminal records are not an automatic bar.',
    'Hombres y mujeres en recuperación de trastornos por uso de sustancias en cualquier etapa; la renta es asequible y basada en ingresos; los antecedentes penales no son una barrera automática.',
    'Contact RecoveryResidences@caritasva.org or 804-801-5082 to apply; the CARITAS Works employment program can be reached at 804-612-1752; Furniture Bank 804-358-0964 ext. 302.',
    'Contacte RecoveryResidences@caritasva.org o el 804-801-5082 para solicitar; el programa de empleo CARITAS Works está en el 804-612-1752; banco de muebles 804-358-0964 ext. 302.',
    ARRAY['Richmond City', 'Henrico', 'Chesterfield'],
    'multi',
    ARRAY['Sober-living apartments', 'Recovery programming', 'Workforce development', 'Furniture Bank access', 'Case management'],
    ARRAY['housing', 'sober-living', 'recovery-residence', 'affordable', 'Richmond', 'reentry'],
    ARRAY['accepts_criminal_record'],
    false,
    'active'
  ),
  -- source id: 173
  (
    'da000001-0173-4000-8000-000000000001',
    'REAL LIFE — Recovery & Reentry Housing',
    'REAL LIFE operates recovery houses in Richmond with about 130 beds for men and women impacted by incarceration, substance use, or homelessness, serving a primarily reentry population from across Virginia. Residents receive intensive case management from a Pathway Navigator, a behavior-modification curriculum, employment navigation with more than 100 employer partners, and required recovery classes as they work toward graduation and independent living.',
    'REAL LIFE opera casas de recuperación en Richmond con unas 130 camas para hombres y mujeres afectados por la encarcelación, el uso de sustancias o la falta de vivienda, sirviendo principalmente a una población en reinserción de toda Virginia. Los residentes reciben manejo de caso intensivo de un Pathway Navigator, un currículo de modificación de conducta, orientación de empleo con más de 100 empleadores aliados y clases de recuperación requeridas mientras avanzan hacia la vida independiente.',
    'c1000001-0002-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    '1111 N 25th Street',
    '804-406-4111',
    'https://reallifeprogram.org/',
    'info@reallifeprogram.org',
    'Office Monday–Friday business hours; houses 24/7',
    'Adults impacted by incarceration, substance use, or homelessness; apply online or through a prison reentry counselor; people can apply from custody as part of a home plan.',
    'Adultos afectados por la encarcelación, el uso de sustancias o la falta de vivienda; solicite en línea o a través de un consejero de reinserción de la prisión; se puede solicitar desde custodia como parte de un plan de hogar.',
    'Submit one application online and expect up to a week for review plus a phone interview; people in prison can request an application through their reentry counselor; email is answered faster than calls.',
    'Envíe una sola solicitud en línea y espere hasta una semana para revisión más una entrevista telefónica; las personas en prisión pueden pedir la solicitud a su consejero de reinserción; el correo electrónico se responde más rápido que las llamadas.',
    ARRAY['Richmond City'],
    'single',
    ARRAY['Recovery housing', 'Intensive case management', 'Employment navigation', 'Behavior-modification curriculum', 'Reentry support'],
    ARRAY['housing', 'recovery-residence', 'reentry', 'justice-involved', 'case-management', 'Richmond'],
    ARRAY['accepts_criminal_record'],
    false,
    'active'
  ),
  -- source id: 174
  (
    'da000001-0174-4000-8000-000000000001',
    'HomeAgain — Emergency Shelters & Rapid Rehousing',
    'HomeAgain has served greater Richmond since 1979 with year-round emergency shelters, bridge housing, rapid rehousing, and permanent supportive housing. Its City Family Shelter downtown houses up to 50 women, mothers, and families with case management, housing and job search help, and mental health support, while community housing programs place individuals and families in scattered-site apartments with short- and long-term rental subsidies.',
    'HomeAgain sirve al área metropolitana de Richmond desde 1979 con refugios de emergencia todo el año, vivienda puente, realojamiento rápido y vivienda de apoyo permanente. Su City Family Shelter en el centro aloja hasta 50 mujeres, madres y familias con manejo de caso, ayuda de búsqueda de vivienda y empleo y apoyo de salud mental, mientras los programas comunitarios ubican a personas y familias en apartamentos dispersos con subsidios de renta.',
    'c1000001-0002-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    '2001 Maywill Street, Suite 201',
    '804-358-7747',
    'https://www.homeagainrichmond.org/',
    'info@homeagainrichmond.org',
    'Shelters 24/7; office Monday–Friday business hours',
    'Individuals and families experiencing homelessness in the greater Richmond region; all placements come through the Homeless Connection Line coordinated entry, not direct referral.',
    'Personas y familias sin hogar en la región metropolitana de Richmond; todas las colocaciones pasan por la entrada coordinada de la Homeless Connection Line, no por referencia directa.',
    'Call the Homeless Connection Line at 804-972-0813 to be assessed for shelter (Mon–Fri 8 a.m.–9 p.m., Sat–Sun 1–9 p.m.); the Maywill Street office is administrative and for donations only.',
    'Llame a la Homeless Connection Line al 804-972-0813 para una evaluación de refugio (lun–vie 8 a.m.–9 p.m., sáb–dom 1–9 p.m.); la oficina de Maywill Street es administrativa y solo para donaciones.',
    ARRAY['Richmond City', 'Henrico', 'Chesterfield', 'Hanover', 'Charles City', 'New Kent', 'Colonial Heights'],
    'multi',
    ARRAY['Emergency shelter', 'Rapid rehousing', 'Permanent supportive housing', 'Case management', 'Housing search assistance'],
    ARRAY['housing', 'emergency-shelter', 'rapid-rehousing', 'families', 'Richmond', 'coordinated-entry'],
    ARRAY[]::TEXT[],
    false,
    'active'
  ),
  -- source id: 175
  (
    'da000001-0175-4000-8000-000000000001',
    'SupportWorks Housing (formerly Virginia Supportive Housing)',
    'SupportWorks Housing is Virginia''s largest and oldest provider of permanent supportive housing, combining affordable apartments with individualized support services to end homelessness across greater Richmond, South Hampton Roads, and Charlottesville. Programs include supportive apartment communities like Cool Lane Commons, the HomeLink scattered-site program for chronically homeless single adults with disabilities, and Supportive Services for Veteran Families.',
    'SupportWorks Housing es el proveedor más grande y antiguo de vivienda de apoyo permanente de Virginia, combinando apartamentos asequibles con servicios de apoyo individualizados para acabar con la falta de vivienda en Richmond, South Hampton Roads y Charlottesville. Sus programas incluyen comunidades de apartamentos como Cool Lane Commons, el programa HomeLink de sitios dispersos para adultos solteros con discapacidades y servicios de apoyo para familias de veteranos.',
    'c1000001-0002-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    '1900 Cool Lane, Suite B',
    '804-788-6825',
    'https://supportworkshousing.org/',
    NULL,
    'Office Monday–Friday business hours',
    'Adults experiencing homelessness, including chronically homeless single adults, veterans, older adults, and persons with disabilities; income limits apply; referrals flow through regional coordinated entry.',
    'Adultos sin hogar, incluidos adultos con falta de vivienda crónica, veteranos, adultos mayores y personas con discapacidades; aplican límites de ingresos; las referencias pasan por la entrada coordinada regional.',
    'Call 804-788-6825 for program information; veterans seeking SSVF help should ask for the intake coordinator at ext. 260; in Richmond, shelter placement starts with the Homeless Connection Line 804-972-0813.',
    'Llame al 804-788-6825 para información de programas; los veteranos que buscan ayuda SSVF deben pedir el coordinador de admisión en la ext. 260; en Richmond, la colocación en refugio comienza con la Homeless Connection Line 804-972-0813.',
