  -- source id: 176
  (
    'da000001-0176-4000-8000-000000000001',
    'The Salvation Army Richmond — Chamberlayne Avenue Shelters',
    'The Salvation Army operates the City of Richmond''s year-round 50-bed men''s shelter and the seasonal 100-bed Inclement Weather Shelter at 1900 Chamberlayne Avenue. The men''s shelter provides beds, meals, and case management year-round, while the Inclement Weather Shelter opens each winter from 5 p.m. to 8 a.m. on a first-come, first-served basis. The Community Resource and Training Center at the same address connects guests to services.',
    'El Ejército de Salvación opera el refugio de hombres de 50 camas de la ciudad de Richmond, abierto todo el año, y el refugio de clima inclemente de 100 camas, ambos en 1900 Chamberlayne Avenue. El refugio de hombres ofrece camas, comidas y manejo de caso todo el año, mientras el refugio de clima inclemente abre cada invierno de 5 p.m. a 8 a.m. por orden de llegada. El Community Resource and Training Center en la misma dirección conecta a los huéspedes con servicios.',
    'c1000001-0002-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    '1900 Chamberlayne Avenue',
    '804-972-0813',
    'https://southernusa.salvationarmy.org/centralvirginia/',
    NULL,
    'Men''s shelter 24/7 via referral; Inclement Weather Shelter seasonal 5:00 p.m.–8:00 a.m.',
    'Year-round men''s shelter serves single adult men referred through the Homeless Connection Line; the seasonal Inclement Weather Shelter is open to adults on a walk-up, first-come basis during winter.',
    'El refugio de hombres todo el año sirve a hombres adultos solteros referidos por la Homeless Connection Line; el refugio de clima inclemente está abierto a adultos por orden de llegada durante el invierno.',
    'There is no walk-in intake for the year-round shelter—call the Homeless Connection Line at 804-972-0813; the Inclement Weather Shelter operates roughly November 15–April 15, 5 p.m.–8 a.m., entrance via side alley.',
    'No hay admisión directa para el refugio anual—llame a la Homeless Connection Line al 804-972-0813; el refugio de clima inclemente opera aproximadamente del 15 de noviembre al 15 de abril, 5 p.m.–8 a.m., entrada por el callejón lateral.',
    ARRAY['Richmond City'],
    'single',
    ARRAY['Year-round men''s shelter', 'Seasonal inclement weather shelter', 'Meals', 'Case management', 'Resource center connection'],
    ARRAY['housing', 'emergency-shelter', 'men', 'inclement-weather', 'Richmond', 'low-barrier'],
