  -- source id: 177
  (
    'da000001-0177-4000-8000-000000000001',
    'ForKids — Housing Crisis Hotline & Housing Programs',
    'ForKids operates the Regional Housing Crisis Hotline, the central entry point for anyone facing homelessness or eviction across 14 cities and counties in Southeastern Virginia, answering more than 77,000 calls a year. From its Landmark Center headquarters in Chesapeake, ForKids also provides emergency shelter, rapid rehousing, homelessness prevention, and comprehensive family services including education support and case management.',
    'ForKids opera la Regional Housing Crisis Hotline, el punto central de entrada para cualquier persona que enfrenta la falta de vivienda o el desalojo en 14 ciudades y condados del sureste de Virginia, respondiendo más de 77,000 llamadas al año. Desde su sede Landmark Center en Chesapeake, ForKids también ofrece refugio de emergencia, realojamiento rápido, prevención de la falta de vivienda y servicios familiares integrales con apoyo educativo y manejo de caso.',
    'c1000001-0002-4000-8000-000000000001',
    'Virginia',
    'Chesapeake',
    'Chesapeake',
    '1001 Poindexter Street',
    '757-587-4202',
    'https://forkids.org/hotline/',
    'Info@ForKids.org',
    'Hotline Monday–Friday, 8:00 a.m.–5:30 p.m.',
    'Anyone experiencing a housing crisis in Greater Hampton Roads—living on the street, in shelter, or facing eviction; hotline staff assess and refer to available programs.',
    'Cualquier persona en crisis de vivienda en Greater Hampton Roads—viviendo en la calle, en refugio o enfrentando desalojo; el personal de la línea evalúa y refiere a los programas disponibles.',
    'Call the Housing Crisis Hotline at 757-587-4202, Monday–Friday 8 a.m.–5:30 p.m.; the hotline does not give direct financial assistance; general office 757-622-6400; browse resources at resources757.org.',
    'Llame a la Housing Crisis Hotline al 757-587-4202, lunes–viernes 8 a.m.–5:30 p.m.; la línea no da asistencia financiera directa; oficina general 757-622-6400; consulte recursos en resources757.org.',
    ARRAY['Chesapeake', 'Norfolk', 'Portsmouth', 'Suffolk', 'Virginia Beach', 'Franklin City', 'Isle of Wight', 'Southampton'],
