  (
    'da000001-0178-4000-8000-000000000001',
    'Union Mission Ministries — Norfolk Shelters',
    'Union Mission Ministries runs Norfolk''s largest emergency shelter campus, open 24 hours a day with the Bashford Men''s Shelter, a women''s shelter, cafeteria meals, day services, clothing, case management, and the long-term RECLAIM residential recovery program. The Mission provides more than 72,000 nights of shelter and nearly 190,000 meals each year to men, women, and children across Hampton Roads at no charge.',
    'Union Mission Ministries dirige el campus de refugio de emergencia más grande de Norfolk, abierto las 24 horas, con el refugio de hombres Bashford, un refugio de mujeres, comidas de cafetería, servicios de día, ropa, manejo de caso y el programa residencial de recuperación RECLAIM. La Misión brinda más de 72,000 noches de refugio y casi 190,000 comidas al año a hombres, mujeres y niños de Hampton Roads sin costo.',
    'c1000001-0002-4000-8000-000000000001',
    'Virginia',
    'Norfolk',
    'Norfolk',
    '5100 E Virginia Beach Boulevard',
    '757-627-8686',
    'https://www.unionmissionministries.org/',
    NULL,
    'Open 24/7; day services Monday–Friday 9:30 a.m.–3:00 p.m.',
    'Men, women, and children experiencing homelessness; faith-based program open to all; call first to confirm bed availability.',
    'Hombres, mujeres y niños sin hogar; programa basado en la fe abierto a todos; llame primero para confirmar disponibilidad de camas.',
    'Call 757-627-8686 before arriving—men ext. 200, single women ext. 331; the women and children''s shelter is temporarily closed but staff offer referrals (ext. 335); men''s intake arrival recommended 5–5:15 p.m.; day services 9:30 a.m.–3 p.m. weekdays.',
    'Llame al 757-627-8686 antes de llegar—hombres ext. 200, mujeres solteras ext. 331; el refugio de mujeres con niños está cerrado temporalmente pero el personal ofrece referencias (ext. 335); llegada recomendada para hombres 5–5:15 p.m.; servicios de día 9:30 a.m.–3 p.m. entre semana.',
