  (
    'da000001-0179-4000-8000-000000000001',
    'Samaritan House — Emergency & Permanent Housing',
    'Samaritan House owns and operates 13 emergency shelter homes at undisclosed locations across Virginia Beach and provides permanent housing through rapid rehousing for homeless families and survivors of domestic violence, sexual assault, and human trafficking. Case managers work with each participant on safety planning, financial literacy, vocational help, counseling, and children''s services on the path to self-sufficiency and permanent housing.',
    'Samaritan House posee y opera 13 hogares de refugio de emergencia en ubicaciones no divulgadas en Virginia Beach y ofrece vivienda permanente mediante realojamiento rápido para familias sin hogar y sobrevivientes de violencia doméstica, agresión sexual y trata de personas. Los manejadores de caso trabajan con cada participante en planes de seguridad, educación financiera, ayuda vocacional, consejería y servicios para niños hacia la autosuficiencia y la vivienda permanente.',
    'c1000001-0002-4000-8000-000000000001',
    'Virginia',
    'Virginia Beach',
    'Virginia Beach',
    '2620 Southern Boulevard',
    '757-631-0710',
    'https://samaritanhouseva.org/',
    NULL,
    'Crisis hotline 24/7; administrative office Monday–Friday business hours',
    'Victims of domestic violence, sexual assault, and human trafficking, and families experiencing homelessness; services are free; shelter placement is assessed through hotlines.',
    'Víctimas de violencia doméstica, agresión sexual y trata de personas, y familias sin hogar; los servicios son gratuitos; la colocación en refugio se evalúa por líneas telefónicas.',
    'For safety-related shelter call the 24-hour crisis hotline 757-430-2120; for general homelessness call the Regional Housing Crisis Hotline 757-587-4202; dial 911 if in immediate danger.',
    'Para refugio por seguridad llame a la línea de crisis 24 horas 757-430-2120; para falta de vivienda general llame a la Regional Housing Crisis Hotline 757-587-4202; marque 911 si está en peligro inmediato.',
    ARRAY['Virginia Beach'],
    'single',
    ARRAY['Emergency safe housing', 'Rapid rehousing', 'Case management', 'Victim advocacy', 'Children''s services'],
    ARRAY['housing', 'emergency-shelter', 'domestic-violence', 'rapid-rehousing', 'Virginia-Beach', 'trauma-informed'],
