  (
    'da000001-0180-4000-8000-000000000001',
    'Carpenter''s Shelter — Alexandria',
    'Carpenter''s Shelter serves people experiencing homelessness in the City of Alexandria through the 64-bed Hoffman Center family shelter on North Henry Street and the 64-bed Alexandria Community Shelter on Mill Road, which houses both single adults and families. Beyond beds and daily meals, the shelter provides case management, employment help, and aftercare so clients can address the barriers that led to homelessness and return to permanent housing.',
    'Carpenter''s Shelter sirve a personas sin hogar en la ciudad de Alexandria a través del refugio familiar Hoffman Center de 64 camas en North Henry Street y el Alexandria Community Shelter de 64 camas en Mill Road, que aloja a adultos solteros y familias. Además de camas y comidas diarias, el refugio ofrece manejo de caso, ayuda de empleo y seguimiento para que los clientes superen las barreras que causaron su falta de vivienda y vuelvan a una vivienda permanente.',
    'c1000001-0002-4000-8000-000000000001',
    'Virginia',
    'Alexandria',
    'Alexandria',
    '930 N Henry Street',
    '703-548-7500',
    'https://carpentersshelter.org/',
    'Info@CarpentersShelter.org',
    'Shelters 24/7; administrative office Monday–Friday business hours',
    'Individuals and families experiencing homelessness in the City of Alexandria; the Hoffman Center is family-only; single adults are served at the Alexandria Community Shelter.',
    'Personas y familias sin hogar en la ciudad de Alexandria; el Hoffman Center es solo para familias; los adultos solteros son atendidos en el Alexandria Community Shelter.',
    'For emergency shelter placement call Alexandria''s Homeless Services Assessment Center at 703-746-5700; Alexandria Community Shelter direct line 703-746-3660; winter shelter 571-652-9984.',
    'Para colocación en refugio de emergencia llame al Homeless Services Assessment Center de Alexandria al 703-746-5700; línea directa del Alexandria Community Shelter 703-746-3660; refugio de invierno 571-652-9984.',
    ARRAY['Alexandria'],
