  (
    'da000001-0181-4000-8000-000000000001',
    'Shelter House — Fairfax & Loudoun Emergency Shelters',
    'Shelter House operates seven emergency shelters across Fairfax and Loudoun counties, including the 62-bed Katherine K. Hanley Family Shelter in Fairfax, all using a rapid rehousing approach that pairs shelter with housing location support, rental assistance, and intensive case management. The organization serves families and individuals experiencing homelessness or fleeing domestic violence and helps them return to permanent housing quickly.',
    'Shelter House opera siete refugios de emergencia en los condados de Fairfax y Loudoun, incluido el Katherine K. Hanley Family Shelter de 62 camas en Fairfax, todos con un enfoque de realojamiento rápido que combina refugio con búsqueda de vivienda, asistencia de renta y manejo de caso intensivo. La organización sirve a familias y personas sin hogar o que huyen de violencia doméstica y les ayuda a volver rápidamente a una vivienda permanente.',
    'c1000001-0002-4000-8000-000000000001',
    'Virginia',
    'Fairfax',
    'Fairfax',
    '12970 Katherine Hanley Court',
    '571-522-6800',
    'https://www.shelterhouse.org/',
    NULL,
    'Shelters 24/7; referrals weekdays via Coordinated Services Planning',
    'Families and individuals experiencing homelessness or domestic violence in Fairfax County and Loudoun County; placement is through county coordinated entry, not walk-in.',
    'Familias y personas sin hogar o en situación de violencia doméstica en los condados de Fairfax y Loudoun; la colocación es por entrada coordinada del condado, no por llegada directa.',
    'In Fairfax County call Coordinated Services Planning at 703-222-0880 (Mon–Fri 8 a.m.–4:30 p.m.) for shelter referral; in a domestic violence emergency call the county''s 24-hour hotline 703-360-7273.',
    'En el condado de Fairfax llame a Coordinated Services Planning al 703-222-0880 (lun–vie 8 a.m.–4:30 p.m.) para referencia de refugio; en una emergencia de violencia doméstica llame a la línea 24 horas del condado 703-360-7273.',
