  (
    'da000001-0182-4000-8000-000000000001',
    'Miriam''s House — Lynchburg Homeless Response',
    'Miriam''s House leads the Lynchburg area''s homeless response system, operating Coordinated Homeless Intake and Access (CHIA), street outreach, rapid rehousing, and permanent supportive housing for people experiencing homelessness in Lynchburg and the counties of Amherst, Appomattox, Bedford, and Campbell. Its solution-focused programs pair stable, affordable housing with financial assistance and supportive services so households do not return to homelessness.',
    'Miriam''s House lidera el sistema de respuesta a la falta de vivienda del área de Lynchburg, operando la entrada coordinada CHIA, alcance en la calle, realojamiento rápido y vivienda de apoyo permanente para personas sin hogar en Lynchburg y los condados de Amherst, Appomattox, Bedford y Campbell. Sus programas combinan vivienda estable y asequible con asistencia financiera y servicios de apoyo para que los hogares no vuelvan a quedar sin vivienda.',
    'c1000001-0002-4000-8000-000000000001',
    'Virginia',
    'Lynchburg',
    'Lynchburg',
    '409 Magnolia Street',
    '434-847-1101',
    'https://www.miriamshouse.org/',
    NULL,
    'Office Monday–Friday, 9:00 a.m.–4:00 p.m.',
    'People who are homeless or within three days of losing housing in Lynchburg, Amherst, Appomattox, Bedford, or Campbell; entry is through the CHIA coordinated intake line.',
    'Personas sin hogar o a tres días de perder su vivienda en Lynchburg, Amherst, Appomattox, Bedford o Campbell; la entrada es por la línea de admisión coordinada CHIA.',
    'Call the CHIA homeless information line at 434-427-2442 if you are in a housing crisis; office hours Monday–Friday 9 a.m.–4 p.m.',
    'Llame a la línea de información CHIA al 434-427-2442 si está en crisis de vivienda; horario de oficina lunes–viernes 9 a.m.–4 p.m.',
    ARRAY['Lynchburg', 'Amherst', 'Appomattox', 'Bedford', 'Campbell'],
