  -- source id: 183
  (
    'da000001-0183-4000-8000-000000000001',
    'The Haven — Day Shelter & Housing Programs',
    'The Haven is a multi-resource day shelter and housing resource center in downtown Charlottesville, open every morning 365 days a year with breakfast, showers, laundry, mail service, storage, and emergency clothing assistance. Its Housing First programs—homeless prevention, the Haven Housing Fund, and rapid rehousing—connect guests from Charlottesville and surrounding counties to case management and rent assistance that return them to stable housing.',
    'The Haven es un refugio de día y centro de recursos de vivienda en el centro de Charlottesville, abierto cada mañana los 365 días del año con desayuno, duchas, lavandería, servicio de correo, almacenamiento y ayuda de ropa de emergencia. Sus programas Housing First—prevención, el Haven Housing Fund y realojamiento rápido—conectan a los huéspedes de Charlottesville y los condados cercanos con manejo de caso y asistencia de renta hacia una vivienda estable.',
    'c1000001-0002-4000-8000-000000000001',
    'Virginia',
    'Charlottesville',
    'Charlottesville',
    '112 W Market Street',
    '434-973-1234',
    'https://www.thehaven.org/',
    'operations@thehaven.org',
    'Monday–Friday 7:00 a.m.–5:00 p.m. (closed 12–1 p.m.); Saturday–Sunday 7:00 a.m.–12:00 noon',
    'Day shelter is open to anyone in need age 18 and over; housing programs serve people who are literally homeless or within 14 days of losing housing in the Charlottesville region.',
    'El refugio de día está abierto a cualquier persona mayor de 18 años; los programas de vivienda sirven a personas literalmente sin hogar o a 14 días de perder su vivienda en la región de Charlottesville.',
    'Drop in any morning or call 434-973-1234 ext. 100; for housing screening call the Homeless Information Line 434-207-2328 and leave a voicemail; for other needs call the Community Resource Line 833-524-2904.',
    'Visite cualquier mañana o llame al 434-973-1234 ext. 100; para evaluación de vivienda llame a la Homeless Information Line 434-207-2328 y deje un mensaje; para otras necesidades llame a la Community Resource Line 833-524-2904.',
    ARRAY['Charlottesville', 'Albemarle', 'Fluvanna', 'Greene', 'Louisa', 'Nelson'],
    'multi',
