  (
    'da000001-0184-4000-8000-000000000001',
    'House of Hope — Danville Emergency Shelter',
    'House of Hope is a faith-based emergency homeless shelter in downtown Danville serving men, women, and children from Danville, Pittsylvania County, and surrounding Southside communities for more than a decade. The shelter provides beds, a morning meal, an evening meal, and bagged lunches to go, plus transitional housing and referrals to local agencies so residents can move toward stable housing and employment.',
    'House of Hope es un refugio de emergencia basado en la fe en el centro de Danville que sirve a hombres, mujeres y niños de Danville, el condado de Pittsylvania y las comunidades cercanas de Southside desde hace más de una década. El refugio ofrece camas, desayuno, cena y almuerzos para llevar, además de vivienda de transición y referencias a agencias locales para que los residentes avancen hacia vivienda estable y empleo.',
    'c1000001-0002-4000-8000-000000000001',
    'Virginia',
    'Danville',
    'Danville',
    '206 S Ridge Street',
    '434-549-1459',
    'https://danvillehoh.org/',
    'info@danvillehoh.org',
    'Intake daily 5:00–7:00 p.m.; shelter overnight',
    'Anyone needing emergency shelter in the Danville area, including men (Phil and Fran''s Place), women, and families with children.',
    'Cualquier persona que necesite refugio de emergencia en el área de Danville, incluidos hombres (Phil and Fran''s Place), mujeres y familias con niños.',
    'Check in daily between 5:00 and 7:00 p.m.; call ahead at 434-549-1459 to confirm bed availability; residents are referred to local agencies for daytime meals and services.',
    'Regístrese a diario entre las 5:00 y 7:00 p.m.; llame antes al 434-549-1459 para confirmar disponibilidad de camas; se refieren a los residentes a agencias locales para comidas y servicios de día.',
    ARRAY['Danville', 'Pittsylvania', 'Martinsville', 'Henry', 'Halifax'],
    'multi',
    ARRAY['Emergency shelter', 'Meals', 'Transitional housing', 'Agency referrals', 'Family shelter'],
    ARRAY['housing', 'emergency-shelter', 'faith-based', 'Danville', 'Southside', 'families'],
    ARRAY[]::TEXT[],
    false,
    'active'
  ),
  -- source id: 185
  (
    'da000001-0185-4000-8000-000000000001',
    'The Warming Center of Martinsville & Henry County',
    'The Warming Center of MHC, a project of the West Piedmont Better Housing Coalition, provides a warm, dry overnight sleep space and a hot meal inside the Salvation Army building in Martinsville on any night temperatures fall to around 38–40 degrees or below, roughly November through March. All guests are welcome and staff connect them to resources for stable housing and other community services in Martinsville and Henry County.',
    'El Warming Center de MHC, un proyecto de la West Piedmont Better Housing Coalition, ofrece un espacio nocturno cálido y seco para dormir y una comida caliente dentro del edificio del Ejército de Salvación en Martinsville cualquier noche que la temperatura baje a unos 38–40 grados o menos, aproximadamente de noviembre a marzo. Todos son bienvenidos y el personal los conecta con recursos de vivienda estable y otros servicios comunitarios en Martinsville y el condado de Henry.',
    'c1000001-0002-4000-8000-000000000001',
    'Virginia',
    'Martinsville',
    'Martinsville',
    '603 Memorial Boulevard S',
    '276-207-9660',
    'https://warmingcentermhc.org/',
    'operations@mhcwarmingcenter.org',
    'Seasonal cold-weather nights, approximately 7:00 p.m.–8:00 a.m.',
    'Anyone needing overnight shelter on cold nights in the Martinsville–Henry County area; no residency or sobriety documentation required to enter.',
    'Cualquier persona que necesite refugio nocturno en noches frías en el área de Martinsville–condado de Henry; no se requiere documentación de residencia ni de sobriedad para entrar.',
    'Seasonal: open only on nights near or below 38–40 degrees, roughly November–March; check-in about 7–10 p.m., center closes 8 a.m.; the center is a nighttime operation, so daytime calls may be answered the following evening.',
    'Estacional: abre solo en noches cercanas o por debajo de 38–40 grados, aproximadamente de noviembre a marzo; registro de 7 a 10 p.m., cierra a las 8 a.m.; opera de noche, por lo que las llamadas de día pueden responderse la noche siguiente.',
    ARRAY['Martinsville', 'Henry'],
    'multi',
    ARRAY['Overnight warming shelter', 'Hot meal', 'Housing resource connection', 'Community service referrals'],
    ARRAY['housing', 'warming-center', 'seasonal', 'emergency-shelter', 'Martinsville', 'Henry-County'],
    ARRAY[]::TEXT[],
    false,
    'active'
  ),
  -- source id: 186
  (
    'da000001-0186-4000-8000-000000000001',
    'Stone Mountain Health Services (FQHC)',
    'Stone Mountain Health Services is a federally qualified health center operating 12 clinics and black lung breathing centers across far Southwest Virginia, serving Buchanan, Dickenson, Lee, Russell, Scott, Smyth, Tazewell, Washington, and Wise counties and the City of Norton. Clinics provide primary care for all ages, behavioral health counseling, medication assistance, lab services, and black lung services, with fees on a sliding scale for the uninsured.',
    'Stone Mountain Health Services es un centro de salud federalmente calificado con 12 clínicas y centros respiratorios para pulmón negro en el extremo suroeste de Virginia, sirviendo los condados de Buchanan, Dickenson, Lee, Russell, Scott, Smyth, Tazewell, Washington y Wise y la ciudad de Norton. Las clínicas ofrecen atención primaria para todas las edades, consejería de salud conductual, asistencia con medicamentos, laboratorio y servicios de pulmón negro, con tarifas de escala móvil para no asegurados.',
    'c1000001-0004-4000-8000-000000000001',
    'Virginia',
    'Lee',
    'Jonesville',
    '276 Fieldstone Drive',
    '276-546-3001',
    'https://stonemountainhealthservices.org/',
    NULL,
    'Clinic hours vary; Jonesville Monday–Friday, 8:00 a.m.–6:00 p.m.',
    'Open to everyone regardless of insurance status or ability to pay; sliding-scale fees based on income; Medicaid, Medicare, and private insurance accepted.',
    'Abierto a todos sin importar el seguro o la capacidad de pago; tarifas de escala móvil según ingresos; se aceptan Medicaid, Medicare y seguros privados.',
    'Jonesville Family Health Center 276-546-3001 (Mon–Fri 8 a.m.–6 p.m.); central administration 276-546-5310 or toll-free 866-297-5250; 12 clinic locations are listed on the website including Damascus and Konnarock.',
    'Jonesville Family Health Center 276-546-3001 (lun–vie 8 a.m.–6 p.m.); administración central 276-546-5310 o línea gratuita 866-297-5250; las 12 clínicas aparecen en el sitio web, incluidas Damascus y Konnarock.',
