  (
    'da000001-0187-4000-8000-000000000001',
    'The Health Wagon — Free Clinics of Southwest Virginia',
    'The Health Wagon is a nurse practitioner–managed nonprofit providing free medical, dental, vision, and behavioral health care to uninsured and underinsured people at stationary clinics in Wise and Clintwood and mobile units visiting sites across Buchanan, Dickenson, Lee, Russell, Scott, and Wise counties and the City of Norton. Services include chronic disease management, medication assistance, cancer screenings, specialty clinics, and free health fairs.',
    'The Health Wagon es una organización sin fines de lucro dirigida por enfermeras practicantes que brinda atención médica, dental, visual y de salud conductual gratuita a personas sin seguro o con seguro insuficiente en clínicas fijas en Wise y Clintwood y unidades móviles que visitan sitios en los condados de Buchanan, Dickenson, Lee, Russell, Scott y Wise y la ciudad de Norton. Ofrece manejo de enfermedades crónicas, asistencia con medicamentos, detección de cáncer, clínicas de especialidad y ferias de salud gratuitas.',
    'c1000001-0004-4000-8000-000000000001',
    'Virginia',
    'Wise',
    'Wise',
    '5626 Patriot Drive',
    '276-328-8850',
    'https://thehealthwagon.org/',
    'info@thehealthwagon.org',
    'Monday–Friday business hours; mobile clinic schedule varies',
    'Uninsured and underinsured residents of far Southwest Virginia; no fee for care; call to confirm eligibility and clinic schedule.',
    'Residentes sin seguro o con seguro insuficiente del extremo suroeste de Virginia; la atención es gratuita; llame para confirmar elegibilidad y horario de clínicas.',
    'Call 276-328-8850 for appointments and the mobile clinic schedule; specialty clinics include cardiology, endocrinology, women''s health, and dental/vision events; hosts the annual RAM-style health outreach in Wise.',
    'Llame al 276-328-8850 para citas y el calendario de la clínica móvil; las clínicas de especialidad incluyen cardiología, endocrinología, salud de la mujer y eventos dentales y de visión; organiza la feria de salud anual en Wise.',
    ARRAY['Wise', 'Dickenson', 'Buchanan', 'Russell', 'Lee', 'Scott', 'Norton'],
