  (
    'da000001-0188-4000-8000-000000000001',
    'Tri-Area Community Health (FQHC)',
    'Tri-Area Community Health is a federally qualified health center with clinics in Laurel Fork (Carroll County), Ferrum (Franklin County), Floyd, and Troutdale (Grayson County), plus pharmacies at Laurel Fork and Ferrum. Providers deliver primary care from pediatrics to geriatrics, behavioral health, psychiatric services, clinical pharmacy, diabetes education, x-rays, and family planning, with Medicaid enrollment help and an after-hours on-call line.',
    'Tri-Area Community Health es un centro de salud federalmente calificado con clínicas en Laurel Fork (condado de Carroll), Ferrum (condado de Franklin), Floyd y Troutdale (condado de Grayson), más farmacias en Laurel Fork y Ferrum. Los proveedores ofrecen atención primaria de pediatría a geriatría, salud conductual, servicios psiquiátricos, farmacia clínica, educación en diabetes, radiografías y planificación familiar, con ayuda de inscripción en Medicaid y línea de guardia fuera de horario.',
    'c1000001-0004-4000-8000-000000000001',
