    'Monday–Friday, roughly 7:45 a.m.–5:00 p.m. (Laurel Fork Mondays until 6:30 p.m.)',
    'Open to all patients regardless of insurance; sliding-fee discounts available; Medicaid and insurance enrollment assistance offered.',
    'Abierto a todos los pacientes sin importar el seguro; descuentos de escala móvil disponibles; se ofrece ayuda de inscripción en Medicaid y seguros.',
    'Laurel Fork 276-398-2292; Ferrum 540-365-4469; Floyd 540-745-9290; after-hours medical advice via the clinic phone lines; on-site pharmacies at Laurel Fork (276-398-2620) and Ferrum (540-365-6337).',
    'Laurel Fork 276-398-2292; Ferrum 540-365-4469; Floyd 540-745-9290; consejo médico fuera de horario por las mismas líneas; farmacias en Laurel Fork (276-398-2620) y Ferrum (540-365-6337).',
