  (
    'da000001-0189-4000-8000-000000000001',
    'Bland County Medical Clinic (FQHC)',
    'Bland County Medical Clinic is a federally qualified health center founded in 1979 in Bastian, just off I-77 exit 58, with three locations including a dental clinic and the Orchard Creek Clinic. It provides primary and urgent care, behavioral health support, and dental services to Bland County''s rural community, with a medical provider on call 24/7 and sliding-scale fees so no one is turned away for inability to pay.',
    'Bland County Medical Clinic es un centro de salud federalmente calificado fundado en 1979 en Bastian, junto a la salida 58 de la I-77, con tres ubicaciones que incluyen una clínica dental y la Orchard Creek Clinic. Ofrece atención primaria y de urgencia, apoyo de salud conductual y servicios dentales a la comunidad rural del condado de Bland, con un proveedor médico de guardia 24/7 y tarifas de escala móvil para que nadie sea rechazado por no poder pagar.',
    'c1000001-0004-4000-8000-000000000001',
    'Virginia',
    'Bland',
    'Bastian',
    '12301 Grapefield Road',
    '276-688-4331',
    'https://blandclinic.com/',
    NULL,
    'Monday–Friday, 8:00 a.m.–6:00 p.m.; provider on call 24/7',
    'Open to all; sliding-scale fees for uninsured patients; Medicaid, Medicare, and private insurance accepted.',
    'Abierto a todos; tarifas de escala móvil para pacientes sin seguro; se aceptan Medicaid, Medicare y seguros privados.',
    'Main line 276-688-4331 also reaches the 24/7 on-call medical provider; clinic hours Monday–Friday 8 a.m.–6 p.m.; dental services available through the partnership with Bland Ministry Center''s dental program.',
    'La línea principal 276-688-4331 también conecta con el proveedor médico de guardia 24/7; horario lunes–viernes 8 a.m.–6 p.m.; servicios dentales disponibles mediante la alianza con el programa dental del Bland Ministry Center.',
