  (
    'da000001-0190-4000-8000-000000000001',
    'Southwest Virginia Community Health Systems (FQHC)',
    'Southwest Virginia Community Health Systems is a federally qualified health center network with community health centers in Saltville, Meadowview, Tazewell, and Bristol, plus a regional dental center and the New Day Recovery program in Saltville. The centers provide family medicine, pediatrics, behavioral health, optometry, dental care, and addiction recovery support with sliding-scale fees and an after-hours emergency line.',
    'Southwest Virginia Community Health Systems es una red de centros de salud federalmente calificados con centros comunitarios en Saltville, Meadowview, Tazewell y Bristol, además de un centro dental regional y el programa de recuperación New Day en Saltville. Los centros ofrecen medicina familiar, pediatría, salud conductual, optometría, atención dental y apoyo de recuperación de adicciones con tarifas de escala móvil y una línea de emergencia fuera de horario.',
    'c1000001-0004-4000-8000-000000000001',
