    'information@svchs.com',
    'Monday–Friday, 8:00 a.m.–6:30 p.m. at most locations',
    'Open to all patients; sliding-fee scale for the uninsured; Medicaid, Medicare, and most insurance accepted.',
    'Abierto a todos los pacientes; escala de tarifas móvil para no asegurados; se aceptan Medicaid, Medicare y la mayoría de los seguros.',
    'Saltville 276-496-4433; Meadowview 276-944-3999; Tazewell 276-979-9899; Bristol 276-669-5179; dental center 276-496-4492; after-hours emergencies 1-888-531-8354.',
    'Saltville 276-496-4433; Meadowview 276-944-3999; Tazewell 276-979-9899; Bristol 276-669-5179; centro dental 276-496-4492; emergencias fuera de horario 1-888-531-8354.',
