  (
    'da000001-0191-4000-8000-000000000001',
    'Central Virginia Health Services (FQHC network)',
    'Central Virginia Health Services is Virginia''s oldest community health center network, operating about 19 federally qualified health centers from its New Canton headquarters in Buckingham County. Sites across central and eastern Virginia—including Buckingham, Fluvanna, Cumberland, Charlotte, Caroline, Louisa, Prince Edward, Charles City, Petersburg, Hopewell, Charlottesville, and Fredericksburg—offer medical, dental, behavioral health, pharmacy, and addiction treatment with sliding-scale fees.',
    'Central Virginia Health Services es la red de centros de salud comunitarios más antigua de Virginia, con unas 19 clínicas federalmente calificadas desde su sede en New Canton, condado de Buckingham. Sus sitios en el centro y este de Virginia—incluidos Buckingham, Fluvanna, Cumberland, Charlotte, Caroline, Louisa, Prince Edward, Charles City, Petersburg, Hopewell, Charlottesville y Fredericksburg—ofrecen atención médica, dental, salud conductual, farmacia y tratamiento de adicciones con tarifas de escala móvil.',
    'c1000001-0004-4000-8000-000000000001',
    'Virginia',
    'Buckingham',
    'New Canton',
    '25892 N James Madison Highway',
    '434-581-3271',
    'https://www.cvhsinc.org/',
    'info@cvhsinc.org',
    'Most sites Monday–Friday, 8:00 a.m.–4:30 p.m. or later',
    'Open to anyone regardless of insurance or ability to pay; sliding-fee discounts based on household income; served 45,000+ patients in 2024.',
    'Abierto a cualquier persona sin importar el seguro o la capacidad de pago; descuentos de escala móvil según ingresos del hogar; atendió a más de 45,000 pacientes en 2024.',
    'Buckingham Health Center and administration at New Canton 434-581-3271 (general inquiries 434-581-4073); use the Find a Health Center tool on the website to locate the nearest of the 19 sites.',
    'Centro de salud de Buckingham y administración en New Canton 434-581-3271 (consultas generales 434-581-4073); use la herramienta Find a Health Center del sitio web para ubicar el más cercano de los 19 sitios.',
