  (
    'da000001-0192-4000-8000-000000000001',
    'Horizon Behavioral Health (Lynchburg-area CSB)',
    'Horizon Behavioral Health is the community services board for the City of Lynchburg and the counties of Amherst, Appomattox, Bedford, and Campbell, providing mental health, substance use, and developmental disability services across the lifespan. Wellness centers in each locality offer assessments, outpatient therapy, psychiatric care, case management, and crisis services, with new clients seen at the Langhorne Wellness Center in Lynchburg.',
    'Horizon Behavioral Health es la junta de servicios comunitarios de la ciudad de Lynchburg y los condados de Amherst, Appomattox, Bedford y Campbell, ofreciendo servicios de salud mental, uso de sustancias y discapacidades del desarrollo en todas las edades. Los centros de bienestar de cada localidad ofrecen evaluaciones, terapia ambulatoria, atención psiquiátrica, manejo de caso y servicios de crisis; los nuevos clientes son atendidos en el Langhorne Wellness Center de Lynchburg.',
    'c1000001-0004-4000-8000-000000000001',
    'Virginia',
    'Lynchburg',
    'Lynchburg',
    '2215 Langhorne Road',
    '434-477-5000',
    'https://www.horizonbh.org/',
    NULL,
    'Monday–Friday business hours; crisis services 24/7',
    'Residents of Lynchburg, Amherst, Appomattox, Bedford, and Campbell; Medicaid, Medicare, private insurance, and sliding-scale self-pay accepted; people on probation or reentering from incarceration may self-refer.',
    'Residentes de Lynchburg, Amherst, Appomattox, Bedford y Campbell; se aceptan Medicaid, Medicare, seguros privados y pago según escala móvil; las personas en probatoria o en reinserción pueden autorreferirse.',
    'Call admissions at 434-477-5000 to set up a profile and assessment; 24/7 crisis line 434-522-8191; local wellness centers in Amherst (434-946-2316), Appomattox (434-352-8239), Bedford (540-586-5429), and Rustburg (434-332-5149).',
    'Llame a admisiones al 434-477-5000 para crear un perfil y evaluación; línea de crisis 24/7 434-522-8191; centros locales en Amherst (434-946-2316), Appomattox (434-352-8239), Bedford (540-586-5429) y Rustburg (434-332-5149).',
    ARRAY['Lynchburg', 'Amherst', 'Appomattox', 'Bedford', 'Campbell'],
