  (
    'da000001-0193-4000-8000-000000000001',
    'Cumberland Mountain Community Services Board',
    'Cumberland Mountain Community Services Board serves Buchanan, Russell, and Tazewell counties from more than twenty locations, offering mental health, substance use, and developmental disability services including crisis intervention, assessment, case management, psychiatric care, counseling, and psychosocial rehabilitation. Satellite outpatient offices in Grundy, Lebanon, and Tazewell put care within reach of this 1,500-square-mile rural service area.',
    'Cumberland Mountain Community Services Board sirve a los condados de Buchanan, Russell y Tazewell desde más de veinte ubicaciones, ofreciendo servicios de salud mental, uso de sustancias y discapacidades del desarrollo, incluidos intervención en crisis, evaluación, manejo de caso, atención psiquiátrica, consejería y rehabilitación psicosocial. Las oficinas satélite en Grundy, Lebanon y Tazewell acercan la atención a esta área rural de 1,500 millas cuadradas.',
    'c1000001-0004-4000-8000-000000000001',
    'Virginia',
