    'Residentes de los condados de Buchanan, Russell y Tazewell; servicios para todas las edades y todo diagnóstico conductual o del desarrollo; se aceptan tarifas móviles y Medicaid.',
    'Call 276-964-6702 for an assessment; 24-hour emergencies 800-286-0586; satellite offices: Grundy 276-935-7154, Lebanon 276-889-3785, Tazewell 276-988-7961.',
    'Llame al 276-964-6702 para una evaluación; emergencias 24 horas 800-286-0586; oficinas satélite: Grundy 276-935-7154, Lebanon 276-889-3785, Tazewell 276-988-7961.',
