  (
    'da000001-0194-4000-8000-000000000001',
    'Mount Rogers Community Services',
    'Mount Rogers Community Services is the community services board for Bland, Carroll, Grayson, Smyth, and Wythe counties and the City of Galax, providing mental health, substance use disorder, and developmental disability services since 1972. Community counseling centers in each locality offer outpatient therapy, psychiatric services, case management, crisis care, and employment support services for people with disabilities.',
    'Mount Rogers Community Services es la junta de servicios comunitarios de los condados de Bland, Carroll, Grayson, Smyth y Wythe y la ciudad de Galax, brindando servicios de salud mental, trastornos por uso de sustancias y discapacidades del desarrollo desde 1972. Los centros de consejería comunitaria de cada localidad ofrecen terapia ambulatoria, servicios psiquiátricos, manejo de caso, atención de crisis y apoyo de empleo para personas con discapacidades.',
    'c1000001-0004-4000-8000-000000000001',
    'Virginia',
    'Wythe',
    'Wytheville',
    '770 W Ridge Road',
    '276-223-3200',
    'https://www.mountrogers.org/',
    'info@mountrogers.org',
    'Monday–Friday business hours; crisis services 24/7',
    'Residents of Bland, Carroll, Grayson, Smyth, and Wythe counties and Galax; anyone may make a referral by calling the community counseling center in their area.',
    'Residentes de los condados de Bland, Carroll, Grayson, Smyth y Wythe y de Galax; cualquiera puede hacer una referencia llamando al centro de consejería comunitaria de su área.',
    'Administrative office 276-223-3200 or toll-free 866-589-0265; counseling centers operate in Wytheville, Marion, Galax, Hillsville, and Independence—see the Locations tab on the website.',
    'Oficina administrativa 276-223-3200 o línea gratuita 866-589-0265; hay centros de consejería en Wytheville, Marion, Galax, Hillsville e Independence—vea la pestaña Locations del sitio web.',
