  (
    'da000001-0195-4000-8000-000000000001',
    'New River Valley Community Services',
    'New River Valley Community Services is the community services board for the counties of Floyd, Giles, Montgomery, and Pulaski and the City of Radford, offering comprehensive outpatient behavioral health, developmental disability, substance use, and prevention programs for children, adults, and families. The main Montgomery Center in Blacksburg provides assessments, therapy, psychiatric care, and same-day crisis response, with offices in each locality.',
    'New River Valley Community Services es la junta de servicios comunitarios de los condados de Floyd, Giles, Montgomery y Pulaski y la ciudad de Radford, con programas ambulatorios integrales de salud conductual, discapacidades del desarrollo, uso de sustancias y prevención para niños, adultos y familias. El Montgomery Center principal en Blacksburg ofrece evaluaciones, terapia, atención psiquiátrica y respuesta de crisis el mismo día, con oficinas en cada localidad.',
    'c1000001-0004-4000-8000-000000000001',
    'Virginia',
    'Montgomery',
    'Blacksburg',
    '700 University City Boulevard',
    '540-961-8300',
    'https://www.nrvcs.org/',
    'info@nrvcs.org',
    'Monday–Friday 8:30 a.m.–5:00 p.m. (Tue/Thu until 7:00 p.m.); crisis line 24/7',
    'Residents of Floyd, Giles, Montgomery, and Pulaski counties and Radford; sign and foreign language interpreters available; sliding fees and Medicaid accepted.',
    'Residentes de los condados de Floyd, Giles, Montgomery y Pulaski y de Radford; intérpretes de señas y de idiomas disponibles; se aceptan tarifas móviles y Medicaid.',
    'Business and non-emergency calls 540-961-8300; in crisis call 988 or 540-961-8400; Montgomery Center open late Tuesdays and Thursdays until 7 p.m.',
    'Llamadas de negocios y no urgentes 540-961-8300; en crisis llame al 988 o al 540-961-8400; el Montgomery Center abre hasta las 7 p.m. martes y jueves.',
