  (
    'da000001-0196-4000-8000-000000000001',
    'Rappahannock Area Community Services Board (RACSB)',
    'RACSB provides behavioral health, developmental disability, substance use, prevention, and early intervention services to the City of Fredericksburg and the counties of Caroline, King George, Spotsylvania, and Stafford, with an outpatient clinic in each of the five localities. Licensed clinicians offer individual, group, and family therapy, psychiatric assessment and medication management, case management, and 24/7 emergency services.',
    'RACSB brinda servicios de salud conductual, discapacidades del desarrollo, uso de sustancias, prevención e intervención temprana a la ciudad de Fredericksburg y los condados de Caroline, King George, Spotsylvania y Stafford, con una clínica ambulatoria en cada una de las cinco localidades. Los clínicos licenciados ofrecen terapia individual, grupal y familiar, evaluación psiquiátrica y manejo de medicamentos, manejo de caso y servicios de emergencia 24/7.',
    'c1000001-0004-4000-8000-000000000001',
    'Virginia',
    'Fredericksburg',
    'Fredericksburg',
    '600 Jackson Street',
    '540-373-3223',
    'https://rappahannockareacsb.org/',
