    'Residentes de Fredericksburg, Caroline, King George, Spotsylvania y Stafford; se aceptan Medicaid y tarifas de escala móvil.',
    'Clinics: Fredericksburg 540-373-3223, Caroline (Ruther Glen) 804-633-9997, King George 540-775-9879, Spotsylvania 540-582-3980, Stafford 540-659-2725; 24-hour emergencies 540-373-6876 (Caroline 804-633-4148, King George 540-775-5064).',
    'Clínicas: Fredericksburg 540-373-3223, Caroline (Ruther Glen) 804-633-9997, King George 540-775-9879, Spotsylvania 540-582-3980, Stafford 540-659-2725; emergencias 24 horas 540-373-6876 (Caroline 804-633-4148, King George 540-775-5064).',
