  (
    'da000001-0197-4000-8000-000000000001',
    'Encompass Community Supports (Rappahannock-Rapidan CSB)',
    'Encompass Community Supports, formerly the Rappahannock-Rapidan Community Services Board, serves Culpeper, Fauquier, Madison, Orange, and Rappahannock counties with behavioral health, substance use, developmental disability, housing, children''s, and aging services—Virginia''s only combined CSB and Area Agency on Aging. Behavioral health clinics in Culpeper and Warrenton provide therapy, psychiatric care, and substance use treatment, with a 24/7 regional crisis line.',
    'Encompass Community Supports, antes la junta de servicios comunitarios Rappahannock-Rapidan, sirve a los condados de Culpeper, Fauquier, Madison, Orange y Rappahannock con servicios de salud conductual, uso de sustancias, discapacidades del desarrollo, vivienda, niñez y envejecimiento—la única agencia combinada de CSB y envejecimiento de Virginia. Las clínicas de Culpeper y Warrenton ofrecen terapia, atención psiquiátrica y tratamiento de uso de sustancias, con línea de crisis regional 24/7.',
    'c1000001-0004-4000-8000-000000000001',
    'Virginia',
    'Culpeper',
    'Culpeper',
    '15361 Bradford Road',
    '540-825-3100',
    'https://www.encompasscommunitysupports.org/',
    NULL,
