  (
    'da000001-0198-4000-8000-000000000001',
    'Piedmont Community Services (Martinsville-area CSB)',
    'Piedmont Community Services is the community services board for the City of Martinsville and the counties of Henry, Franklin, and Patrick, providing mental health, substance use, and developmental disability treatment for individuals and families since 1972. Walk-in screenings and assessments are available at clinical offices in Martinsville, Rocky Mount, and Stuart, alongside a recovery center, psychosocial rehabilitation, and the Lighthouse crisis intervention center.',
    'Piedmont Community Services es la junta de servicios comunitarios de la ciudad de Martinsville y los condados de Henry, Franklin y Patrick, brindando tratamiento de salud mental, uso de sustancias y discapacidades del desarrollo para personas y familias desde 1972. Hay evaluaciones sin cita en las oficinas clínicas de Martinsville, Rocky Mount y Stuart, junto con un centro de recuperación, rehabilitación psicosocial y el centro de intervención en crisis Lighthouse.',
    'c1000001-0004-4000-8000-000000000001',
