  (
    'da000001-0199-4000-8000-000000000001',
    'Danville-Pittsylvania Community Services',
    'Danville-Pittsylvania Community Services provides behavioral health, developmental disability, substance use, and prevention services to residents of the City of Danville and Pittsylvania County from its main campus on Hairston Street in Danville and a Gretna office. Services include assessments, outpatient counseling, psychiatric care, day support, the Harmony House program, and 24-hour behavioral health emergency response.',
    'Danville-Pittsylvania Community Services brinda servicios de salud conductual, discapacidades del desarrollo, uso de sustancias y prevención a los residentes de la ciudad de Danville y el condado de Pittsylvania desde su campus principal en Hairston Street en Danville y una oficina en Gretna. Los servicios incluyen evaluaciones, consejería ambulatoria, atención psiquiátrica, apoyo de día, el programa Harmony House y respuesta de emergencia conductual las 24 horas.',
    'c1000001-0004-4000-8000-000000000001',
