    'Call 434-799-0456 for an assessment Monday–Friday 8:30 a.m.–5 p.m.; 24-hour emergencies 434-793-4922 (toll-free 877-793-4922); Gretna office 434-656-8201.',
    'Llame al 434-799-0456 para una evaluación de lunes a viernes de 8:30 a.m. a 5 p.m.; emergencias 24 horas 434-793-4922 (línea gratuita 877-793-4922); oficina de Gretna 434-656-8201.',
