  (
    'da000001-0200-4000-8000-000000000001',
    'Dickenson County Behavioral Health Services',
    'Dickenson County Behavioral Health Services is the community services board for Dickenson County, offering outpatient mental health and substance use care at its Clinical Services Building in Clintwood. Services include individual, group, family, and marriage therapy, case management, psychiatric services, medication-assisted treatment, mental health skills building, psychosocial day support, and referral to inpatient detox at The Laurels in Lebanon.',
    'Dickenson County Behavioral Health Services es la junta de servicios comunitarios del condado de Dickenson, con atención ambulatoria de salud mental y uso de sustancias en su edificio de servicios clínicos en Clintwood. Ofrece terapia individual, grupal, familiar y de pareja, manejo de caso, servicios psiquiátricos, tratamiento asistido con medicamentos, desarrollo de habilidades de salud mental, apoyo de día psicosocial y referencia a desintoxicación en The Laurels en Lebanon.',
