  (
    'da000001-0201-4000-8000-000000000001',
    'Life Center of Galax — Residential & MAT Programs',
    'Life Center of Galax is an Acadia Healthcare facility in Galax providing detoxification, residential treatment, partial hospitalization, and medication-assisted treatment with methadone and buprenorphine for adults age 18 and older with substance use disorders and co-occurring mental health conditions. The program includes a voluntary faith-based track, a co-occurring disorders program, and a Hillsville campus, with 24/7 nursing supervision during detox and residential care.',
    'Life Center of Galax es un centro de Acadia Healthcare en Galax que ofrece desintoxicación, tratamiento residencial, hospitalización parcial y tratamiento asistido con medicamentos con metadona y buprenorfina para adultos de 18 años o más con trastornos por uso de sustancias y condiciones de salud mental concurrentes. El programa incluye una vía voluntaria basada en la fe, un programa de trastornos concurrentes y un campus en Hillsville, con supervisión de enfermería 24/7 durante la desintoxicación y la atención residencial.',
    'c1000001-0005-4000-8000-000000000001',
    'Virginia',
    'Galax',
    'Galax',
    '112 Painter Street',
    '276-236-2994',
    'https://www.galaxrecovery.com/',
    NULL,
    'Residential and detox 24/7; admissions during business hours',
    'Adults age 18 and older with substance use disorders; co-occurring mental health treatment available; call admissions for bed availability and insurance verification.',
    'Adultos de 18 años o más con trastornos por uso de sustancias; tratamiento de salud mental concurrente disponible; llame a admisiones para disponibilidad de camas y verificación de seguro.',
    'Admissions 276-236-2994 or toll-free 855-716-3827; Hillsville campus at 160 Training Center Road, Woodlawn; Medicare is not accepted per the organization''s website.',
    'Admisiones 276-236-2994 o línea gratuita 855-716-3827; campus de Hillsville en 160 Training Center Road, Woodlawn; según el sitio web de la organización no se acepta Medicare.',
