  (
    'da000001-0202-4000-8000-000000000001',
    'The Laurels Recovery Center (Cumberland Mountain CSB)',
    'The Laurels Recovery Center in Lebanon, operated by Cumberland Mountain Community Services Board, provides regional residential substance use treatment including medically supervised detox and stabilization in Phase I and short-term residential rehabilitation in Phase II. The program accepts voluntary and involuntary admissions, offers counseling, medication services, and peer recovery support, and serves adults from Buchanan, Russell, and Tazewell counties who need inpatient-level SUD care close to home.',
    'The Laurels Recovery Center en Lebanon, operado por Cumberland Mountain Community Services Board, brinda tratamiento residencial regional de uso de sustancias con desintoxicación y estabilización supervisadas médicamente en la Fase I y rehabilitación residencial de corto plazo en la Fase II. El programa acepta admisiones voluntarias e involuntarias, ofrece consejería, servicios de medicamentos y apoyo entre pares, y sirve a adultos de los condados de Buchanan, Russell y Tazewell.',
    'c1000001-0005-4000-8000-000000000001',
    'Virginia',
    'Russell',
    'Lebanon',
    '216 Gilmer Street',
