    'Adultos de 18 años o más con trastornos por uso de sustancias en los condados de Buchanan, Russell o Tazewell; se requiere evaluación previa; se aceptan admisiones voluntarias y por orden judicial.',
    'Call 276-889-3063 or toll-free 888-403-3869 for intake; CMCSB main line 276-964-6702; after-hours emergencies 800-286-0586; visiting hours 8:30 a.m.–4:30 p.m.',
    'Llame al 276-889-3063 o a la línea gratuita 888-403-3869 para admisión; línea principal de CMCSB 276-964-6702; emergencias fuera de horario 800-286-0586; horario de visitas 8:30 a.m.–4:30 p.m.',
