  (
    'da000001-0203-4000-8000-000000000001',
    'Master Center for Addiction Medicine',
    'Master Center for Addiction Medicine is a Virginia outpatient addiction medicine practice with locations in Glen Allen, Richmond, Chesterfield, Hampton, Norfolk, Harrisonburg, and other communities, offering ambulatory detox, medication-assisted treatment, intensive outpatient programs, addiction psychiatry, and certified peer recovery coaching. The practice accepts Medicaid, Medicare, Tricare, and most private insurance, with telehealth and in-person options so people can begin treatment without leaving work or family obligations.',
    'Master Center for Addiction Medicine es una práctica ambulatoria de medicina de adicciones de Virginia con ubicaciones en Glen Allen, Richmond, Chesterfield, Hampton, Norfolk, Harrisonburg y otras comunidades, que ofrece desintoxicación ambulatoria, tratamiento asistido con medicamentos, programas intensivos ambulatorios, psiquiatría de adicciones y coaching certificado entre pares. Acepta Medicaid, Medicare, Tricare y la mayoría de los seguros privados, con opciones de telemedicina y presenciales.',
    'c1000001-0005-4000-8000-000000000001',
    'Virginia',
    'Henrico',
