  (
    'da000001-0204-4000-8000-000000000001',
    'New Day Recovery (Southwest Virginia CHS)',
    'New Day Recovery is an outpatient substance use disorder program operated by Southwest Virginia Community Health Systems with sites in Saltville, Bristol, and North Tazewell, offering office-based addiction treatment with medications such as Suboxone, individual and group therapy, and care coordination. As part of an FQHC network, the program accepts all insurance and offers a sliding fee scale, with extended hours and peer recovery outreach funded through HRSA grants serving rural Southwest Virginia.',
    'New Day Recovery es un programa ambulatorio de trastornos por uso de sustancias operado por Southwest Virginia Community Health Systems con sitios en Saltville, Bristol y North Tazewell, que ofrece tratamiento de adicciones en consultorio con medicamentos como Suboxone, terapia individual y grupal, y coordinación de atención. Como parte de una red FQHC, acepta todos los seguros y ofrece escala de tarifas móvil, con horarios extendidos y alcance entre pares financiado por subvenciones HRSA.',
    'c1000001-0005-4000-8000-000000000001',
