    'Adultos de 18 años o más con trastornos por uso de sustancias, incluidos opioides, alcohol y metanfetamina; complete la documentación de admisión y las evaluaciones requeridas antes de iniciar sesiones grupales o individuales.',
    'Central scheduling 276-496-4492; Saltville site at T.K. McKee 319 Fifth Avenue; additional sites in Bristol and Tazewell listed on the SVCHS website.',
