  (
    'da000001-0205-4000-8000-000000000001',
    'The McShin Foundation — Recovery Community Organization',
    'The McShin Foundation is Virginia''s leading peer-run recovery community organization, operating a 15,000-square-foot recovery center and 16 recovery residences with more than 150 beds in the Richmond area. Certified peer recovery specialists deliver authentic peer-to-peer support, a 28-day residential program, jail recovery programming, family council, daily recovery groups, and linkage to clinical detox and addiction psychiatry for people with substance use disorders statewide.',
    'The McShin Foundation es la principal organización comunitaria de recuperación dirigida por pares de Virginia, con un centro de recuperación de 15,000 pies cuadrados y 16 residencias con más de 150 camas en el área de Richmond. Especialistas certificados en recuperación entre pares brindan apoyo auténtico, un programa residencial de 28 días, programación carcelaria de recuperación, consejo familiar, grupos diarios y conexión con desintoxicación clínica y psiquiatría de adicciones en todo el estado.',
    'c1000001-0012-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    '2300 Dumbarton Road',
    '804-249-1845',
    'https://mcshin.org/',
    'info@mcshin.org',
    'Center Mon–Fri 8:00 a.m.–8:00 p.m.; Sat–Sun 12:00–5:00 p.m.',
    'Anyone seeking recovery from substance use disorders; residential and recovery house programs have separate application processes; jail and family programs available by referral.',
    'Cualquier persona que busque recuperación de trastornos por uso de sustancias; los programas residenciales y de casas de recuperación tienen procesos de solicitud separados; programas carcelarios y familiares disponibles por referencia.',
    'Recovery center open Monday–Friday 8 a.m.–8 p.m. and Saturday–Sunday 12–5 p.m.; email info@mcshin.org; CAPRSS-accredited peer recovery support services.',
    'Centro de recuperación abierto lunes–viernes 8 a.m.–8 p.m. y sábado–domingo 12–5 p.m.; correo info@mcshin.org; servicios de apoyo entre pares acreditados por CAPRSS.',
