  (
    'da000001-0206-4000-8000-000000000001',
    'SAARA of Virginia — Peer Recovery & Advocacy',
    'SAARA (Substance Abuse and Addiction Recovery Alliance) of Virginia is a statewide advocacy and peer support organization that trains certified peer recovery specialists, facilitates recovery groups, and partners with drug courts and behavioral health dockets across Virginia. Through the Alive RVA Recovery Warmline at 833-473-3782, trained peers offer confidential peer-to-peer support for people navigating recovery and for families affected by substance use.',
    'SAARA (Substance Abuse and Addiction Recovery Alliance) of Virginia es una organización estatal de defensa y apoyo entre pares que capacita especialistas certificados en recuperación, facilita grupos de recuperación y colabora con tribunales de drogas y cortes de salud conductual en Virginia. A través de la Alive RVA Recovery Warmline al 833-473-3782, pares capacitados ofrecen apoyo confidencial entre pares a personas en recuperación y familias afectadas.',
    'c1000001-0012-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    '530 E Main Street, Suite 701',
    '804-762-4445',
    'https://www.saara.org/',
    'info@saara.org',
    'Warmline hours vary; office Monday–Friday business hours',
    'Open to Virginians seeking recovery support, family members, and people interested in peer specialist training; warmline available to anyone in the Alive RVA partnership service area.',
    'Abierto a virginianos que buscan apoyo de recuperación, familiares y personas interesadas en capacitación como especialistas entre pares; la línea de apoyo está disponible en el área de servicio de la alianza Alive RVA.',
    'Alive RVA Recovery Warmline 833-473-3782 (833-4PEERVA); office 804-762-4445; peer groups and court docket support listed at saara.org/support.',
    'Alive RVA Recovery Warmline 833-473-3782 (833-4PEERVA); oficina 804-762-4445; grupos entre pares y apoyo en cortes listados en saara.org/support.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Peer recovery warmline', 'Certified peer specialist training', 'Recovery support groups', 'Drug court peer services', 'Family recovery support'],
    ARRAY['peer-support', 'warmline', 'certified-peer-specialist', 'advocacy', 'Richmond', 'statewide'],
    ARRAY[]::TEXT[],
    false,
    'active'
