  (
    'da000001-0207-4000-8000-000000000001',
    'The Chris Atwood Foundation — Recovery Community Center',
    'The Chris Atwood Foundation is a peer-run harm reduction and recovery community organization in Northern Virginia operating a Recovery Community Center in Fairfax City where people connect with certified peer recovery specialists, attend recovery and family support groups, and access free naloxone and the Peer Recovery Academy. The peer warm line at 703-653-4221 offers call-or-text support, and the mobile Comprehensive Harm Reduction program brings peer services and overdose reversal kits into the community.',
    'The Chris Atwood Foundation es una organización comunitaria de reducción de daños y recuperación dirigida por pares en el norte de Virginia que opera un Recovery Community Center en Fairfax City donde las personas se conectan con especialistas certificados, asisten a grupos de recuperación y apoyo familiar, y acceden a naloxona gratuita y la Peer Recovery Academy. La línea de apoyo entre pares al 703-653-4221 ofrece ayuda por llamada o texto, y el programa móvil de reducción de daños integral lleva servicios y kits de reversión de sobredosis a la comunidad.',
    'c1000001-0012-4000-8000-000000000001',
    'Virginia',
    'Fairfax City',
    'Fairfax',
    '10301 Democracy Lane, Suite 150',
    '703-653-4221',
    'https://www.thecaf.org/',
    NULL,
    'RCC hours vary; peer warm line availability posted on website',
    'Open to people in recovery, people actively using substances seeking harm reduction, and families; all peer services are free; no insurance required for naloxone or warm line support.',
    'Abierto a personas en recuperación, personas que usan sustancias activamente que buscan reducción de daños y familias; todos los servicios entre pares son gratuitos; no se requiere seguro para naloxona o la línea de apoyo.',
    'Peer warm line call or text 703-653-4221; RCC entrance on ground floor facing Blenheim Boulevard; mobile CHR van schedule posted at thecaf.org/chr.',
    'Línea de apoyo entre pares llamada o texto 703-653-4221; entrada del RCC en planta baja frente a Blenheim Boulevard; horario de la van móvil CHR publicado en thecaf.org/chr.',
    ARRAY['Fairfax', 'Fairfax City', 'Arlington', 'Loudoun', 'Prince William'],
