  -- source id: 208
  (
    'da000001-0208-4000-8000-000000000001',
    'Bland Ministry Center — Food Pantry & Clothes Closet',
    'Bland Ministry Center in Bland provides free emergency food boxes through a volunteer-run food pantry and a clothes closet where families may take up to 50 pounds of donated clothing, accessories, and home goods per member each year. The pantry distributes USDA food boxes on Tuesdays and Thursdays with a rotating schedule by county, and the benevolence program offers limited emergency assistance for utilities, transportation, and other crises after an in-person application.',
    'Bland Ministry Center en Bland ofrece cajas de alimentos de emergencia gratuitas mediante una despensa administrada por voluntarios y un ropero donde las familias pueden llevarse hasta 50 libras de ropa, accesorios y artículos del hogar donados por miembro al año. La despensa distribuye cajas del USDA los martes y jueves con un calendario rotativo por condado, y el programa de benevolencia ofrece asistencia limitada de emergencia para servicios públicos, transporte y otras crisis tras una solicitud en persona.',
    'c1000001-0015-4000-8000-000000000001',
    'Virginia',
    'Bland',
    'Bland',
    '65 Seddon Street',
    '276-688-4701',
    'https://www.blandministrycenter.org/',
    'dhoosier@blandministrycenter.org',
    'Food pantry Tuesday and Thursday, 10:00 a.m.–1:00 p.m.; clothes closet Tuesday and Wednesday mornings',
    'Anyone in need may register at the food pantry warehouse on distribution days; clothes closet open to all on scheduled days; benevolence requires an in-person application.',
    'Cualquier persona necesitada puede registrarse en la bodega de la despensa en los días de distribución; el ropero está abierto a todos en los días programados; la benevolencia requiere una solicitud en persona.',
    'Food pantry Tue/Thu 10 a.m.–1 p.m. (closed when Bland County Schools are closed); clothes closet Tue 10 a.m.–1 p.m. and Wed 10 a.m.–noon; one food box per household per month.',
    'Despensa mar/jue 10 a.m.–1 p.m. (cerrada cuando las escuelas del condado de Bland están cerradas); ropero mar 10 a.m.–1 p.m. y mié 10 a.m.–mediodía; una caja de alimentos por hogar al mes.',
