  (
    'da000001-0209-4000-8000-000000000001',
    'Ghent Area Ministry — Emergency Assistance',
    'Ghent Area Ministry is a faith-based coalition of Ghent-area congregations providing compassionate assistance to marginalized, low-income, and homeless residents of Norfolk. The ministry helps with clothing, limited utility assistance when a disconnection notice is present, prescription medication co-pays (excluding narcotics and psychotropics), city bus passes, and travel assistance, with face-to-face interviews required before aid is approved.',
    'Ghent Area Ministry es una coalición basada en la fe de congregaciones del área de Ghent que brinda asistencia compasiva a residentes marginados, de bajos ingresos y sin hogar de Norfolk. El ministerio ayuda con ropa, asistencia limitada de servicios públicos cuando hay aviso de corte, copagos de medicamentos recetados (excluyendo narcóticos y psicotrópicos), pases de autobús urbano y ayuda de transporte, con entrevistas presenciales requeridas antes de aprobar la ayuda.',
    'c1000001-0015-4000-8000-000000000001',
    'Virginia',
    'Norfolk',
    'Norfolk',
    '1301 Colonial Avenue, Suite 2',
    '757-622-0438',
    'https://www.gamhelpsnorfolk.org/',
    NULL,
    'Monday–Friday, 10:00 a.m.–2:00 p.m.',
    'Residents of the City of Norfolk only; financial assistance limited to once in a 12-month period; must complete an application and interview with the director or assistant director.',
    'Solo residentes de la ciudad de Norfolk; asistencia financiera limitada a una vez en un período de 12 meses; debe completar una solicitud y entrevista con el director o subdirector.',
    'Walk-ins and telephone inquiries welcome Monday–Friday 10 a.m.–2 p.m.; bring a utility disconnection notice for utility help; Spanish-speaking staff available.',
    'Se aceptan visitas y consultas telefónicas lunes–viernes 10 a.m.–2 p.m.; traiga un aviso de corte de servicios para ayuda con servicios públicos; personal que habla español disponible.',
