  (
    'da000001-0210-4000-8000-000000000001',
    'Mercy Mall of Virginia',
    'Mercy Mall of Virginia is a free clothing and housewares boutique in North Chesterfield for individuals and families in crisis, including homelessness, domestic violence, substance use recovery, incarceration, house fires, and extreme poverty. By appointment, clients receive new and gently used clothing, shoes, baby gear, kitchen supplies, linens, toiletries, and cleaning supplies through curbside pickup, with no geographic restrictions and no income documentation required.',
    'Mercy Mall of Virginia es una boutique gratuita de ropa y artículos del hogar en North Chesterfield para personas y familias en crisis, incluida falta de vivienda, violencia doméstica, recuperación de uso de sustancias, encarcelación, incendios y pobreza extrema. Con cita, los clientes reciben ropa nueva y usada, zapatos, artículos para bebés, utensilios de cocina, ropa de cama, artículos de higiene y limpieza mediante recogida en la acera, sin restricciones geográficas ni documentación de ingresos.',
    'c1000001-0015-4000-8000-000000000001',
    'Virginia',
    'Chesterfield',
    'North Chesterfield',
    '7519 Whitepine Road',
    '804-728-2928',
    'https://mercymallva.org/',
    'info@mercymallva.org',
    'Monday–Thursday, 9:00 a.m.–2:30 p.m. by appointment',
    'Individuals and families experiencing a qualifying crisis; no geographic borders; appointment required via the Get Help tab on the website or by texting 804-728-2928.',
    'Personas y familias que enfrentan una crisis calificada; sin límites geográficos; cita requerida mediante la pestaña Get Help del sitio web o enviando un mensaje de texto al 804-728-2928.',
    'Curbside pickup appointments Monday–Thursday mid-day; text 804-728-2928 with your name and situation for timely needs; for food call Feed More Hunger Help Line 804-237-8617.',
    'Citas de recogida en la acera lunes–jueves al mediodía; envíe un mensaje al 804-728-2928 con su nombre y situación para necesidades urgentes; para alimentos llame a Feed More Hunger Help Line 804-237-8617.',
    ARRAY['Chesterfield', 'Richmond City', 'Henrico', 'Colonial Heights', 'Amelia', 'Goochland', 'Powhatan'],
