  (
    'da000001-0211-4000-8000-000000000001',
    'Micah Ecumenical Ministries — Hospitality Services Network',
    'Micah Ecumenical Ministries coordinates basic-needs hospitality for people experiencing homelessness in Fredericksburg through a network of downtown partner churches rather than a single walk-in center. Free community meals, shower access, bagged lunch pickup, and clothing resources are available on rotating weekday schedules, with Micah outreach staff present to connect neighbors to housing, the winter shelter, and other regional services.',
    'Micah Ecumenical Ministries coordina servicios de hospitalidad de necesidades básicas para personas sin hogar en Fredericksburg a través de una red de iglesias aliadas del centro en lugar de un solo centro sin cita. Hay comidas comunitarias gratuitas, acceso a duchas, recogida de almuerzos empacados y recursos de ropa en horarios rotativos entre semana, con personal de alcance de Micah presente para conectar a los vecinos con vivienda, refugio de invierno y otros servicios regionales.',
    'c1000001-0015-4000-8000-000000000001',
    'Virginia',
    'Fredericksburg',
    'Fredericksburg',
    '1013 Princess Anne Street',
    '540-358-5801',
    'https://micahfredericksburg.org/',
    NULL,
    'Meal and shower schedules vary by partner church; call Help Line for current times',
    'Anyone experiencing homelessness or housing instability in the Fredericksburg region; call the Homeless Help Line for current meal, shower, and clothing locations and times.',
    'Cualquier persona sin hogar o con inestabilidad de vivienda en la región de Fredericksburg; llame a la Homeless Help Line para ubicaciones y horarios actuales de comidas, duchas y ropa.',
    'Homeless Help Line 540-358-5801 directs callers to daily meal sites, shower locations (FXBG Baptist Church Mon/Tue/Thu/Fri 9–11 a.m.), and bagged lunch pickup schedules; winter shelter coordinated separately.',
    'La Homeless Help Line 540-358-5801 dirige a los llamantes a sitios de comidas diarias, ubicaciones de duchas (FXBG Baptist Church lun/mar/jue/vie 9–11 a.m.) y horarios de almuerzos empacados; refugio de invierno coordinado por separado.',
