  (
    'da000001-0212-4000-8000-000000000001',
    'The Least of These Ministry — Showers & Street Outreach',
    'The Least of These Ministry serves unsheltered men and women in the Roanoke Valley with showers, laundry access, loving lunches, coffee, and housing search help from its Luck Avenue facility. Open Monday, Wednesday, and Friday mornings, the ministry provides soap, razors, towels, and refreshments while guests wait for a shower, and assists eligible homeless friends with move-in essentials when they secure affordable housing.',
    'The Least of These Ministry sirve a hombres y mujeres sin refugio en el valle de Roanoke con duchas, acceso a lavandería, almuerzos solidarios, café y ayuda de búsqueda de vivienda desde su instalación en Luck Avenue. Abierto lunes, miércoles y viernes por la mañana, el ministerio proporciona jabón, rastrillos, toallas y refrigerios mientras los huéspedes esperan su turno, y ayuda a amigos elegibles con artículos de mudanza cuando consiguen vivienda asequible.',
    'c1000001-0015-4000-8000-000000000001',
    'Virginia',
    'Roanoke City',
    'Roanoke',
    '422 Luck Avenue SW',
    '540-556-3200',
    'https://www.theleastoftheseministry.org/',
    'roaleastofthese@yahoo.com',
    'Monday, Wednesday, Friday, 10:30 a.m.–2:30 p.m.',
    'Unsheltered individuals in the Roanoke Valley; showers and lunches available during open hours or by appointment; housing assistance provided when resources allow.',
    'Personas sin refugio en el valle de Roanoke; duchas y almuerzos disponibles durante el horario de apertura o con cita; asistencia de vivienda cuando hay recursos.',
    'Open Mon/Wed/Fri 10:30 a.m.–2:30 p.m.; donation drop-offs welcome same hours; mailing address 602 Marshall Avenue SW; call or email Dawn Sandoval for appointments.',
    'Abierto lun/mié/vie 10:30 a.m.–2:30 p.m.; donaciones bienvenidas en el mismo horario; dirección postal 602 Marshall Avenue SW; llame o escriba a Dawn Sandoval para citas.',
