  -- source id: 213
  (
    'da000001-0213-4000-8000-000000000001',
    'The Salvation Army Lynchburg — Center of Hope Emergency Services',
    'The Salvation Army Center of Hope in Lynchburg provides emergency shelter, a food pantry, a clothes closet, hot meals, and limited rent and utility assistance to struggling individuals and families across Lynchburg and surrounding counties. Applicants need an active eviction notice for rental help or a utility shutoff or past-due notice for energy assistance, and the center serves as a warming and cooling station during extreme temperatures.',
    'The Salvation Army Center of Hope en Lynchburg ofrece refugio de emergencia, despensa de alimentos, ropero, comidas calientes y asistencia limitada de renta y servicios públicos a personas y familias en dificultades en Lynchburg y los condados cercanos. Los solicitantes necesitan un aviso de desalojo activo para ayuda de renta o un aviso de corte o pago atrasado para asistencia de energía, y el centro funciona como estación de calor y frescor en temperaturas extremas.',
    'c1000001-0015-4000-8000-000000000001',
    'Virginia',
    'Lynchburg',
    'Lynchburg',
    '2211 Park Avenue',
    '434-845-5939',
    'https://salvationarmypotomac.org/lynchburgva/',
    NULL,
    'Office Monday–Friday, 9:00 a.m.–4:00 p.m.; shelter intake 9:30 a.m.–3:30 p.m.',
    'Residents of Lynchburg, Amherst, Appomattox, Bedford, Campbell, and Nelson counties; utility help requires shutoff notice; rental help requires eviction notice; shelter intake Mon–Fri 9:30 a.m.–3:30 p.m.',
    'Residentes de Lynchburg y los condados de Amherst, Appomattox, Bedford, Campbell y Nelson; ayuda de servicios requiere aviso de corte; ayuda de renta requiere aviso de desalojo; admisión al refugio lun–vie 9:30 a.m.–3:30 p.m.',
    'Call 434-845-5939 for shelter availability weekdays; after 4:30 p.m. and weekends call housing monitors 434-941-4701; Spanish-speaking staff available.',
    'Llame al 434-845-5939 para disponibilidad de refugio entre semana; después de las 4:30 p.m. y fines de semana llame a monitores de vivienda 434-941-4701; personal que habla español disponible.',
    ARRAY['Lynchburg', 'Amherst', 'Appomattox', 'Bedford', 'Campbell', 'Nelson'],
