  -- source id: 214
  (
    'da000001-0214-4000-8000-000000000001',
    'FACETS — Hot Meals & Emergency Food Assistance',
    'FACETS operates Northern Virginia''s longest-running hot meals program, serving a hot dinner 365 nights a year at two Fairfax County locations through more than 50 faith partners, plus biweekly fresh produce distributions and an emergency pantry with diapers and household items. The hypothermia prevention shelter line operates seasonally, and FACETS connects Fairfax County residents to coordinated services for shelter, employment, and financial help through county referral partners.',
    'FACETS opera el programa de comidas calientes más antiguo del norte de Virginia, sirviendo cena caliente las 365 noches del año en dos ubicaciones del condado de Fairfax con más de 50 aliados de fe, además de distribuciones quincenales de productos frescos y una despensa de emergencia con pañales y artículos del hogar. La línea del refugio de prevención de hipotermia opera de forma estacional, y FACETS conecta a los residentes del condado de Fairfax con servicios coordinados de refugio, empleo y ayuda financiera.',
    'c1000001-0015-4000-8000-000000000001',
    'Virginia',
    'Fairfax',
    'Fairfax',
    '10700 Page Avenue, Suite 160',
    '703-352-5090',
    'https://facetscares.org/',
    NULL,
    'Hot meals nightly; office Monday–Friday business hours',
    'Hot meals open to anyone in need at published locations; emergency food, diapers, and hypothermia shelter referrals for Fairfax County residents; county CSP intake at 703-222-0880 for broader services.',
    'Comidas calientes abiertas a cualquier persona necesitada en ubicaciones publicadas; alimentos de emergencia, pañales y referencias de refugio de hipotermia para residentes del condado de Fairfax; admisión del condado CSP al 703-222-0880 para servicios más amplios.',
    'Emergency food or diapers call front desk 703-352-5090; hypothermia shelter line ext. 1302 seasonal (Sunday after Thanksgiving through April 1); Fairfax County CSP 703-222-0880 Mon–Fri 8 a.m.–4:30 p.m.',
    'Alimentos de emergencia o pañales llame a recepción 703-352-5090; línea de refugio de hipotermia ext. 1302 estacional (domingo después de Acción de Gracias hasta el 1 de abril); CSP del condado de Fairfax 703-222-0880 lun–vie 8 a.m.–4:30 p.m.',
    ARRAY['Fairfax'],
    'single',
    ARRAY['Daily hot meals', 'Fresh produce distribution', 'Emergency food pantry', 'Diaper assistance', 'Hypothermia prevention shelter referral'],
    ARRAY['basic-needs', 'hot-meals', 'food-pantry', 'hypothermia-shelter', 'Northern-Virginia', 'Fairfax'],
    ARRAY[]::TEXT[],
    false,
    'active'
