  -- source id: 215
  (
    'da000001-0215-4000-8000-000000000001',
    'Rescue Mission of Roanoke — Manna Food Pantry',
    'The Rescue Mission of Roanoke''s Manna Food Pantry distributes weekly grocery boxes of about 60 pounds—including non-perishable staples, fresh produce, frozen meat, and pet food—to struggling families in the Roanoke region through a drive-thru model partnered with Feeding Southwest Virginia. Enrolled recipients also receive free clothing vouchers for the Mission''s Donation Center, connecting food insecurity with basic apparel and household needs.',
    'La despensa Manna Food Pantry de la Rescue Mission of Roanoke distribuye semanalmente cajas de comestibles de unas 60 libras—incluidos productos básicos no perecederos, productos frescos, carne congelada y alimento para mascotas—a familias en dificultades de la región de Roanoke mediante un modelo drive-thru en alianza con Feeding Southwest Virginia. Los inscritos también reciben vales gratuitos de ropa para el Donation Center de la Misión.',
    'c1000001-0015-4000-8000-000000000001',
    'Virginia',
    'Roanoke City',
    'Roanoke',
    '402 4th Street SE',
    '540-598-5203',
    'https://rescuemission.net/manna-food-pantry/',
    NULL,
    'Distribution Wednesday and Thursday, 1:00–3:00 p.m. for enrolled clients',
    'Open registration for families in the Roanoke region; enroll by text only at 540-598-5203; once enrolled, reserved boxes picked up Wed or Thu 1–3 p.m.',
    'Inscripción abierta para familias de la región de Roanoke; inscríbase solo por mensaje de texto al 540-598-5203; una vez inscrito, recoja cajas reservadas mié o jue 1–3 p.m.',
    'Text 540-598-5203 to enroll; save reservation texts with QR codes for faster check-in; clothing vouchers redeemable at Donation Center 421 Fourth Street; equal opportunity provider.',
    'Envíe un mensaje al 540-598-5203 para inscribirse; guarde los mensajes de reserva con códigos QR para registro más rápido; vales de ropa canjeables en Donation Center 421 Fourth Street; proveedor de igualdad de oportunidades.',
    ARRAY['Roanoke City', 'Roanoke', 'Salem', 'Botetourt', 'Craig', 'Floyd', 'Franklin', 'Alleghany'],
