    ARRAY['Weekly grocery boxes', 'Fresh produce and protein', 'Pet food', 'Clothing vouchers', 'Drive-thru food distribution'],
    ARRAY['basic-needs', 'food-pantry', 'clothing-vouchers', 'drive-thru', 'Roanoke', 'rescue-mission'],
    ARRAY[]::TEXT[],
    false,
    'active'
