  -- source id: 216
  (
    'da000001-0216-4000-8000-000000000001',
    'Assisting Families of Inmates (AFOI)',
    'Assisting Families of Inmates is a Richmond-based nonprofit that keeps incarcerated Virginians connected to spouses, children, and parents through video visitation at ten visitor centers statewide, a transportation program for prison visits, DJJ family transportation, and children''s services including the MAC program. By reducing isolation and supporting family reunification, AFOI helps returning citizens and their loved ones maintain relationships critical to successful reentry.',
    'Assisting Families of Inmates es una organización sin fines de lucro con sede en Richmond que mantiene a los virginianos encarcelados conectados con cónyuges, hijos y padres mediante visitas por video en diez centros de visitantes en el estado, un programa de transporte para visitas a prisiones, transporte familiar del DJJ y servicios para niños incluido el programa MAC. Al reducir el aislamiento y apoyar la reunificación familiar, AFOI ayuda a quienes regresan y a sus seres queridos a mantener relaciones críticas para una reinserción exitosa.',
    'c1000001-0011-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    '220 Hull Street, Suite 100',
    '804-643-2401',
    'https://afoi.org/',
    'family@afoi.org',
    'Office Monday–Friday business hours; Richmond video center Saturday–Sunday',
    'Families of people incarcerated in Virginia state prisons or DJJ facilities; video visitor centers serve all major VADOC institutions; register through AFOI for visitor center visitation.',
    'Familias de personas encarceladas en prisiones estatales de Virginia o instalaciones del DJJ; los centros de visitas por video sirven a las principales instituciones de VADOC; regístrese a través de AFOI para visitas en centros de visitantes.',
    'Richmond visitor center open Saturdays and Sundays at 220 Hull Street; register or ask video questions at 804-643-2401 or family@afoi.org; transportation program resumed March 2023.',
    'Centro de visitantes de Richmond abierto sábados y domingos en 220 Hull Street; regístrese o pregunte sobre video al 804-643-2401 o family@afoi.org; programa de transporte reanudado en marzo de 2023.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Video visitation centers', 'Prison visit transportation', 'DJJ family transportation', 'Children''s MAC program', 'Family reunification support'],
    ARRAY['family-children', 'incarcerated-parents', 'video-visitation', 'reunification', 'reentry', 'Richmond', 'statewide'],
    ARRAY['accepts_criminal_record'],
    false,
    'active'
  ),
  -- source id: 217
  (
    'da000001-0217-4000-8000-000000000001',
    'Seton Youth Services — Mentoring Children of Prisoners (MCP)',
    'Seton Youth Services operates the free Mentoring Children of Prisoners program for Hampton Roads youth ages 4–18 who have been affected by the past or present incarceration of a parent or adult loved one. Each child is matched with a volunteer mentor age 20 or older for at least four hours per month for one year, providing recreational outings, homework help, and consistent adult friendship—not substitute parenting—for children navigating parental incarceration.',
    'Seton Youth Services opera el programa gratuito Mentoring Children of Prisoners para jóvenes de Hampton Roads de 4 a 18 años afectados por la encarcelación pasada o presente de un padre o adulto querido. Cada niño es emparejado con un mentor voluntario de 20 años o más durante al menos cuatro horas al mes por un año, con salidas recreativas, ayuda con tareas y amistad adulta constante—no sustituto de crianza—para niños que enfrentan la encarcelación de un padre.',
    'c1000001-0011-4000-8000-000000000001',
    'Virginia',
    'Virginia Beach',
    'Virginia Beach',
    '101 N Lynnhaven Road, Suite 101',
    '757-646-9965',
    'https://setonyouthservices.org/mentoring/',
    'cday@setonyouthservices.org',
    'Mentoring by appointment; office Monday–Friday business hours',
    'Youth ages 4–18 in Virginia Beach, Norfolk, Portsmouth, Chesapeake, Newport News, or Hampton affected by a parent or loved one''s incarceration; mentors must be age 20+ and pass background checks.',
    'Jóvenes de 4 a 18 años en Virginia Beach, Norfolk, Portsmouth, Chesapeake, Newport News o Hampton afectados por la encarcelación de un padre o ser querido; los mentores deben tener 20 años o más y pasar verificaciones de antecedentes.',
    'Contact Director of Mentoring Charliesa Day at 757-646-9965 or cday@setonyouthservices.org; mentee and mentor applications online; administrative office 757-963-5795.',
    'Contacte a la directora de mentoría Charliesa Day al 757-646-9965 o cday@setonyouthservices.org; solicitudes de mentees y mentores en línea; oficina administrativa 757-963-5795.',
    ARRAY['Virginia Beach', 'Norfolk', 'Portsmouth', 'Chesapeake', 'Newport News', 'Hampton'],
    'multi',
    ARRAY['One-to-one mentoring', 'Recreational outings', 'Homework support', 'Caregiver communication', 'Volunteer mentor matching'],
    ARRAY['family-children', 'mentoring', 'incarcerated-parents', 'youth', 'Hampton-Roads', 'free'],
    ARRAY[]::TEXT[],
    false,
    'active'
