  -- source id: 218
  (
    'da000001-0218-4000-8000-000000000001',
    'GRTC CARE Paratransit',
    'GRTC''s CARE (Community Assisted Ride Enterprise) paratransit program provides ADA origin-to-destination curb-to-curb transportation for seniors and people with disabilities who cannot use fixed-route buses in Richmond, Henrico, and portions of Chesterfield. CARE operates within three-quarters of a mile of GRTC bus lines with reservation-based vans and sedans, and CARE Plus extends trips farther into Henrico or Chesterfield for a fee.',
    'El programa de paratransporte CARE (Community Assisted Ride Enterprise) de GRTC ofrece transporte de origen a destino de acera a acera conforme a la ADA para adultos mayores y personas con discapacidades que no pueden usar autobuses de ruta fija en Richmond, Henrico y partes de Chesterfield. CARE opera dentro de tres cuartos de milla de las líneas de autobús de GRTC con vans y sedanes bajo reserva, y CARE Plus extiende viajes más lejos en Henrico o Chesterfield con tarifa.',
    'c1000001-0010-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    '301 East Belt Boulevard',
    '804-782-2273',
    'https://www.ridegrtc.com/grtc-services/care-paratransit/',
    'adacoordinator@ridegrtc.com',
    'CARE Mon–Fri 7:00 a.m.–5:00 p.m.; Sat–Sun 8:00 a.m.–4:30 p.m.',
    'ADA-eligible riders who cannot use fixed-route service; apply through GRTC''s Eligibility Coordinator; riders 80+ may apply for a paratransit ID card; visitors with paratransit eligibility may use CARE up to 21 days per year.',
    'Pasajeros elegibles conforme a la ADA que no pueden usar servicio de ruta fija; solicite a través del coordinador de elegibilidad de GRTC; pasajeros de 80 años o más pueden solicitar una tarjeta de identificación de paratransporte; visitantes con elegibilidad de paratransporte pueden usar CARE hasta 21 días al año.',
    'Schedule rides at 804-782-2273; eligibility questions 804-358-3871 ext. 434; customer service 804-358-4782; completed applications mailed to 301 East Belt Boulevard (not accepted by fax).',
    'Programe viajes al 804-782-2273; preguntas de elegibilidad 804-358-3871 ext. 434; servicio al cliente 804-358-4782; solicitudes completas por correo a 301 East Belt Boulevard (no se aceptan por fax).',
    ARRAY['Richmond City', 'Henrico', 'Chesterfield'],
    'multi',
    ARRAY['Curb-to-curb paratransit', 'ADA eligibility certification', 'CARE Plus extended trips', 'Visitor paratransit privileges', 'Reduced-fare ID cards'],
    ARRAY['transportation', 'paratransit', 'ADA', 'seniors', 'disabilities', 'Richmond'],
    ARRAY[]::TEXT[],
    false,
    'active'
  ),
  -- source id: 219
  (
    'da000001-0219-4000-8000-000000000001',
    'Mountain Empire Transit (MEOC)',
    'Mountain Empire Older Citizens operates Mountain Empire Transit, the public transportation provider for Lee, Scott, and Wise counties and the City of Norton across nearly 1,390 square miles. Free demand-response curb-to-curb trips run Monday through Friday 7 a.m.–5 p.m. with 24-hour advance booking, and the METGo! on-demand microtransit app serves Wise–Norton, Big Stone Gap–Appalachia, and Pennington Gap–Jonesville zones for same-day rides.',
    'Mountain Empire Older Citizens opera Mountain Empire Transit, el proveedor de transporte público de los condados de Lee, Scott y Wise y la ciudad de Norton en casi 1,390 millas cuadradas. Viajes gratuitos bajo demanda de acera a acera de lunes a viernes de 7 a.m. a 5 p.m. con reserva con 24 horas de anticipación, y la aplicación de microtransporte bajo demanda METGo! sirve las zonas Wise–Norton, Big Stone Gap–Appalachia y Pennington Gap–Jonesville para viajes el mismo día.',
    'c1000001-0010-4000-8000-000000000001',
    'Virginia',
    'Wise',
    'Big Stone Gap',
    '1501 Third Avenue East',
    '276-523-7433',
    'https://meoc.org/transportation/',
    'info@meoc.org',
    'Monday–Friday, 7:00 a.m.–5:00 p.m.',
    'Open to the public of all ages; wheelchair-accessible vehicles available; demand-response requires booking at least 24 hours ahead; METGo! riders must be 13+ to travel alone.',
