  (
    'da000001-0220-4000-8000-000000000001',
    'Bay Transit — Demand-Response Public Transit',
    'Bay Transit is the public demand-response transportation service operated by Bay Aging, serving 12 counties and several towns across Virginia''s Northern Neck and Middle Peninsula including Essex, King and Queen, King William, Lancaster, Richmond, Northumberland, Westmoreland, Gloucester, Mathews, Middlesex, Charles City, and New Kent. Riders call the Ride Line at least 24 hours ahead to schedule curb-to-curb trips Monday through Friday for medical appointments, work, shopping, and other essential travel.',
    'Bay Transit es el servicio público de transporte bajo demanda operado por Bay Aging, que sirve a 12 condados y varios pueblos del Northern Neck y la península media de Virginia, incluidos Essex, King and Queen, King William, Lancaster, Richmond, Northumberland, Westmoreland, Gloucester, Mathews, Middlesex, Charles City y New Kent. Los pasajeros llaman a la Ride Line con al menos 24 horas de anticipación para programar viajes de acera a acera de lunes a viernes para citas médicas, trabajo, compras y otros desplazamientos esenciales.',
    'c1000001-0010-4000-8000-000000000001',
    'Virginia',
    'Richmond',
    'Warsaw',
    '111 Commerce Parkway',
    '877-869-6046',
    'https://baytransit.org/',
    NULL,
    'Monday–Friday, 6:00 a.m.–6:00 p.m.',
    'Open to all ages and all trip purposes in the 12-county service area; New Freedom paratransit for eligible riders with disabilities; base fare $2 with ticket book options.',
    'Abierto a todas las edades y propósitos de viaje en el área de 12 condados; New Freedom paratransit para pasajeros elegibles con discapacidades; tarifa base $2 con opciones de libreta de boletos.',
    'Ride Line toll-free 877-869-6046, Mon–Fri 6 a.m.–6 p.m.; Warsaw office 804-250-2011; Gloucester office 804-693-6977; call 24 hours in advance to schedule.',
    'Ride Line gratuita 877-869-6046, lun–vie 6 a.m.–6 p.m.; oficina de Warsaw 804-250-2011; oficina de Gloucester 804-693-6977; llame con 24 horas de anticipación para programar.',
    ARRAY['Essex', 'King and Queen', 'King William', 'Lancaster', 'Richmond', 'Northumberland', 'Westmoreland', 'Gloucester', 'Mathews', 'Middlesex', 'Charles City', 'New Kent'],
