    'Danville Community College Workforce Services and Training connects justice-involved adults who earn GED credentials through Danville ACEC to certificate programs, FastForward workforce credentials, and employer partnerships in advanced manufacturing and healthcare across Southside Virginia. Career navigators help returning citizens enroll in short-term training aligned with Virginia Career Works and regional fair-chance employers. College workforce division—not emergency cash or legal aid.',
    'Danville Community College Workforce Services and Training conecta a adultos con antecedentes penales que obtienen credenciales GED a través de Danville ACEC con programas de certificado, credenciales FastForward y alianzas con empleadores en manufactura avanzada y salud en el Southside de Virginia. Navegadores de carrera ayudan a quienes regresan a inscribirse en capacitación de corto plazo.',
