    'Salem VA Medical Center — Veterans Justice Outreach',
    'Salem VA Medical Center Veterans Justice Outreach specialists connect justice-involved veterans in the Roanoke Valley, New River Valley, and southwest Virginia to VA mental health, substance use treatment, and housing services after contact with local courts and jails. VJO staff provide direct outreach, assessment, and case management—not legal representation. VA enrollment and eligibility determination required for medical services.',
