    'da000001-0250-4000-8000-000000000001',
    'McGuire VA — Health Care for Reentry Veterans (HCRV)',
    'The Health Care for Reentry Veterans program at Hunter Holmes McGuire VA Medical Center provides pre-release outreach and post-release case management for veterans in Virginia state prisons within six months of release, connecting them to VA health care, benefits, and housing resources. HCRV specialist Jim Temple coordinates prison visits and community linkages—not criminal defense or emergency cash. For local jail veterans, contact VJO instead.',
    'El programa Health Care for Reentry Veterans en Hunter Holmes McGuire VA Medical Center ofrece alcance previo a la liberación y manejo de casos posterior para veteranos en prisiones estatales de Virginia dentro de los seis meses previos a la liberación. El especialista HCRV Jim Temple coordina visitas a prisiones y vínculos comunitarios, no defensa penal ni efectivo de emergencia.',
