    'Salem VA — Health Care for Reentry Veterans (HCRV)',
    'Salem VA Medical Center Health Care for Reentry Veterans specialists visit Virginia DOC facilities in western Virginia to meet veterans before release and coordinate VA health care, mental health, substance use treatment, and housing supports in coalfield and southwest Virginia communities. HCRV prevents homelessness and supports veteran reintegration—not a veterans crisis line. Local jail veterans should contact VJO.',
    'Los especialistas Health Care for Reentry Veterans del Salem VA Medical Center visitan instalaciones del DOC de Virginia en el oeste para reunirse con veteranos antes de la liberación y coordinar atención médica del VA, salud mental, tratamiento de uso de sustancias y vivienda en comunidades del suroeste. HCRV previene la falta de vivienda; veteranos en cárceles locales deben contactar VJO.',
