    'da000001-0252-4000-8000-000000000001',
    'Virginia DVS — Abingdon Veterans Services Office',
    'The Virginia Department of Veterans Services Abingdon office helps veterans and families obtain federal and state benefits including disability compensation, health care enrollment, and discharge upgrades, serving justice-involved veterans in Bristol, Russell, Smyth, and Washington counties. Veterans Service Representatives also coordinate with VVFS Justice Involved Services co-located at this site. Benefits advocacy—not emergency mental health crisis response.',
