  (
    'da000001-0255-4000-8000-000000000001',
    'Virginia DVS — Salem/Roanoke Veterans Services Office',
    'The Virginia Department of Veterans Services office at Salem VA Medical Center helps veterans in Roanoke, Salem, Radford, Pulaski, Henry, Patrick, and surrounding localities file VA disability claims, access health care, and connect to VVFS supports for justice-involved veterans rebuilding stability after jail or prison. Co-located with VA campus services—not a DMV or legal aid office. Appointments strongly recommended.',
    'La oficina del Departamento de Servicios para Veteranos en el Salem VA Medical Center ayuda a veteranos en Roanoke, Salem, Radford, Pulaski, Henry, Patrick y localidades circundantes a presentar reclamos de discapacidad del VA, acceder a atención médica y conectarse con apoyos de VVFS para veteranos con antecedentes penales. Citas muy recomendadas.',
