  (
    'da000001-0256-4000-8000-000000000001',
    'VDH Division of Vital Records',
    'The Virginia Department of Health Division of Vital Records issues certified Virginia birth, death, marriage, and divorce certificates needed for DMV IDs, SNAP, Medicaid, and employment after release. Returning citizens born in Virginia may apply by mail to the Richmond office or in person at any DMV customer service center using forms DL-81 or DL-82. Vital records office—not a probation reporting location.',
    'La División de Registros Vitales del Departamento de Salud de Virginia emite certificados oficiales de nacimiento, defunción, matrimonio y divorcio necesarios para identificaciones del DMV, SNAP, Medicaid y empleo después de la liberación. Los ciudadanos que regresan nacidos en Virginia pueden solicitar por correo a la oficina de Richmond o en persona en cualquier centro del DMV.',
    'c1000001-0008-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    '2001 Maywill Street, Suite 101',
    '804-662-6200',
    'https://www.vdh.virginia.gov/vital-records/',
    NULL,
    'Monday–Friday business hours',
    'Virginia-born individuals and eligible immediate family requesting certified vital records with acceptable ID.',
    'Personas nacidas en Virginia y familiares inmediatos elegibles que soliciten registros vitales certificados con identificación aceptable.',
    'Mail applications to P.O. Box 1000, Richmond, VA 23218; $12 mail fee; DMV in-person option prints many records immediately.',
    'Envíe solicitudes a Apartado 1000, Richmond, VA 23218; tarifa por correo $12; opción en persona en DMV imprime muchos registros de inmediato.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Birth certificate issuance', 'Marriage and divorce records', 'Death certificate copies', 'Mail-in applications', 'DMV partnership referrals'],
