  (
    'da000001-0257-4000-8000-000000000001',
    'Virginia DMV Connect — Community Mobile Offices',
    'Virginia DMV Connect mobile teams bring driver''s licenses, state ID cards, vital records ordering, and knowledge testing to libraries, colleges, employers, and community sites across Virginia when returning citizens cannot reach a fixed DMV office. Fourteen regional mobile units serve rural and justice-involved communities after release, with certificates mailed for vital records transactions. Mobile DMV—not emergency cash assistance.',
    'Los equipos móviles Virginia DMV Connect llevan licencias de conducir, tarjetas de identificación estatal, pedidos de registros vitales y exámenes de conocimientos a bibliotecas, colegios y sitios comunitarios en toda Virginia cuando quienes regresan no pueden llegar a una oficina fija del DMV. Catorce unidades móviles regionales sirven comunidades rurales después de la liberación.',
    'c1000001-0008-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    NULL,
    '804-497-7100',
    'https://www.dmv.virginia.gov/locations/mobile-offices',
    NULL,
    'Visit schedules vary by location; check online calendar',
    'Virginia residents needing DMV services at scheduled community visits; walk-ins at some locations per calendar.',
    'Residentes de Virginia que necesitan servicios del DMV en visitas comunitarias programadas; sin cita en algunos sitios según calendario.',
    'View full calendar at dmv.virginia.gov mobile offices; book appointment when required; vital records mailed from VDH.',
    'Vea el calendario completo en oficinas móviles de dmv.virginia.gov; reserve cita cuando se requiera; registros vitales enviados por VDH.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['State ID cards', 'Driver''s licenses', 'Vital records ordering', 'Knowledge testing', 'Address changes'],
