  (
    'da000001-0258-4000-8000-000000000001',
    'Project ID — Virginia ID Assistance',
    'Project ID Action Fund supports Virginia chapters that help justice-involved and low-income residents obtain birth certificates, state IDs, and voting documents by covering fees and navigating multi-step vital records processes. Chapters operate in Richmond, New River Valley, Hampton Roads, and other regions—volunteer-led ID navigation, not clinical treatment or legal representation. Request help through the statewide online form.',
    'Project ID Action Fund apoya capítulos de Virginia que ayudan a residentes con antecedentes penales y de bajos ingresos a obtener certificados de nacimiento, identificaciones estatales y documentos de votación cubriendo tarifas y navegando procesos de registros vitales. Capítulos en Richmond, el valle New River y Hampton Roads; navegación de identificación liderada por voluntarios.',
    'c1000001-0008-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    NULL,
    NULL,
    'https://www.projectidaf.org/virginia',
    NULL,
    'Contact chapter for availability',
    'Virginia residents needing help obtaining government ID who cannot afford fees or navigate records processes alone.',
    'Residentes de Virginia que necesitan ayuda para obtener identificación gubernamental y no pueden pagar tarifas o navegar procesos solos.',
    'Apply at projectidaf.org/virginia; volunteer email idsforlife@projectid.org; chapters include New River Valley and Hampton Roads.',
