  (
    'da000001-0259-4000-8000-000000000001',
    'CommonHelp Virginia — Benefits Portal',
    'CommonHelp is the Virginia Department of Social Services secure online portal where returning citizens and families check eligibility and apply for SNAP, Medicaid, TANF, energy assistance, and child care help after release. Users create an account to submit applications, upload documents, report household changes, and track case status in English and Spanish. Online benefits portal—not a walk-in crisis shelter or legal aid office.',
    'CommonHelp es el portal en línea seguro del Departamento de Servicios Sociales de Virginia donde quienes regresan y las familias verifican elegibilidad y solicitan SNAP, Medicaid, TANF, asistencia energética y ayuda de cuidado infantil después de la liberación. Los usuarios crean una cuenta para enviar solicitudes y rastrear el estado del caso en inglés y español.',
    'c1000001-0001-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    NULL,
    '833-522-5582',
    'https://www.commonhelp.virginia.gov',
