  (
    'da000001-0260-4000-8000-000000000001',
    'Virginia DBHDS — Community Services Board Directory',
    'The Virginia Department of Behavioral Health and Developmental Services maintains the statewide Community Services Board and Behavioral Health Authority directory connecting justice-involved Virginians to local mental health, substance use, and crisis services including 988 and CSB emergency teams in every locality. Returning citizens use the directory to find their county CSB for Medicaid behavioral health intake—not a housing or employment office. Navigation resource with local direct services through CSBs.',
    'El Departamento de Salud Conductual y de Servicios de Desarrollo de Virginia mantiene el directorio estatal de Juntas de Servicios Comunitarios que conecta a virginianos con antecedentes penales con servicios locales de salud mental, uso de sustancias y crisis incluyendo 988 en cada localidad. Recurso de navegación con servicios directos locales a través de CSB.',
    'c1000001-0001-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    '1220 Bank Street',
    '804-786-3921',
    'https://dbhds.virginia.gov/find-help',
    NULL,
    '988 available 24/7; CSB hours vary by locality',
    'Virginia residents seeking public behavioral health or developmental services through their local CSB.',
    'Residentes de Virginia que buscan servicios públicos de salud conductual o del desarrollo a través de su CSB local.',
    'Call 988 for crisis; find local CSB at dbhds.virginia.gov/find-help or vacsb.org directory.',
    'Llame al 988 para crisis; encuentre su CSB en dbhds.virginia.gov/find-help o el directorio vacsb.org.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['CSB locator', 'Crisis services navigation', 'Substance use treatment referrals', 'Mental health intake', '988 crisis routing'],
