  (
    'da000001-0261-4000-8000-000000000001',
    'Goodwill Industries of the Valleys — GoodStart Reentry Program',
    'Goodwill Industries of the Valleys GoodStart Reentry Program provides case management, soft-skills training, occupational skills pathways including welding and CDL preparation, and job placement for justice-involved adults ages 18 and older convicted in Virginia across 35 counties and 14 cities in central and southwest Virginia. The three-phase program reports low recidivism and connects participants to fair-chance employers—not emergency housing.',
    'El programa GoodStart Reentry de Goodwill Industries of the Valleys ofrece manejo de casos, capacitación en habilidades blandas, vías de habilidades ocupacionales incluyendo soldadura y preparación CDL, y colocación laboral para adultos con antecedentes penales de 18 años o más en 35 condados y 14 ciudades del centro y suroeste de Virginia.',
    'c1000001-0003-4000-8000-000000000001',
    'Virginia',
    'Roanoke City',
    'Roanoke',
    'PO Box 2420',
    '540-581-0620',
    'https://www.goodwillvalleys.com',
    NULL,
    'Contact for program intake hours',
    'Virginia adults age 18+ with adult convictions seeking reentry employment services in Goodwill Valleys territory.',
    'Adultos de Virginia de 18 años o más con condenas como adultos que buscan servicios de empleo de reinserción en el territorio de Goodwill Valleys.',
    'Contact Mission Services via goodwillvalleys.com; pairs with VADOC District 15 and Region 5 adult education.',
    'Contacte Mission Services vía goodwillvalleys.com; se vincula con el Distrito 15 de VADOC y educación para adultos Región 5.',
