  (
    'da000001-0262-4000-8000-000000000001',
    'Virginia Has Jobs — Fair Chance Careers',
    'Virginia Has Jobs Fair Chance is a VADOC and Virginia Works partnership portal helping justice-impacted Virginians explore career pathways, connect with fair-chance employers, and access training and registered apprenticeships after release from state custody or local jail. The site maps high-demand industries and skills needed for long-term career growth—not a probation office or emergency cash program. Online career navigation with statewide employer network.',
    'Virginia Has Jobs Fair Chance es un portal de asociación entre VADOC y Virginia Works que ayuda a virginianos con antecedentes penales a explorar vías de carrera, conectarse con empleadores de segunda oportunidad y acceder a capacitación y aprendizajes registrados después de la liberación. El sitio mapea industrias de alta demanda; navegación de carrera en línea con red estatal de empleadores.',
    'c1000001-0003-4000-8000-000000000001',
    'Virginia',
    'Richmond City',
    'Richmond',
    NULL,
