    'Residentes de Virginia con antecedentes penales que buscan conexiones de empleo y capacitación; abierto a quienes están bajo supervisión.',
    'Launched with VADOC and VCHEP; complements Virginia Career Works center visits; not a job placement guarantee.',
    'Lanzado con VADOC y VCHEP; complementa visitas a centros Virginia Career Works; no garantiza colocación laboral.',
