  (
    'da000001-0263-4000-8000-000000000001',
    'Appalachian Re-Entry Council',
    'The Appalachian Re-Entry Council is a VADOC-facilitated quarterly network in District 18 connecting state agencies, employers, treatment providers, and community organizations serving returning citizens in Dickenson, Lee, Scott, Wise counties and Norton. The council strengthens collaboration and referral pathways for coalfield reentry but does not provide direct cash, housing, or legal representation. Contact the Norton P&P chief to join meetings.',
    'El Consejo de Reinserción Apalache es una red trimestral facilitada por VADOC en el Distrito 18 que conecta agencias estatales, empleadores, proveedores de tratamiento y organizaciones comunitarias que sirven a ciudadanos que regresan en Dickenson, Lee, Scott, Wise y Norton. El consejo fortalece la colaboración pero no ofrece efectivo, vivienda ni representación legal directa.',
    'c1000001-0017-4000-8000-000000000001',
    'Virginia',
    'Wise',
    'Norton',
    '1650 Park Avenue SW',
    '276-679-9201',
    'https://vadoc.virginia.gov/inmates-and-probationers/reentry-resources/',
    NULL,
    'Quarterly virtual meetings; contact for schedule',
    'Open to reentry stakeholders and returning citizens connected through District 18 partners; meetings are quarterly virtual.',
    'Abierto a partes interesadas de reinserción y ciudadanos que regresan conectados a través de aliados del Distrito 18; reuniones trimestrales virtuales.',
    'Contact Chief Jennifer Lester jennifer.lester@vadoc.virginia.gov or 276-365-3339; see VADOC reentry council schedule PDF.',
    'Contacte a la Directora Jennifer Lester jennifer.lester@vadoc.virginia.gov o 276-365-3339; vea el PDF de consejos de reinserción de VADOC.',
    ARRAY['Dickenson', 'Lee', 'Scott', 'Wise', 'Norton'],
