  (
    'da000001-0264-4000-8000-000000000001',
    'Highlands Community Collaboration Council',
    'The Highlands Community Collaboration Council is a voluntary regional reentry and community collaboration network in southwest Virginia addressing housing, substance abuse, employment, and prisoner reentry across Bland, Bristol, Carroll, Grayson, Russell, Smyth, Washington, and Wythe counties. Member agencies coordinate services and identify gaps but the council does not provide direct financial assistance or case management to individuals. Networking body—not a walk-in service center.',
    'El Highlands Community Collaboration Council es una red regional voluntaria de colaboración comunitaria y reinserción en el suroeste de Virginia que aborda vivienda, abuso de sustancias, empleo y reinserción en los condados Bland, Bristol, Carroll, Grayson, Russell, Smyth, Washington y Wythe. Las agencias miembros coordinan servicios pero el consejo no ofrece asistencia financiera directa.',
    'c1000001-0017-4000-8000-000000000001',
