    'Contact member agencies for service hours',
    'Community agencies and justice-involved individuals participate through member organizations; no direct public intake.',
    'Las agencias comunitarias y personas con antecedentes penales participan a través de organizaciones miembros; sin admisión pública directa.',
    'Covers Bristol, Carroll, Grayson, Russell, Smyth, Washington, Wythe; contact member agencies for direct services.',
    'Cubre Bristol, Carroll, Grayson, Russell, Smyth, Washington, Wythe; contacte agencias miembros para servicios directos.',
