  (
    'da000001-0265-4000-8000-000000000001',
    'Feeding Southwest Virginia',
    'Feeding Southwest Virginia distributes more than 20 million pounds of food annually through 400 partner pantries and direct programs across 26 counties and nine cities in southwest Virginia, with distribution centers in Salem and Abingdon serving high-need rural localities including Buchanan, Dickenson, Lee, Norton, and Wise. Mobile pantries, SNAP outreach, and healthcare food partnerships support returning citizens establishing food security. Regional food bank—not a cash assistance office.',
    'Feeding Southwest Virginia distribuye más de 20 millones de libras de alimentos anualmente a través de 400 despensas asociadas y programas directos en 26 condados y nueve ciudades del suroeste de Virginia, con centros en Salem y Abingdon que sirven localidades rurales de alta necesidad incluyendo Buchanan, Dickenson, Lee, Norton y Wise.',
    'c1000001-0007-4000-8000-000000000001',
    'Virginia',
    'Salem',
