    '1025 Electric Road',
    '540-342-3011',
    'https://feedingswva.org',
    NULL,
    'Office Monday–Friday business hours; pantry hours vary',
    'Open to southwest Virginia residents needing food assistance through partner pantries; SNAP help available.',
    'Abierto a residentes del suroeste de Virginia que necesitan asistencia alimentaria a través de despensas asociadas; ayuda SNAP disponible.',
    'Find pantries at feedingswva.org/find-food; Abingdon center at 21452 Gravel Lake Road serves far southwest counties.',
    'Encuentre despensas en feedingswva.org/find-food; centro de Abingdon en 21452 Gravel Lake Road sirve condados del extremo suroeste.',
    ARRAY['Bristol', 'Buchanan', 'Carroll', 'Dickenson', 'Galax', 'Grayson', 'Henry', 'Lee', 'Martinsville', 'Norton', 'Patrick', 'Pittsylvania', 'Pulaski', 'Radford', 'Russell', 'Scott', 'Smyth', 'Tazewell', 'Washington', 'Wise', 'Wythe', 'Danville'],
