  (
    'da000001-0266-4000-8000-000000000001',
    'Blue Ridge Area Food Bank — Lynchburg Branch',
    'Blue Ridge Area Food Bank Lynchburg branch distributes food through hundreds of partner pantries and program sites in Amherst, Appomattox, Bedford, Campbell, and Nelson counties and the city of Lynchburg, helping low-income and justice-involved residents access groceries and SNAP application support across rural Southside communities. Use the online food finder for nearest pantry. Regional food bank hub—not direct walk-in grocery distribution at the branch.',
    'La sucursal de Lynchburg del Blue Ridge Area Food Bank distribuye alimentos a través de cientos de despensas asociadas en los condados Amherst, Appomattox, Bedford, Campbell y Nelson y la ciudad de Lynchburg, ayudando a residentes de bajos ingresos y con antecedentes penales a acceder a comestibles y apoyo para solicitudes SNAP.',
    'c1000001-0007-4000-8000-000000000001',
    'Virginia',
    'Lynchburg',
