  -- source id: 267
  (
    'da000001-0267-4000-8000-000000000001',
    'Valley Mission — Emergency Shelter & Reentry Support',
    'Valley Mission in Staunton operates one of the few shelters within 100 miles that serves single men, single women, and families with 24/7 emergency beds, meals, case management, GED classes, housing-fund assistance, and pastoral counseling. Justice-involved adults returning to Augusta County, Staunton, or Waynesboro can call for bed availability and complete intake with photo ID. Direct shelter and reentry support—not a statewide benefits hotline or legal clinic.',
    'Valley Mission en Staunton opera uno de los pocos refugios en un radio de 100 millas que atiende a hombres solteros, mujeres solteras y familias con camas de emergencia 24/7, comidas, manejo de caso, clases de GED, asistencia para fondos de vivienda y consejería pastoral. Adultos con antecedentes penales que regresan al condado Augusta, Staunton o Waynesboro pueden llamar para disponibilidad de camas y completar la admisión con identificación con foto.',
    'c1000001-0002-4000-8000-000000000001',
    'Virginia',
    'Staunton',
    'Staunton',
    '1513 West Beverley Street',
    '540-886-4673',
    'https://valleymission.net/shelter/',
    NULL,
    'Shelter 24/7; administrative hours Monday–Friday, 8:00 a.m.–4:30 p.m.',
    'Homeless adults and families in Augusta County, Staunton, and Waynesboro; must function independently; children must be with a parent; call ahead for bed availability.',
    'Adultos y familias sin hogar en el condado Augusta, Staunton y Waynesboro; deben funcionar de forma independiente; los niños deben estar con un padre; llame con anticipación para disponibilidad de camas.',
    'Call 540-886-4673 before arriving; bring photo ID; dayroom open Monday–Friday 8 a.m.–5 p.m.; thrift store vouchers available for clothing.',
    'Llame al 540-886-4673 antes de llegar; traiga identificación con foto; sala diurna abierta lunes a viernes de 8 a.m. a 5 p.m.; vales de tienda de segunda mano disponibles para ropa.',
    ARRAY['Augusta', 'Staunton', 'Waynesboro'],
    'multi',
    ARRAY['Emergency shelter', 'Meals', 'Case management', 'GED classes', 'Housing fund assistance', 'Thrift store vouchers'],
    ARRAY['housing', 'emergency-shelter', 'case-management', 'GED', 'Staunton', 'Augusta', 'reentry'],
    ARRAY[]::TEXT[],
    false,
    'active'
  ),
  -- source id: 268
  (
    'da000001-0268-4000-8000-000000000001',
    'Southern Dominion Health System — Lunenburg Medical Center',
    'Southern Dominion Health System operates Lunenburg Medical Center, a Federally Qualified Health Center in Victoria providing primary medical, dental, behavioral health, and sliding-fee care for uninsured and Medicaid patients in Lunenburg County and surrounding Southside communities. Justice-involved adults reestablishing healthcare after release can access same-week appointments, medication assistance, and counseling at the K-V Road clinic. Direct clinical care—not emergency room or SNAP intake.',
    'Southern Dominion Health System opera el Lunenburg Medical Center, un Centro de Salud Calificado Federalmente en Victoria que ofrece atención médica primaria, dental, de salud conductual y tarifas móviles para pacientes sin seguro y Medicaid en el condado Lunenburg y comunidades del Southside. Adultos con antecedentes penales que restablecen atención médica pueden acceder a citas, asistencia con medicamentos y consejería en la clínica de K-V Road.',
    'c1000001-0004-4000-8000-000000000001',
    'Virginia',
    'Lunenburg',
    'Victoria',
    '1508 K-V Road',
    '434-696-2165',
    'https://sdhsinc.com/locations/lunenburg/',
    NULL,
    'Monday–Friday, 8:00 a.m.–5:00 p.m.; Saturday, 8:00 a.m.–12:00 p.m.',
    'Residents of Lunenburg and surrounding Southside localities; sliding-fee scale based on income; Medicaid and Medicare accepted; criminal record not a stated barrier.',
    'Residentes de Lunenburg y localidades del Southside circundante; escala de tarifas según ingresos; se aceptan Medicaid y Medicare; los antecedentes penales no son una barrera indicada.',
    'Call 434-696-2165 for appointments; behavioral health at Lunenburg and Dinwiddie sites; Saturday hours 8 a.m.–12 p.m.',
    'Llame al 434-696-2165 para citas; salud conductual en sitios de Lunenburg y Dinwiddie; horario de sábado de 8 a.m. a 12 p.m.',
    ARRAY['Lunenburg'],
    'single',
    ARRAY['Primary medical care', 'Dental care', 'Behavioral health counseling', 'Sliding-fee program', 'Medication assistance'],
    ARRAY['healthcare', 'FQHC', 'primary-care', 'behavioral-health', 'Lunenburg', 'Southside', 'reentry'],
    ARRAY['accepts_criminal_record'],
    false,
    'active'
