  -- source id: 269
  (
    'da000001-0269-4000-8000-000000000001',
    'Virginia Career Works — South Hill Center',
    'The Virginia Career Works South Hill center connects job seekers in Mecklenburg, Lunenburg, Brunswick, and surrounding South Central Virginia localities to resume help, skills assessments, employer referrals, and WIOA training through the South Central Workforce Development Board. Justice-involved adults on probation or recently released can register on Virginia Workforce Connection for fair-chance job search support and case management when eligible. Workforce center—not emergency housing or legal aid.',
    'El centro Virginia Career Works de South Hill conecta a buscadores de empleo en Mecklenburg, Lunenburg, Brunswick y localidades del sur central de Virginia con ayuda de currículum, evaluaciones de habilidades, referencias a empleadores y capacitación WIOA a través de la Junta de Desarrollo de la Fuerza Laboral del Sur Central. Adultos con antecedentes penales en libertad condicional o recién liberados pueden registrarse en Virginia Workforce Connection.',
    'c1000001-0003-4000-8000-000000000001',
    'Virginia',
    'Mecklenburg',
    'South Hill',
    '118 East Danville Street',
    '434-955-2252',
    'https://www.virginiaworks.gov/local-office/south-hill/',
    NULL,
    'Monday, Wednesday–Friday 8:30 a.m.–4:30 p.m.; Tuesday 9:30 a.m.–4:30 p.m.',
    'Open to South Central Virginia job seekers including justice-involved individuals; veterans receive priority services; register at vawc.virginia.gov.',
    'Abierto a buscadores de empleo del sur central de Virginia incluidas personas con antecedentes penales; veteranos reciben servicios prioritarios; regístrese en vawc.virginia.gov.',
    'Hours Monday, Wednesday–Friday 8:30 a.m.–4:30 p.m., Tuesday 9:30 a.m.–4:30 p.m.; closed lunch 12–1 p.m.; board office in Charlotte Court House 434-542-5871.',
    'Horario lunes y miércoles–viernes 8:30 a.m.–4:30 p.m., martes 9:30 a.m.–4:30 p.m.; cerrado almuerzo 12–1 p.m.; oficina de la junta en Charlotte Court House 434-542-5871.',
    ARRAY['Mecklenburg', 'Lunenburg', 'Brunswick', 'Charlotte', 'Halifax', 'Nottoway'],
