  (
    'da000001-0270-4000-8000-000000000001',
    'Centra Southside Community Hospital',
    'Centra Southside Community Hospital in Farmville is a 100-bed acute care hospital serving Buckingham, Cumberland, Prince Edward, and surrounding South Central Virginia counties with emergency care, inpatient services, primary care referrals, and community health outreach. Returning citizens without a medical home can establish emergency and follow-up care through Centra''s Farmville campus and affiliated primary care practices. Hospital services—not a walk-in SNAP or probation office.',
    'Centra Southside Community Hospital en Farmville es un hospital de cuidados agudos de 100 camas que sirve a Buckingham, Cumberland, Prince Edward y condados del sur central de Virginia con atención de emergencia, servicios hospitalarios, referencias de atención primaria y alcance comunitario. Ciudadanos que regresan sin hogar médico pueden establecer atención de emergencia y seguimiento a través del campus de Farmville de Centra.',
    'c1000001-0004-4000-8000-000000000001',
    'Virginia',
    'Prince Edward',
    'Farmville',
    '800 Oak Street',
    '434-392-8811',
    'https://www.centrahealth.com/locations/centra-southside-community-hospital',
    NULL,
    'Emergency 24/7; hospital and clinic hours vary',
    'Open to residents of South Central Virginia; emergency care regardless of ability to pay; Medicaid and uninsured patients accepted for eligible services.',
    'Abierto a residentes del sur central de Virginia; atención de emergencia independientemente de capacidad de pago; pacientes Medicaid y sin seguro aceptados para servicios elegibles.',
    'Emergency department 24/7; main switchboard 434-392-8811; Centra primary care practices throughout Farmville and Buckingham County.',
    'Departamento de emergencias 24/7; conmutador principal 434-392-8811; prácticas de atención primaria de Centra en Farmville y el condado Buckingham.',
    ARRAY['Buckingham', 'Cumberland', 'Prince Edward', 'Charlotte', 'Lunenburg'],
