  -- source id: 271
  (
    'da000001-0271-4000-8000-000000000001',
    'People Inc. — Clarke County Community Action',
    'People Inc. is the community action agency serving Clarke, Frederick, Page, Shenandoah, and Warren counties with emergency assistance for rent, utilities, food, and clothing plus long-term self-sufficiency programs for low-income families. Justice-involved adults returning to Clarke County can apply for crisis assistance and connect to regional housing, employment, and benefits partners through the Berryville office. Direct assistance programs—not a statewide legal aid intake line.',
    'People Inc. es la agencia de acción comunitaria que sirve a los condados Clarke, Frederick, Page, Shenandoah y Warren con asistencia de emergencia para renta, servicios públicos, alimentos y ropa, además de programas de autosuficiencia para familias de bajos ingresos. Adultos con antecedentes penales que regresan al condado Clarke pueden solicitar asistencia en crisis y conectarse con aliados regionales de vivienda, empleo y beneficios.',
    'c1000001-0015-4000-8000-000000000001',
    'Virginia',
    'Clarke',
